import{_ as n,o as r,c as s,a3 as a,j as o,a as t,t as d}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Changelog | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/changelog/"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Changelog | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/changelog/"}]]},"headers":[],"relativePath":"changelog/index.md","filePath":"changelog/index.md","lastUpdated":1786061750000}'),l={name:"changelog/index.md"};function c(i,e,u,p,m,g){return r(),s("div",null,[e[4]||(e[4]=a('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="announcements-module-2026-08-07" tabindex="-1">Announcements module (2026-08-07) <a class="header-anchor" href="#announcements-module-2026-08-07" aria-label="Permalink to &quot;Announcements module (2026-08-07)&quot;">​</a></h2><p>Free Communication Marketplace module (<code>announcements</code>: not default-included, not billable) for workspace announcements with read tracking.</p><ul><li>Post-login unread dialog for every signed-in user when the module is installed (<strong>no</strong> <code>announcements.view</code> permission)</li><li>Dashboard announcements section after the welcome greeting (<strong>unread only</strong>; hidden when empty or all read)</li><li>Admin CRUD with <code>create</code> / <code>update</code> / <code>delete</code> / <code>restore</code> / <code>force.delete</code>; readers list via <code>view_reads</code> (first/last read + IP)</li><li>Publish fans out in-app notification <code>type: announcement</code></li><li>Pest <code>AnnouncementTest</code> (incl. validation + non-UTC expiry) + Playwright <code>test:e2e:announcements</code></li><li>Docs: user / developer / deployment / API + database dictionary</li><li>Production hardening: unread-only dashboard Mark as read, queued publish fan-out, UTC expiry scope, workspace-timezone form helpers</li></ul><h2 id="connectivity-banner-—-offline-restored-2026-08-07" tabindex="-1">Connectivity banner — offline / restored (2026-08-07) <a class="header-anchor" href="#connectivity-banner-—-offline-restored-2026-08-07" aria-label="Permalink to &quot;Connectivity banner — offline / restored (2026-08-07)&quot;">​</a></h2><ul><li>SPA and marketing site show a sticky top banner when the browser goes offline (“You are currently offline”) and a short green “connection was restored” notice when it comes back</li></ul><h2 id="email-—-connect-smtp-ip-note-2026-08-07" tabindex="-1">Email — connect SMTP IP note (2026-08-07) <a class="header-anchor" href="#email-—-connect-smtp-ip-note-2026-08-07" aria-label="Permalink to &quot;Email — connect SMTP IP note (2026-08-07)&quot;">​</a></h2><ul><li>Connect mailbox dialog and user guide note that the mail provider must allow SMTP from the application server IP (587/465) for Test and send</li></ul><h2 id="email-—-security-harden-docs-honesty-2026-08-06" tabindex="-1">Email — security harden + docs honesty (2026-08-06) <a class="header-anchor" href="#email-—-security-harden-docs-honesty-2026-08-06" aria-label="Permalink to &quot;Email — security harden + docs honesty (2026-08-06)&quot;">​</a></h2><ul><li>Reading pane sanitizes HTML bodies with DOMPurify before render</li><li>CRM link API authorizes <code>view</code> on the target Lead/Contact/Company/Opportunity</li><li>Docs demote attachment download/storage and CRM linking UI (API/schema only in v1)</li></ul><h2 id="email-—-per-mailbox-sync-interval-2026-08-06" tabindex="-1">Email — per-mailbox sync interval (2026-08-06) <a class="header-anchor" href="#email-—-per-mailbox-sync-interval-2026-08-06" aria-label="Permalink to &quot;Email — per-mailbox sync interval (2026-08-06)&quot;">​</a></h2><ul><li>Each connected mailbox has <strong>Auto-sync interval</strong> (default <strong>5 minutes</strong>; 5 / 10 / 15 / 30 / 60)</li><li>Scheduler runs <code>email:sync</code> every minute and only queues jobs for due mailboxes; <strong>Sync</strong> button still forces an immediate sync</li><li>Forge: dedicated <code>email-sync</code> queue daemon documented separately from <code>emails,default</code></li><li>Docs: user guide, API, deployment, Laravel Forge</li></ul><h2 id="email-—-rich-text-compose-2026-08-06" tabindex="-1">Email — rich text compose (2026-08-06) <a class="header-anchor" href="#email-—-rich-text-compose-2026-08-06" aria-label="Permalink to &quot;Email — rich text compose (2026-08-06)&quot;">​</a></h2><ul><li>Compose, Reply, Forward, Templates, and Signatures use a TipTap rich text editor (bold, italic, underline, lists, link, text color)</li><li>Reply/Forward quote the original message as rendered HTML instead of showing source in a raw textarea</li><li>Docs: user guide + developer guide editor notes</li></ul><h2 id="email-—-reply-move-trash-2026-08-06" tabindex="-1">Email — reply, move, trash (2026-08-06) <a class="header-anchor" href="#email-—-reply-move-trash-2026-08-06" aria-label="Permalink to &quot;Email — reply, move, trash (2026-08-06)&quot;">​</a></h2><ul><li>Reading pane: <strong>Reply</strong>, <strong>Forward</strong>, and <strong>Move to</strong> folder actions</li><li>Delete moves the message to <strong>Trash</strong> (IMAP) when a trash folder exists; delete again permanently removes it</li><li>Compose sends <code>in_reply_to</code> / <code>thread_key</code> for replies</li><li>Docs: user guide + tenant API behavior notes</li></ul><h2 id="email-module-—-personal-imap-smtp-2026-08-06" tabindex="-1">Email module — personal IMAP/SMTP (2026-08-06) <a class="header-anchor" href="#email-module-—-personal-imap-smtp-2026-08-06" aria-label="Permalink to &quot;Email module — personal IMAP/SMTP (2026-08-06)&quot;">​</a></h2>',17)),o("p",null,[e[0]||(e[0]=t("Free Communication Marketplace module for a ",-1)),e[1]||(e[1]=o("strong",null,"personal",-1)),e[2]||(e[2]=t(" mailbox inside EloSync (Inbox/folders, compose/drafts/sent, templates with ",-1)),o("code",null,d(i.variables),1),e[3]||(e[3]=t(", signatures). CRM link API and attachment schema are present; SPA linking UI and attachment file sync are deferred.",-1))]),e[5]||(e[5]=a('<ul><li>Catalog: slug <code>email</code>, <code>is_default_included=false</code>, <code>is_billable=false</code>, prices <code>$0</code> (not auto-installed)</li><li>Connect via IMAP/SMTP credentials with Gmail/Outlook <strong>app password</strong> presets — <strong>no OAuth</strong> in v1</li><li>Sync/send jobs on dedicated <code>email-sync</code> queue; scheduler <code>email:sync</code> every five minutes; requires PHP <code>ext-imap</code></li><li>Fully separate from Settings → Mail / <code>EmailConfigResolver</code> (platform transactional mail) and from Communication Templates (WhatsApp plain-text)</li><li>Personal isolation enforced in policies; Spa <code>/email</code> + Playwright <code>test:e2e:email</code></li><li>Docs: user, developer, API, and deployment guides</li></ul><h2 id="phase-1-—-resellers-reseller-payouts-2026-08-06" tabindex="-1">Phase 1 — Resellers + Reseller Payouts (2026-08-06) <a class="header-anchor" href="#phase-1-—-resellers-reseller-payouts-2026-08-06" aria-label="Permalink to &quot;Phase 1 — Resellers + Reseller Payouts (2026-08-06)&quot;">​</a></h2><p>Free Sales Marketplace modules for partner accounts and a two-tier commission ledger on fully <strong>Paid</strong> customer invoices.</p><ul><li><strong>Resellers</strong> (<code>resellers</code>): partner directory with <code>commission_rate</code> / <code>owner_commission_rate</code>, assignee scoping, soft delete, same-workspace <strong>invite-login</strong> (protected <code>reseller</code> role only), Vendor-parity <strong>threaded notes</strong> (<code>note_entries</code> / <code>reseller_notes</code>) and <strong>domain activity</strong> timeline (<code>reseller_activities</code>). Hard dependency on <strong>Payments</strong>. Catalog: <code>is_default_included=false</code>, <code>is_billable=false</code>, category <code>sales</code>, <code>sort_order=70</code>.</li><li><strong>Reseller Payouts</strong> (<code>reseller-payouts</code>): <code>reseller_commission_entries</code> accrued on <code>CustomerInvoiceBecamePaid</code> (not Partial); formula <code>resellerCut = T×R%</code>, <code>ownerCut = (T−resellerCut)×O%</code>; approve → pay / void. <strong>Pay → void payment → pay again</strong> revives void ledger rows to accrued with refreshed snapshots. Hard dependency on <strong>Resellers</strong>. Catalog: same free Sales flags, <code>sort_order=80</code>.</li><li>Invoice link: nullable <code>customer_invoices.reseller_id</code> (+ <code>LinkableReseller</code>).</li><li>SPA: Resellers list + detail sheet tabs Overview | Notes | Activity | Access; Reseller Payouts ledger workflow.</li><li><strong>Deferred:</strong> cross-workspace identity (each tenant manages its own reseller logins; no Central multi-tenant reseller person).</li><li>Docs: user/developer/deployment/API guides + module-dependencies + database dictionary.</li><li>Finance ops: voiding a posted payment voids <strong>all</strong> commission rows for that invoice (including already <code>paid</code>); re-paying revives them to <code>accrued</code>.</li></ul><h2 id="fix-—-leads-ops-merge-readiness-audit-2026-08-06" tabindex="-1">Fix — Leads Ops merge-readiness audit (2026-08-06) <a class="header-anchor" href="#fix-—-leads-ops-merge-readiness-audit-2026-08-06" aria-label="Permalink to &quot;Fix — Leads Ops merge-readiness audit (2026-08-06)&quot;">​</a></h2><p>Pre-merge fixes from security/bug audit on <code>feature/leads-operations</code>:</p><ul><li>Persist <strong>Receive website leads</strong> on user <strong>update</strong> (<code>UpdateTenantUserRequest</code>)</li><li>Snapshot <strong>commission rate</strong> when <code>assigned_to</code> changes via <code>PUT /leads/{id}</code> (not only <code>/assign</code>)</li><li>Import <strong>Update</strong> mode no longer self-matches as a same-day duplicate; Skip/create still notify; preview write-gated</li><li>Department weekly digest week bounds use each tenant’s workspace timezone after <code>applyRuntimeConfig</code></li><li>SPA: refresh <code>/me</code> after department save so <code>is_department_manager</code> unlocks equal import / reports without reload; edit lead omits forced <code>lead_type: direct</code> for legacy null rows</li><li>Docs corrections: eligible assignees vs website flag, digest schedule timezone, <code>dashboard.view</code>, current-stage metrics, <code>lead_commission_rate</code> / <code>department_weekly</code> in database dictionary</li></ul><h2 id="fix-—-leads-playwright-coverage-for-ops-gates-2026-08-05" tabindex="-1">Fix — Leads Playwright coverage for Ops gates (2026-08-05) <a class="header-anchor" href="#fix-—-leads-playwright-coverage-for-ops-gates-2026-08-05" aria-label="Permalink to &quot;Fix — Leads Playwright coverage for Ops gates (2026-08-05)&quot;">​</a></h2><p>Headed <code>test:e2e:leads</code> updates for Lead Ops:</p><ul><li>Create-lead helpers target the <strong>Company</strong> textbox exactly so the <strong>Company Lead</strong> system tag does not collide</li><li>Import keep-duplicate flow restored (was referencing an undefined locator)</li><li>Equal-distribute e2e asserts the radio is disabled for non–department-manager owners, and runs a manager path with Departments + a staff member in the managed department</li><li>Integrations waits for webhook endpoints to finish loading before create</li></ul><p>Requires a local queue worker on <code>imports</code> (and usually <code>emails</code>) so import jobs leave <code>queued</code>.</p><h2 id="fix-—-lead-inactivity-setting-save-2026-08-05" tabindex="-1">Fix — lead inactivity setting save (2026-08-05) <a class="header-anchor" href="#fix-—-lead-inactivity-setting-save-2026-08-05" aria-label="Permalink to &quot;Fix — lead inactivity setting save (2026-08-05)&quot;">​</a></h2><p>Settings → Leads <strong>Inactivity alert (working days)</strong> did not persist overrides and did not surface validation errors. The form field used a dotted React Hook Form name (<code>leads.inactivity_working_days</code>), which nested into <code>dirtyFields</code> / <code>errors</code> and skipped the update payload. Renamed the form field to <code>leads_inactivity_working_days</code> and map to API key <code>leads.inactivity_working_days</code> on save.</p><h2 id="lead-inactivity-alerts-2026-08-05" tabindex="-1">Lead inactivity alerts (2026-08-05) <a class="header-anchor" href="#lead-inactivity-alerts-2026-08-05" aria-label="Permalink to &quot;Lead inactivity alerts (2026-08-05)&quot;">​</a></h2><p>Assigned open leads (not in Won/Lost stages) trigger daily inactivity alerts when no <strong>meaningful</strong> activity occurs for the configured number of <strong>Mon–Sat working days</strong> (workspace timezone; Sundays excluded). Default threshold: <strong>3</strong> (<code>leads.inactivity_working_days</code>). Meaningful types: notes, follow-ups, stage/status changes, CRM activities, tag changes. Assignment/import/create alone do not reset the timer.</p><ul><li>Assignee receives <code>lead.inactive</code>; department managers of the assignee receive <code>lead.inactive_escalation</code> (workspace owners when no managers).</li><li>Backend: <code>LeadInactivityService</code>, <code>leads:notify-inactive</code> (daily schedule), <code>NotificationIdempotency</code>, Pest <code>LeadInactiveNotificationTest</code></li><li>Frontend: Settings → Leads tab; notification registry entries</li><li>Docs: Leads user + developer guides</li></ul><h2 id="department-performance-reports-weekly-digest-2026-08-05" tabindex="-1">Department performance reports + weekly digest (2026-08-05) <a class="header-anchor" href="#department-performance-reports-weekly-digest-2026-08-05" aria-label="Permalink to &quot;Department performance reports + weekly digest (2026-08-05)&quot;">​</a></h2><p>Workspace owners and department managers get an in-app <strong>Department reports</strong> page (<code>/reports/departments</code>) with leads open/won/lost and tasks open/completed by department for a selected period. Metrics join assignees via <code>department_user</code> membership (plus linked employees and manager). A weekly scheduled command sends database + email digest notifications to owners and managers.</p><ul><li>Backend: <code>DepartmentPerformanceReportService</code>, <code>GET /reports/department-performance</code>, <code>reports:send-department-digest</code>, <code>DepartmentPerformanceDigestNotification</code>, Pest authz + metrics + digest tests</li><li>Frontend: HR nav item (owner or <code>is_department_manager</code>), period filters, summary cards + table</li><li>Docs: tenant reports API, Departments user + developer guides</li></ul><h2 id="same-day-duplicate-leads-—-notify-duplicate-tag-2026-08-05" tabindex="-1">Same-day duplicate leads — notify + Duplicate tag (2026-08-05) <a class="header-anchor" href="#same-day-duplicate-leads-—-notify-duplicate-tag-2026-08-05" aria-label="Permalink to &quot;Same-day duplicate leads — notify + Duplicate tag (2026-08-05)&quot;">​</a></h2><p>When email or phone matches another lead created the <strong>same workspace calendar day</strong> (Settings → General timezone), EloSync applies the protected <strong>Duplicate</strong> system tag and sends <code>lead.duplicate_detected</code> notifications to the existing lead’s assignee, creator, and the actor (importer or manual creator). Import duplicate mode (<strong>Skip</strong> / <strong>Update</strong> / <strong>Keep</strong>) is unchanged; tagging and notifications still run for same-day matches. Inbound ingest skips still tag and notify when the match is same-day.</p><ul><li>Backend: <code>LeadDuplicateService::findSameDayByContactFields</code>, <code>LeadSameDayDuplicateService</code>, <code>LeadDuplicateDetected</code> event + notification, hooks in <code>LeadService</code>, <code>ImportManager</code>, <code>LeadIngestionService</code>, Pest <code>LeadSameDayDuplicateTest</code> (non-UTC day boundary)</li><li>Frontend: notification registry entry <code>lead.duplicate_detected</code></li><li>Docs: Leads user + developer guides</li></ul><h2 id="website-lead-recipient-pool-2026-08-05" tabindex="-1">Website lead recipient pool (2026-08-05) <a class="header-anchor" href="#website-lead-recipient-pool-2026-08-05" aria-label="Permalink to &quot;Website lead recipient pool (2026-08-05)&quot;">​</a></h2><p>Custom webhook endpoints can <strong>assign to website recipients</strong> after ingest. Users opt in with <strong>Receive website leads</strong> (<code>receive_website_leads</code>). Eligible assignees in that pool receive equal distribution; empty pool leaves the lead unassigned and writes a platform audit event. Meta Lead Ads is not part of this pool.</p><ul><li>Backend: migrations, <code>LeadBulkAssignmentService::eligibleAssigneesForWebsite</code>, post-create assign in <code>LeadIngestionService</code>, <code>NotificationSourceEnum::Webhook</code>, Pest <code>LeadCustomWebhookTest</code></li><li>Frontend: user flag toggle; webhook endpoint toggle under Leads → Integrations</li><li>Docs: Users API, Custom Lead Webhook, Leads developer guide</li></ul><h2 id="lead-type-direct-company-2026-08-05" tabindex="-1">Lead type Direct / Company (2026-08-05) <a class="header-anchor" href="#lead-type-direct-company-2026-08-05" aria-label="Permalink to &quot;Lead type Direct / Company (2026-08-05)&quot;">​</a></h2><p>Leads now have a first-class <strong>lead type</strong> (<code>direct</code> | <code>company</code>), required when creating or updating via the API and lead form. Legacy rows may still have a null type until edited.</p><ul><li><p>System tags <strong>Direct Lead</strong> / <strong>Company Lead</strong> are seeded and kept mutually exclusive with the stored type</p></li><li><p>Import mapping adds optional <strong>Lead Type</strong> column (defaults to <code>direct</code> when unmapped)</p></li><li><p>Table, board cards, and detail drawer show lead type</p></li><li><p>Backend: <code>LeadTypeEnum</code>, <code>leads.lead_type</code> migration, tag sync in <code>LeadService</code> / <code>LeadTagService</code>, Pest <code>LeadTypeTest</code></p></li><li><p>Frontend: lead form select, import field list, list/detail/board display</p></li><li><p>Docs: Leads user + developer guides, tenant leads API</p></li></ul><h2 id="lead-commission-rate-snapshot-2026-08-05" tabindex="-1">Lead commission rate snapshot (2026-08-05) <a class="header-anchor" href="#lead-commission-rate-snapshot-2026-08-05" aria-label="Permalink to &quot;Lead commission rate snapshot (2026-08-05)&quot;">​</a></h2><p>Workspace users can have an optional <strong>Default lead commission %</strong> (<code>users.lead_commission_rate</code>). When a lead is assigned or reassigned via <code>POST /leads/{id}/assign</code>, the assignee’s rate is copied to <code>leads.commission_rate</code>; unassign clears it. Display and export only — no payout calculations.</p><ul><li>Backend: migrations, <code>TenantUserService</code>, <code>LeadService::assign</code>, API resources, CSV/XLSX export column, Pest <code>LeadCommissionRateTest</code></li><li>Frontend: Users create/edit field; read-only commission on lead list (when assigned) and detail drawer</li><li>Docs: Users API, Leads developer + user guides</li></ul><h2 id="import-equal-distribute-scoped-to-managed-departments-2026-08-05" tabindex="-1">Import equal distribute scoped to managed departments (2026-08-05) <a class="header-anchor" href="#import-equal-distribute-scoped-to-managed-departments-2026-08-05" aria-label="Permalink to &quot;Import equal distribute scoped to managed departments (2026-08-05)&quot;">​</a></h2><p>Lead import <strong>Automatically distribute</strong> is limited to department managers. Eligible assignees are drawn only from members of active departments where the importer is <code>manager_id</code>. Non-managers cannot select the mode (API 422 + SPA disable). Bulk equal distribute is unchanged (org-wide). Login <code>/me</code> include <code>is_department_manager</code>.</p><h2 id="lead-high-priority-dashboard-chip-2026-08-05" tabindex="-1">Lead High Priority dashboard chip (2026-08-05) <a class="header-anchor" href="#lead-high-priority-dashboard-chip-2026-08-05" aria-label="Permalink to &quot;Lead High Priority dashboard chip (2026-08-05)&quot;">​</a></h2><p>Staff with <strong>leads.update</strong> can toggle <strong>High Priority</strong> from the lead detail drawer. The Dashboard <strong>High Priority</strong> widget lists open-pipeline leads with priority <strong>High</strong> only.</p><p><strong>Behavior notes</strong></p><ul><li><p>Clearing the chip restores the previous priority when the chip was used to mark High in that browser tab (for example Urgent → High → Urgent). Otherwise clear falls back to Medium.</p></li><li><p><strong>Breaking (dashboard):</strong> Urgent open leads no longer appear on the High Priority widget. Use Leads filters for Urgent, or mark the lead High to surface it on the dashboard card.</p></li><li><p>Backend: <code>high_priority</code> widget filter + Pest coverage</p></li><li><p>Frontend: Overview chip with priority restore; Playwright pipeline flow asserts chip, dashboard card, and Urgent restore</p></li><li><p>Docs: Leads / tenant application user guide, <a href="/api/tenant-v1-dashboard">Dashboard API</a></p></li></ul><h2 id="docs-production-build-unblock-2026-08-05" tabindex="-1">Docs production build unblock (2026-08-05) <a class="header-anchor" href="#docs-production-build-unblock-2026-08-05" aria-label="Permalink to &quot;Docs production build unblock (2026-08-05)&quot;">​</a></h2><p>Docs CI publish to <code>build-artifacts</code> was failing the artifact secret scan on a placeholder FCM PEM example in <a href="/deployment/notifications">Push notifications</a>. The example no longer uses PEM armor headers, and the scanner only flags PEM headers that are followed by real base64 key material.</p><h2 id="lead-tags-contacts-on-off-boarded-2026-08-05" tabindex="-1">Lead tags + Contacts On/Off Boarded (2026-08-05) <a class="header-anchor" href="#lead-tags-contacts-on-off-boarded-2026-08-05" aria-label="Permalink to &quot;Lead tags + Contacts On/Off Boarded (2026-08-05)&quot;">​</a></h2><p>Multi-select disposition <strong>tags</strong> on Leads (full catalog CRUD + sort order), seeded defaults (Not Contacted, Contacted, No Response with per-tag auto follow-up days, Invalid Number, Not Interested, Not Applied, Follow Up Later with forced follow-up), badges on board/table/detail/forms, and filter by tag. Tags never change pipeline stage or lead status.</p><p>Contacts gain a lifecycle field separate from soft-delete: <strong>On Boarded Clients</strong> / <strong>Off Boarded Clients</strong> (KPIs, filters, form, detail). Lead convert defaults new contacts to on boarded. Trash wording (<strong>Active only</strong>) is unchanged.</p><ul><li>Backend: <code>lead_tags</code> + pivot, <code>PUT /leads/{id}/tags</code>, tag reorder/CRUD, <code>contacts.lifecycle_status</code>, Pest coverage</li><li>Frontend: Manage tags dialog, tag picker + force follow-up UX, contacts lifecycle UI; Playwright <code>leads.tags.spec.ts</code></li><li>Docs: Leads/Contacts user + API + developer guides</li></ul><h2 id="tenant-user-impersonation-2026-08-05" tabindex="-1">Tenant user impersonation (2026-08-05) <a class="header-anchor" href="#tenant-user-impersonation-2026-08-05" aria-label="Permalink to &quot;Tenant user impersonation (2026-08-05)&quot;">​</a></h2><p>Same-workspace <strong>Login as user</strong> for Owners (permission <code>users.impersonate</code>): Users row menu → reason dialog → amber banner → <strong>End impersonation</strong> restores the actor session. Targets cannot be self or workspace Owner; nested impersonation is blocked. Central platform impersonation is unchanged.</p><p>Hardening: one active session per actor (prior target PAT revoked), revoke PAT on session delete, reject soft-deleted targets, persist impersonation metadata in <code>sessionStorage</code> for refresh/banner restore.</p><p>Platform CI note: Laravel 13 <code>#[AsCommand(name: &#39;db:seed&#39;)]</code> made stancl/tenancy’s <code>Seed</code> command clobber core <code>db:seed</code> (missing <code>--tenants</code> → Pest suite red). Backend re-registers framework <code>SeedCommand</code> after package boot.</p><ul><li>Backend: <code>user_impersonation_sessions</code>, <code>POST /users/{user}/impersonate</code>, <code>POST /user-impersonation/{id}/end</code>, additive permission sync</li><li>Frontend: auth-store modes (<code>central</code> / <code>tenant-user</code>), Users dialog, AppLayout end routing; Playwright <code>users.impersonate.spec.ts</code> (tenant project)</li><li>Docs: <a href="/api/tenant-v1-users#user-impersonation-login-as-user">Tenant Users API</a>, <a href="/developer-guide/authentication#impersonation-compatibility">Authentication</a>, <a href="/user-guide/tenant-rbac">Tenant RBAC</a></li></ul><h2 id="rotating-dashboard-inspire-taglines-2026-08-05" tabindex="-1">Rotating dashboard inspire taglines (2026-08-05) <a class="header-anchor" href="#rotating-dashboard-inspire-taglines-2026-08-05" aria-label="Permalink to &quot;Rotating dashboard inspire taglines (2026-08-05)&quot;">​</a></h2><p>Central and tenant dashboards show a short curated inspirational line under the welcome greeting. A new line is picked on each visit (session-aware so the same line is not repeated back-to-back).</p><h2 id="board-drag-and-drop-auto-saves-2026-08-03" tabindex="-1">Board drag-and-drop auto-saves (2026-08-03) <a class="header-anchor" href="#board-drag-and-drop-auto-saves-2026-08-03" aria-label="Permalink to &quot;Board drag-and-drop auto-saves (2026-08-03)&quot;">​</a></h2><p>Kanban drag-and-drop on <strong>Leads</strong>, <strong>Opportunities</strong>, <strong>Tasks</strong>, and <strong>ToDos</strong> now saves the stage/status immediately (same as Calendar reschedule). Dropping a card no longer opens the detail drawer; click still opens it for edits. Cards without update permission remain view-only (non-draggable).</p><h2 id="role-permissions-filtered-by-installed-modules-2026-08-03" tabindex="-1">Role permissions filtered by installed modules (2026-08-03) <a class="header-anchor" href="#role-permissions-filtered-by-installed-modules-2026-08-03" aria-label="Permalink to &quot;Role permissions filtered by installed modules (2026-08-03)&quot;">​</a></h2><p>Tenant <strong>Roles</strong> edit and the <strong>Permissions matrix</strong> only show core administration permissions plus groups for modules the workspace currently owns. Assigning a permission for an uninstalled module is rejected. Existing grants for a module that was later removed stay in the database (so reinstall can restore prior access) but stay hidden from the UI until the module is installed again.</p><h2 id="module-product-tours-phase-5-2026-08-03" tabindex="-1">Module product tours (Phase 5) (2026-08-03) <a class="header-anchor" href="#module-product-tours-phase-5-2026-08-03" aria-label="Permalink to &quot;Module product tours (Phase 5) (2026-08-03)&quot;">​</a></h2><p>Every tenant module list page includes a short product tour (driver.js) explaining how the module works.</p><ul><li>PageHeader help icon (<code>tourId</code>) — always re-runnable; first visit auto-prompts once via <code>localStorage</code></li><li>Shared helper + per-module step configs under <code>SaaS-Frontend/src/tours/</code> (Leads is the blueprint)</li><li>Wired for nav modules: CRM, sales, billing, purchasing, inventory, accounting, financial reports, and HR (employees, departments, leave, attendance, payroll)</li><li>Docs: <a href="/developer-guide/module-tours">Module Tours</a>; brief note in <a href="/user-guide/shared-layout">Shared Layout</a></li></ul><h2 id="native-fcm-channel-device-tokens-phase-4b-2026-08-03" tabindex="-1">Native FCM channel + device tokens (Phase 4b) (2026-08-03) <a class="header-anchor" href="#native-fcm-channel-device-tokens-phase-4b-2026-08-03" aria-label="Permalink to &quot;Native FCM channel + device tokens (Phase 4b) (2026-08-03)&quot;">​</a></h2><p>Additive Firebase Cloud Messaging HTTP v1 delivery for closed/background devices, using the same <code>PlatformNotificationPayload</code> mapper as VAPID Web Push. No parallel notification framework; Firebase remains optional for local/dev.</p><ul><li>Backend: <code>FcmChannel</code>, <code>fcm_device_tokens</code> register/unregister API, env-based service-account credentials (<code>FCM_*</code>), graceful skip when unconfigured</li><li>Shared wake trait: existing <code>SendsWebPushNotification</code> / <code>withWebPushChannel()</code> also enqueues FCM (including mention notifications)</li><li>Frontend: registers an FCM web token when complete <code>VITE_FIREBASE_*</code> config is present; VAPID path unchanged</li><li>Docs: deployment secrets + Forge checklist, architecture channels table, tenant API surface</li></ul><h2 id="web-push-hardened-vapid-phase-4a-2026-08-03" tabindex="-1">Web Push hardened (VAPID Phase 4a) (2026-08-03) <a class="header-anchor" href="#web-push-hardened-vapid-phase-4a-2026-08-03" aria-label="Permalink to &quot;Web Push hardened (VAPID Phase 4a) (2026-08-03)&quot;">​</a></h2><p>Standards browser Web Push is production-hardened for all existing notification types (including mentions).</p><ul><li>Ops: deploy docs require <code>VAPID_SUBJECT</code> / <code>VAPID_PUBLIC_KEY</code> / <code>VAPID_PRIVATE_KEY</code> and a supervised <code>emails,default</code> queue worker (Web Push rides the same notification jobs)</li><li>Reliability: expired endpoints (<code>404</code>/<code>410</code>) pruned; SW registers with <code>updateViaCache: &#39;none&#39;</code>, activates immediately, and re-syncs on <code>pushsubscriptionchange</code>; Profile / Notification Center prompt when re-subscribe is needed</li><li>Click → HashRouter deep link via <code>PlatformNotificationPayloadMapper</code> <code>url</code></li><li>Channel skips cleanly when VAPID is unconfigured (database + Reverb unaffected)</li></ul><h2 id="mentions-on-lead-task-notes-2026-08-03" tabindex="-1">@mentions on Lead/Task notes (2026-08-03) <a class="header-anchor" href="#mentions-on-lead-task-notes-2026-08-03" aria-label="Permalink to &quot;@mentions on Lead/Task notes (2026-08-03)&quot;">​</a></h2><p>Mention teammates in <strong>Lead notes</strong> and <strong>Task comments</strong> with <code>@</code> autocomplete. Stable body syntax <code>@[Display Name](user:ID)</code> persists mention rows (<code>lead_note_mentions</code> / <code>task_note_mentions</code>) and notifies the mentioned user (skip self; idempotent per note+user).</p><ul><li>Types: <code>lead.mentioned</code> (database + broadcast + web push) / <code>task.mentioned</code> (database + web push)</li><li>Optional mail gated by Settings → Notifications toggles <code>lead_mentioned</code> / <code>task_mentioned</code> (default off)</li><li>SPA registry routes to the lead/task detail sheet; composer shared on lead Notes and task Comments tabs</li></ul><h2 id="leave-self-service-salary-deduction-on-approve-2026-08-03" tabindex="-1">Leave self-service + salary deduction on approve (2026-08-03) <a class="header-anchor" href="#leave-self-service-salary-deduction-on-approve-2026-08-03" aria-label="Permalink to &quot;Leave self-service + salary deduction on approve (2026-08-03)&quot;">​</a></h2><p>Staff (and managers) submit leave only for their linked active employee; admin/superadmin may create on behalf of others. Managers still approve others’ pending requests. Reject requires <code>review_notes</code>. Approve accepts optional <code>deduct_salary</code> (default <code>!leaveType.is_paid</code>); overriding the default requires notes. Payroll <code>PayPeriodCalculator</code> uses <code>deduct_salary</code> (legacy null rows fall back to <code>!is_paid</code>). Default staff role gains <code>leave-management.create</code> + <code>leave-management.update</code> (additive sync).</p><h2 id="leave-catalog-authz-2026-08-03" tabindex="-1">Leave catalog authz (2026-08-03) <a class="header-anchor" href="#leave-catalog-authz-2026-08-03" aria-label="Permalink to &quot;Leave catalog authz (2026-08-03)&quot;">​</a></h2><p>Staff <code>leave-management.create</code> / <code>update</code> remain for <strong>leave requests</strong> only. Leave <strong>types</strong> and <strong>balances</strong> writes require admin/owner. Staff balance lists are scoped to self; managers may view for review.</p><h2 id="attendance-self-service-production-hardening-2026-08-03" tabindex="-1">Attendance self-service production hardening (2026-08-03) <a class="header-anchor" href="#attendance-self-service-production-hardening-2026-08-03" aria-label="Permalink to &quot;Attendance self-service production hardening (2026-08-03)&quot;">​</a></h2><ul><li>Staff cannot change attendance <code>status</code> (manager/admin only); self marks force Present</li><li>Login and <code>/me</code> include <code>employee_id</code> for self-service UX</li><li>Managers cannot approve their own leave requests</li><li>Self check-in/out uses workspace timezone</li></ul><h2 id="attendance-self-service-2026-08-03" tabindex="-1">Attendance self-service (2026-08-03) <a class="header-anchor" href="#attendance-self-service-2026-08-03" aria-label="Permalink to &quot;Attendance self-service (2026-08-03)&quot;">​</a></h2><p>Staff linked to an active employee can mark their own attendance and check out; managers/admins can mark anyone and correct times/notes. Login auto check-in is unchanged. Staff lists are scoped to their own records. Default staff role gains <code>attendance.create</code> + <code>attendance.update</code> (additive sync for existing workspaces).</p><h2 id="profile-avatar-upload-2026-08-03" tabindex="-1">Profile avatar upload (2026-08-03) <a class="header-anchor" href="#profile-avatar-upload-2026-08-03" aria-label="Permalink to &quot;Profile avatar upload (2026-08-03)&quot;">​</a></h2><p>Users can upload a profile picture on <strong>Profile</strong> (Central and Tenant). The photo replaces initials in the topbar user menu and sidebar account chip.</p><ul><li><code>POST/DELETE /api/{central|tenant}/v1/me/avatar</code> (multipart <code>file</code>: jpg/png/webp, max 2 MB)</li><li>Login and <code>/me</code> payloads include nullable absolute <code>avatar_url</code> (API origin <code>/storage/...</code>)</li><li>Avatars always store on the <code>public</code> disk (<code>FILESYSTEM_AVATAR_DISK</code>, default <code>public</code>) — never S3, even when <code>FILESYSTEM_DISK=s3</code></li><li><code>storage:migrate-to-s3</code> skips <code>/avatars/</code> keys so profile photos stay on local public storage</li><li>Persist <code>storage/app/public</code> across zero-downtime deploys (Forge shared storage) so avatars survive releases</li><li>Tenant <code>users.avatar_path</code> column added; central already had <code>avatar_path</code></li><li>SPA resolves relative asset URLs against the API host so Vite/dev origins still show the photo</li></ul><h2 id="compact-ui-density-keyboard-shortcuts-2026-08-03" tabindex="-1">Compact UI density + keyboard shortcuts (2026-08-03) <a class="header-anchor" href="#compact-ui-density-keyboard-shortcuts-2026-08-03" aria-label="Permalink to &quot;Compact UI density + keyboard shortcuts (2026-08-03)&quot;">​</a></h2><p><strong>Density</strong></p><ul><li>Admin shell tightened toward shadcn / Laravel starter density: Inter UI font, narrower sidebar (<code>w-60</code>), shorter topbar (<code>h-14</code>), smaller page titles, denser nav rows, tighter content padding and control heights.</li></ul><p><strong>Keyboard shortcuts</strong></p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Scope</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl/⌘B</code></td><td>App shell</td><td>Collapse / expand sidebar (mobile: open/close drawer)</td></tr><tr><td><code>Ctrl/⌘K</code></td><td>App shell</td><td>Command palette (navigate pages) — unchanged</td></tr><tr><td><code>N</code></td><td>Active module list</td><td>Open <strong>New</strong> create dialog when permitted</td></tr><tr><td><code>Ctrl/⌘F</code></td><td>Active module list</td><td>Focus that module’s search field (not browser Find / not ⌘K)</td></tr></tbody></table><p><strong>Note:</strong> Chromium reserves <code>Ctrl/⌘N</code> for a new browser window — web apps cannot override it. Create uses bare <strong><code>N</code></strong> when focus is not in an input.</p><p>Shortcuts are ignored while typing in inputs. Module pages register via <code>useModuleShortcuts</code> (mirror Leads). UI hints use <code>ShortcutHint</code> on New buttons and list search fields.</p><h2 id="departments-module-2026-08-03" tabindex="-1">Departments module (2026-08-03) <a class="header-anchor" href="#departments-module-2026-08-03" aria-label="Permalink to &quot;Departments module (2026-08-03)&quot;">​</a></h2><p>Marketplace HR module (<code>departments</code>, not default-included) for organizing users and employees:</p><ul><li>One User manager per department; one user may manage many departments</li><li>Many-to-many membership for users and employees</li><li>Admins see all departments; managers see managed departments + performance; staff see memberships</li><li>Performance dashboard aggregates Leads/Tasks for linked users only (unlinked employees stay on the roster)</li><li>Employee forms use multi-select <code>department_ids</code> when Departments is installed (legacy string column retained)</li><li>Manager/member pickers include the signed-in user (Users list API omits self) so a solo owner can manage a department</li><li>Security: tenant-scoped Exists for manager/members; org-wide-only manager assignment; <code>manage_members</code> required to sync memberships on create/update</li><li>Playwright: <code>npm run test:e2e:departments</code></li></ul><p>Docs: <a href="/user-guide/departments">User Guide</a>, <a href="/developer-guide/departments">Developer Guide</a>, <a href="/api/tenant-v1-departments">API</a>, <a href="/deployment/departments">Deployment</a>.</p><h2 id="create-employee-from-existing-user-2026-08-03" tabindex="-1">Create employee from existing user (2026-08-03) <a class="header-anchor" href="#create-employee-from-existing-user-2026-08-03" aria-label="Permalink to &quot;Create employee from existing user (2026-08-03)&quot;">​</a></h2><p>Workspaces that installed <strong>Employees</strong> after creating users can now convert a login into a directory record:</p><ul><li>Users row action <strong>Create employee record</strong> (requires Employees module + <code>employees.create</code>)</li><li><code>POST /api/tenant/v1/users/{user}/create-employee</code> (user-row lock; inactive when the user is suspended)</li><li>User list/show/update include nullable <code>employee_id</code></li><li>Race-safe active link via <code>employees.active_user_id</code> + unique <code>(tenant_id, active_user_id)</code>; soft delete frees the link for re-provision</li><li>Salary remains on Payroll profiles (unchanged)</li></ul><h2 id="tenant-email-notification-toggles-2026-08-03" tabindex="-1">Tenant email notification toggles (2026-08-03) <a class="header-anchor" href="#tenant-email-notification-toggles-2026-08-03" aria-label="Permalink to &quot;Tenant email notification toggles (2026-08-03)&quot;">​</a></h2><p>Workspace admins can enable or disable <strong>event emails</strong> under <strong>Settings → Notifications</strong>. Defaults are <strong>all off</strong> to reduce SMTP cost during MVP testing. In-app and web push channels are unchanged. Daily task digests, daily CRM summaries, and auth emails (password reset / verification) always send.</p><p>Toggles: task assigned, task completed/reopened, task mentioned, follow-up created, follow-up due/overdue, lead mentioned, meeting events, other module assignments.</p><h2 id="workspace-timezone-convention-daily-reminder-gating-2026-08-03" tabindex="-1">Workspace timezone convention + daily reminder gating (2026-08-03) <a class="header-anchor" href="#workspace-timezone-convention-daily-reminder-gating-2026-08-03" aria-label="Permalink to &quot;Workspace timezone convention + daily reminder gating (2026-08-03)&quot;">​</a></h2><p><strong>Code</strong></p><ul><li>Task digest and daily CRM summary emails gated by <strong>Daily Reminder Time</strong> compare against the workspace timezone explicitly (<code>now($timezone)</code>), not the server/UTC process clock.</li><li>Tenant <code>applyRuntimeConfig()</code> applies timezone before mail overlay and no longer drops workspace timezone when mail provider config fails.</li></ul><p><strong>Docs convention</strong></p><ul><li>Canonical <a href="/developer-guide/tenant-settings#timezone-and-scheduled-datetimes">Workspace timezone convention</a>: one Settings → General timezone (e.g. <code>Asia/Karachi</code>) drives Daily Reminder Time, task dues, lead follow-ups, meetings/calendar, and attendance office hours / login check-in. No per-module timezone.</li><li>Binding for <strong>all current and future modules</strong>: Module Development Standard principle + Definition of Done, Module Development Guide (Date and time), Module Architecture, and Platform Freeze Configuration row.</li><li>User Guide Settings, Attendance, Tasks, Leads, Meetings, and Calendar pages cross-link that rule.</li></ul><hr><h2 id="hr-user-sync-login-attendance-and-payroll-deductions-2026-08-02" tabindex="-1">HR user sync, login attendance, and payroll deductions (2026-08-02) <a class="header-anchor" href="#hr-user-sync-login-attendance-and-payroll-deductions-2026-08-02" aria-label="Permalink to &quot;HR user sync, login attendance, and payroll deductions (2026-08-02)&quot;">​</a></h2><p><strong>Users ↔ Employees</strong></p><ul><li>Creating a workspace user can provision a linked <strong>Employee</strong> when the Employees module is installed (<code>create_employee</code>, default on). Suspend sets the linked employee to inactive; name/email updates sync to the employee record.</li></ul><p><strong>Attendance</strong></p><ul><li>Tenant Settings → <strong>Attendance</strong> (when the module is installed): office start/end, grace minutes, work week days.</li><li>Successful tenant login auto check-in for linked active employees (first login of the day; status <code>present</code> or new <code>late</code>).</li><li>Attendance status enum adds <code>late</code>.</li><li>Login check-in stores <strong>IP</strong> and optional <strong>GPS coordinates</strong> (<code>check_in_ip</code> / <code>check_in_latitude</code> / <code>check_in_longitude</code>); shown on the attendance detail sheet.</li></ul><p><strong>Payroll</strong></p><ul><li>Pay runs deduct unpaid leave and unexcused absences from base salary using the working-day calendar; line breakdown fields: <code>working_days</code>, <code>unpaid_leave_days</code>, <code>absent_days</code>, <code>days_present</code>.</li></ul><p><strong>Verification</strong></p><ul><li>Pest: attendance settings, login check-in, user→employee provision, pay-period calculator. Docs and UI updated for settings, attendance, payroll, and users.</li></ul><hr><h2 id="phase-7-hr-—-employees-leave-management-attendance-payroll-2026-08-01" tabindex="-1">Phase 7 HR — Employees, Leave Management, Attendance, Payroll (2026-08-01) <a class="header-anchor" href="#phase-7-hr-—-employees-leave-management-attendance-payroll-2026-08-01" aria-label="Permalink to &quot;Phase 7 HR — Employees, Leave Management, Attendance, Payroll (2026-08-01)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>Shipped four free Marketplace SKUs under category <code>hr</code> (sort <code>70</code>): <strong>Employees</strong> (<code>employees</code>), <strong>Leave Management</strong> (<code>leave-management</code>, sort <code>20</code>), <strong>Attendance</strong> (<code>attendance</code>, sort <code>30</code>), and <strong>Payroll</strong> (<code>payroll</code>, sort <code>40</code>). All are opt-in and non-billable.</li><li>Leave Management, Attendance, and Payroll hard-depend on Employees (<code>module_dependencies</code>). Payroll optionally depends on Accounting for pay-run journal posting.</li><li>Roadmap capabilities (directory, leave types/balances/requests, daily attendance, profiles, pay runs) live inside these four SKUs — not separate Marketplace modules.</li></ul><p><strong>Domain</strong></p><ul><li>Employees directory with employment type/status, optional workspace user link, soft delete, and stats KPIs.</li><li>Leave types, per-year balances, and leave requests with <code>draft → pending → approved|rejected</code> (cancel from draft/pending); approve applies days to balances under <code>lockForUpdate()</code>.</li><li>Attendance records unique per employee/date with check-in/out and presence status (<code>present</code> / <code>absent</code> / <code>half_day</code> / <code>remote</code>).</li><li>Payroll profiles (one per employee) and pay runs that auto-generate lines from active profiles; lifecycle <code>draft → approved → paid</code>; optional soft post to a draft Accounting journal (expense debit / liability credit).</li></ul><p><strong>Security &amp; production readiness (2026-08-02)</strong></p><ul><li>Full security audit: <a href="/deployment/hr-phase7-security-audit"><code>/deployment/hr-phase7-security-audit</code></a> · ops readiness: <a href="/deployment/hr-phase7-production-readiness"><code>/deployment/hr-phase7-production-readiness</code></a>.</li><li>Leave: balance upsert RBAC, days capped to date range, insufficient-balance reject on approve, approved requests not soft- <strong>or</strong> force-deletable, <code>remaining</code> always derived, transition locks.</li><li>Payroll: pay-run approve/pay/post <code>lockForUpdate</code>, line gross <code>min:0</code>, journal accounts must be expense/liability; default <strong>staff</strong> no longer has <code>payroll.view</code>.</li><li>Employees: unique <code>user_id</code> link; Attendance: <code>check_out &gt;= check_in</code>.</li><li>Re-verification: companion PR CI green (Backend #72 QG+Pest, Frontend #66, Docs #75); headed Playwright Employees/Leave/Attendance/Payroll <strong>6/6 each</strong>; <strong>GO</strong> for opt-in staging → production after staff-role re-sync.</li></ul><p><strong>Frontend &amp; verification</strong></p><ul><li>HR nav group with Employees / Leave / Attendance / Payroll UI; API clients, query keys, and permissions wired for module pages.</li><li>Playwright: <code>test:e2e:employees</code> · <code>leave-management</code> · <code>attendance</code> · <code>payroll</code> (modules + authz). Pest under <code>tests/Feature/Tenant/Employee</code>, <code>Leave</code>, <code>Attendance</code>, and <code>Payroll</code>.</li></ul><p><strong>Docs</strong></p><ul><li>User / developer / deployment / API guides for all four SKUs; roadmap, module-dependencies, and <code>database.md</code> HR tables updated; Phase 7 HR security audit + production readiness pages.</li></ul><hr><h2 id="phase-6-finance-—-accounting-financial-reports-2026-08-01" tabindex="-1">Phase 6 Finance — Accounting + Financial Reports (2026-08-01) <a class="header-anchor" href="#phase-6-finance-—-accounting-financial-reports-2026-08-01" aria-label="Permalink to &quot;Phase 6 Finance — Accounting + Financial Reports (2026-08-01)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>Shipped two free Marketplace SKUs under category <code>finance</code> (sort <code>60</code>): <strong>Accounting</strong> (<code>accounting</code>, sort <code>10</code>) and <strong>Financial Reports</strong> (<code>financial-reports</code>, sort <code>20</code>). Both are opt-in and non-billable.</li><li>Roadmap capabilities Accounts / Journals / General Ledger live inside <strong>Accounting</strong>; Trial Balance / P&amp;L / Balance Sheet live in <strong>Financial Reports</strong>.</li><li>Financial Reports hard-depends on Accounting (<code>module_dependencies</code>).</li></ul><p><strong>Domain</strong></p><ul><li>Chart of accounts (<code>accounts</code>) with starter system CoA on first list; journal headers/lines with balanced debit/credit validation; lifecycle <code>draft → post → void</code> (void excluded from GL/reports).</li><li>General ledger inquiry aggregates posted lines (no balance cache), <strong>paginated</strong> (default 100 / max 500) with period opening/closing balances. Manual double-entry only — no auto-post from Billing/Purchasing/Inventory; single currency.</li><li>Production hardeners: journal <code>post</code>/<code>void</code> use <code>lockForUpdate()</code> transactions; system account <code>code</code> locked in API; report/GL query dates FormRequest-validated; CoA seed race-safe.</li></ul><p><strong>Frontend &amp; verification</strong></p><ul><li>Finance nav: Accounts, Journals, General Ledger, Financial Reports; dual module/permission gates.</li><li>Accounts trash/restore/force-delete UX; journal void confirm + optional reason; GL pagination.</li><li>Playwright (per module, headed-ready): shared-session human suites (<code>accounting.modules</code> / <code>financial-reports.modules</code>), authz/security (<code>*.authz</code>), smoke (<code>*.workflow</code>); combined <code>test:e2e:finance</code> / <code>test:e2e:finance:headed</code>.</li><li>Pest: balance/post/void, cross-tenant isolation, double-post/void-draft, GL pagination, FR module gate + date validation.</li></ul><p><strong>Docs</strong></p><ul><li>User / developer / deployment / API guides for both SKUs; roadmap, module-dependencies, and <code>database.md</code> finance tables updated.</li></ul><hr><h2 id="marketplace-filters-and-dependency-enable-2026-08-01" tabindex="-1">Marketplace filters and dependency enable (2026-08-01) <a class="header-anchor" href="#marketplace-filters-and-dependency-enable-2026-08-01" aria-label="Permalink to &quot;Marketplace filters and dependency enable (2026-08-01)&quot;">​</a></h2><ul><li>Tenant Marketplace adds filter chips for <strong>Installed</strong>, <strong>Available</strong>, <strong>Paid</strong>, and <strong>Free</strong> (combinable: install status × pricing).</li><li>Module detail drawer shows required-dependency fee and an <strong>Install</strong> / <strong>Subscribe</strong> action when a hard dependency is missing. Paid dependencies open that module’s subscribe flow (billing cycle + checkout); free dependencies install in place.</li><li>Tenant (and Central) marketplace show payloads enrich <code>required_modules</code> / <code>optional_modules</code> / <code>missing_required_modules</code> with <code>is_billable</code>, prices, and install flags.</li></ul><hr><h2 id="tenant-currency-defaults-products-as-services-2026-08-01" tabindex="-1">Tenant currency defaults + Products as services (2026-08-01) <a class="header-anchor" href="#tenant-currency-defaults-products-as-services-2026-08-01" aria-label="Permalink to &quot;Tenant currency defaults + Products as services (2026-08-01)&quot;">​</a></h2><p><strong>Currency UX</strong></p><ul><li>Money forms (invoices, estimates, quotations, opportunities, contracts, payments, expenses, purchase orders) and Products/Vendors currency fields now use the shared searchable currency list from Settings (<code>currencyOptions</code>), not a five-code hard-coded dropdown or free-text code.</li><li>Create dialogs default currency to the tenant workspace currency from Settings (fallback <code>USD</code>). Edit keeps the record’s existing currency. Credit notes still inherit currency from the selected invoice; their bare create fallback also uses the tenant currency.</li></ul><p><strong>Products as services</strong></p><ul><li>The Products catalog is documented and labeled for both goods and services. Services use the same catalog with <strong>Track stock</strong> turned off; Inventory continues to manage only stock-tracked items. No new product/service type column.</li></ul><hr><h2 id="phase-5-inventory-2026-08-01" tabindex="-1">Phase 5 Inventory (2026-08-01) <a class="header-anchor" href="#phase-5-inventory-2026-08-01" aria-label="Permalink to &quot;Phase 5 Inventory (2026-08-01)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>Shipped three free Marketplace SKUs under the new <code>inventory</code> category (category sort <code>50</code>): <strong>Products</strong> (<code>10</code>), <strong>Warehouses</strong> (<code>20</code>), and <strong>Inventory</strong> (<code>30</code>). All are opt-in, non-billable, and not default-included; catalog module count increases from <strong>20 to 23</strong>.</li><li>Inventory has a required hard dependency on Products. Warehouses is a soft Inventory integration: its UI CRUD remains module-gated while <code>ensureDefaultWarehouse()</code> supplies active default code <code>MAIN</code> to operations that omit a location.</li><li>Products provides categories, stock-tracking flags, notes/activity, and nullable <code>product_id</code> integration on Purchase Order lines. Warehouses provides locations, notes/activity, and guards against deleting the sole default warehouse.</li></ul><p><strong>Stock and purchasing</strong></p><ul><li>Added per-product/per-warehouse <code>stock_levels</code>, immutable <code>stock_movements</code>, and draftable <code>stock_transfers</code> with line items. <code>StockService</code> is the sole stock mutation boundary, using transactions and <code>lockForUpdate()</code> to maintain a non-negative balance and movement ledger.</li><li>Stock adjustment types are <code>in</code>, <code>out</code>, and <code>adjust</code>; transfers follow <code>draft → in_transit → completed|cancelled</code> and post paired stock movements only on completion.</li><li>Purchase Order lines now optionally link a Product. A <strong>received</strong> Purchase Order posts stock-in once for linked products with <code>track_stock=true</code> when Products and Inventory are entitled; <code>partially_received</code> remains acknowledgement-only. Receipt may select <code>warehouse_id</code> or use the default.</li><li>PO receive integrity: <code>POST …/status</code> with <code>received</code> / <code>partially_received</code> routes through <code>receive()</code> (same stock path as <code>/receive</code>); status + stock post share one transaction with <code>lockForUpdate()</code> on the PO so concurrent receives cannot double-post and a failed stock post does not leave the PO stuck as received.</li></ul><p><strong>Frontend, verification, and docs</strong></p><ul><li>Added Products, Warehouses, and Inventory tenant pages using the existing AppLayout, entitlement/permission-gated navigation, services, types, query keys, forms, detail sheets, and shared states.</li><li>Added Pest coverage under <code>tests/Feature/Tenant/Product</code>, <code>Warehouse</code>, and <code>Inventory</code>, plus Playwright commands <code>test:e2e:products</code>, <code>test:e2e:warehouses</code>, <code>test:e2e:inventory</code>, and shared-session <code>test:e2e:inventory-phase</code> / <code>test:e2e:inventory-phase:headed</code> (Products → Warehouses → Stock → PO receive, with form validation and human-mistake paths under one login).</li><li>Added User, Developer, Deployment, and Tenant API guides; updated module dependencies, database dictionary, Purchase Order receiving documentation, roadmap, changelog, and documentation sidebars.</li></ul><p><strong>Out of scope</strong></p><ul><li>Serial/lot tracking, inventory valuation, and COGS are not included in Phase 5.</li></ul><hr><h2 id="expenses-module-purchase-order-convert-2026-08-01" tabindex="-1">Expenses module + Purchase Order convert (2026-08-01) <a class="header-anchor" href="#expenses-module-purchase-order-convert-2026-08-01" aria-label="Permalink to &quot;Expenses module + Purchase Order convert (2026-08-01)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>Third and final Phase 4 (Purchasing) module (backend model <code>Expense</code>) — a standalone operational-expense record: single amount (no line items), category, optional links to a Vendor and/or Purchase Order. Flat Laravel, <code>module:expenses</code> + Spatie RBAC, mirrors the simplified Estimate/Payment notes/timeline/assignee-scope/status-machine pattern.</li><li><strong>No hard <code>module_dependencies</code></strong> — Expenses installs standalone. <code>vendor_id</code> and <code>purchase_order_id</code> are both nullable and validated only at the point of use (<code>LinkableVendor</code>, new <code>LinkablePurchaseOrder</code> rule) when the corresponding module (<code>vendors</code> / <code>purchase-orders</code>) is entitled — a <strong>soft</strong> dependency, unlike Purchase Orders&#39; hard dependency on Vendors. <strong>Free Marketplace opt-in</strong> — catalog category <code>purchasing</code>, <code>is_default_included=false</code> / <code>is_billable=false</code>, <code>sort_order=30</code> (after Purchase Orders&#39; <code>20</code>).</li><li>Status workflow <code>draft → submitted → approved|rejected</code>, <code>approved → paid</code>, <code>draft|submitted → cancelled</code> via <code>ExpenseStatusEnum::allowedTransitions()</code>; <code>rejected</code>/<code>paid</code>/<code>cancelled</code> are terminal. Only <code>draft</code> expenses can have their fields edited — workflow actions (submit/approve/reject/pay/cancel) remain available regardless.</li><li><strong>Convert a Purchase Order to an Expense</strong> (<code>POST /purchase-orders/{id}/convert</code>) — the deferred Phase 4 Milestone 2 feature, now shipped as part of Milestone 3. One-way, one-time: creates a <strong>draft</strong> <code>Expense</code> from a <code>sent</code>/<code>partially_received</code>/<code>received</code> purchase order (<code>title</code>, <code>amount</code>←<code>total</code>, <code>tax_amount</code>←<code>tax_total</code>, <code>currency</code>, <code>vendor_id</code>, <code>assigned_to</code>, <code>notes</code> copied; <code>category</code> always <code>other</code>). Re-running the conversion is blocked by an existing <code>Expense</code> row for that <code>purchase_order_id</code> (including soft-deleted). Gated by a new <strong>soft, call-time</strong> entitlement check for the Expenses module inside <code>PurchaseOrderService::convertToExpense()</code> — not a <code>module_dependencies</code> row — so Purchase Orders keeps working with Expenses uninstalled; only the convert endpoint 422s until Expenses is installed. New permission <code>purchase-orders.convert</code>.</li></ul><p><strong>Backend</strong></p><ul><li>Tables: <code>expenses</code>, <code>expense_notes</code>, <code>expense_activities</code></li><li>Auto-numbered (<code>EXP-00001</code>, prefix from new <code>expenses_number_prefix</code> tenant setting, retried on duplicate via the shared <code>RetriesOnDuplicateNumber</code> trait)</li><li>Enums: <code>ExpenseCategoryEnum</code> (<code>travel</code>, <code>office</code>, <code>software</code>, <code>utilities</code>, <code>other</code>), <code>ExpenseStatusEnum</code> (<code>draft</code>, <code>submitted</code>, <code>approved</code>, <code>rejected</code>, <code>paid</code>, <code>cancelled</code>), <code>ExpenseActivityTypeEnum</code> (<code>Created</code>, <code>Updated</code>, <code>Assigned</code>, <code>StatusChanged</code>, <code>NoteAdded</code>, <code>Deleted</code>, <code>Restored</code>)</li><li>Permissions: <code>expenses.view|create|update|delete|restore|force.delete|assign|submit|approve|reject|pay|cancel</code></li><li>Model (<code>Expense</code>, <code>BelongsToTenant</code>, soft deletes, UUID, <code>LogsActivity</code>) + factories, controller, form requests, API resources, policy (assignee-scoped view/update/submit/cancel; approve/reject/pay are <strong>not</strong> assignee-scoped), service (<code>ExpenseService</code>: numbering, status machine, notes, timeline, assign), events, <code>AppServiceProvider</code>-registered event subscriber (audit + assignment notification)</li><li>New <code>LinkablePurchaseOrder</code> rule (mirrors <code>LinkableVendor</code>) — validates <code>purchase_order_id</code> belongs to the tenant and the Purchase Orders module is entitled, only when a value is supplied</li><li><code>PurchaseOrderService::convertToExpense()</code> mirrors <code>EstimateService::convert()</code>&#39;s draft-creation pattern but swaps the hard-dependency check for a soft <code>EntitlementService::hasModule()</code> check; new <code>PurchaseOrderActivityTypeEnum::Converted</code> timeline entry and <code>PurchaseOrderConverted</code> event</li><li>Catalog registration (no <code>module_dependencies</code> row) via <code>DefaultModuleRegistrar</code> migration (migrate-only); permissions + default role map additive migrations for both <code>expenses.*</code> and <code>purchase-orders.convert</code></li><li><code>expenses_number_prefix</code> added to <code>TenantSettingDefinitions</code> and <code>UpdateTenantSettingsRequest</code> validation</li><li>Pest: <code>tests/Feature/Tenant/Expense/ExpenseTest.php</code> (CRUD, soft FK validation against module entitlement, status workflow, assignee scoping, module gate), Purchase Order convert coverage added to <code>PurchaseOrderTest.php</code> (entitled vs blocked, one-time conversion, status guard)</li><li>Module counts bumped from 19 → 20 across <code>MarketplaceCatalogTest</code>, <code>TenantProvisioningTest</code>, <code>TenantAuthTest</code> fixtures</li></ul><p><strong>Frontend</strong></p><ul><li><code>src/pages/expenses/</code> — list page (KPIs: total, mine, draft/submitted/approved/rejected/paid, approved &amp; paid value; status/category/vendor/PO/assignee filters, DataTable), create/edit form dialog (category select, amount, tax amount, currency, expense date, notes, optional vendor/purchase order <code>SearchableSelect</code> pickers rendered only when the corresponding module is entitled and viewable), detail sheet (overview/notes/timeline tabs; submit/approve/reject/pay/cancel/assign/notes/edit (draft only))</li><li>Added to the existing tenant sidebar <strong>Purchasing</strong> group, after Purchase Orders</li><li><code>expenseService</code>, <code>QUERY_KEYS.expenses</code>, <code>PERMISSIONS.expenses</code></li><li>Purchase order detail sheet: new <strong>Convert to expense</strong> action (permission <code>purchase-orders.convert</code>, visible only when the PO status is convertible, the Expenses module is entitled, and it hasn&#39;t already been converted) with a confirm dialog; shows a link to the resulting expense under &quot;Related records&quot; once converted</li><li>Notification registry: <code>expense.assigned</code> → <code>/expenses?expense={id}</code></li><li>Playwright: <code>e2e/tests/expenses/expenses.workflow.spec.ts</code> (<code>npm run test:e2e:expenses</code>) — enables <code>vendors</code> + <code>purchase-orders</code> + <code>expenses</code>, covers KPI smoke, create/submit/approve/pay workflow, and end-to-end PO → Expense conversion</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/expenses-overview">expenses-overview.md</a> / <a href="/user-guide/expenses">expenses.md</a> (+ <a href="/developer-guide/expenses">developer</a> / <a href="/deployment/expenses">production</a>)</li><li><a href="/api/tenant-v1-expenses">api/tenant-v1-expenses.md</a>; <a href="/api/tenant-v1-purchase-orders">api/tenant-v1-purchase-orders.md</a> updated with the convert endpoint</li><li><a href="/user-guide/purchase-orders-overview">purchase-orders-overview.md</a> / <a href="/user-guide/purchase-orders">purchase-orders.md</a> updated — convert-to-expense moved from deferred to shipped</li><li><a href="/architecture/module-dependencies">Module Dependencies</a> updated — Expenses&#39; soft dependencies on Vendors/Purchase Orders, and Purchase Orders&#39; soft use of Expenses for convert, both marked shipped</li><li><a href="/getting-started/product-roadmap">Product Roadmap</a> — Expenses marked shipped; <strong>Phase 4 — Purchasing goal Achieved</strong></li></ul><p><strong>Deferred</strong></p><ul><li>Receipt attachments, reimbursements, GL posting, multi-line expenses (all explicitly out of scope for this MVP)</li></ul><hr><h2 id="purchase-orders-module-2026-08-01" tabindex="-1">Purchase Orders module (2026-08-01) <a class="header-anchor" href="#purchase-orders-module-2026-08-01" aria-label="Permalink to &quot;Purchase Orders module (2026-08-01)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>Second Phase 4 (Purchasing) module — Milestone 2, header + line-item procurement documents a tenant issues to its own vendors (backend model <code>PurchaseOrder</code>). Flat Laravel, <code>module:purchase-orders</code> + Spatie RBAC, mirrors the Estimates notes/timeline/assignee-scope/lines/status-machine pattern, swapping Estimates&#39; optional related-record pickers for a single <strong>required</strong> <code>vendor_id</code>.</li><li><strong>Hard dependency on Vendors</strong> — same pattern as Estimates → Invoices; Marketplace blocks installing Purchase Orders until a workspace already has Vendors entitled (every purchase order requires a vendor). <strong>Free Marketplace opt-in</strong> — catalog category <code>purchasing</code>, <code>is_default_included=false</code> / <code>is_billable=false</code>, <code>sort_order=20</code> (after Vendors&#39; <code>10</code>).</li><li>Status workflow <code>draft → sent → partially_received|received|cancelled</code> (also <code>sent → cancelled</code>, <code>partially_received → received|cancelled</code>); <code>received</code>/<code>cancelled</code> are terminal. <strong>Receiving is acknowledgement only</strong> — no Inventory stock posting (no Inventory module exists on this platform). Convert-to-expense is deferred to Phase 4 Milestone 3.</li></ul><p><strong>Backend</strong></p><ul><li>Tables: <code>purchase_orders</code>, <code>purchase_order_lines</code>, <code>purchase_order_notes</code>, <code>purchase_order_activities</code></li><li>Auto-numbered (<code>PO-00001</code>, prefix from <code>purchase_orders_number_prefix</code> tenant setting, retried on duplicate via the shared <code>RetriesOnDuplicateNumber</code> trait)</li><li>Enums: <code>PurchaseOrderStatusEnum</code> (<code>draft</code>, <code>sent</code>, <code>partially_received</code>, <code>received</code>, <code>cancelled</code>), <code>PurchaseOrderActivityTypeEnum</code> (<code>Created</code>, <code>Updated</code>, <code>Assigned</code>, <code>StatusChanged</code>, <code>NoteAdded</code>, <code>Deleted</code>, <code>Restored</code>)</li><li>Permissions: <code>purchase-orders.view|create|update|delete|restore|force.delete|assign|send|receive|cancel</code></li><li>Model + factories, controller, form requests, API resources, policy (assignee-scoped view/update/send/receive/cancel), service (<code>PurchaseOrderService</code>, <code>syncLines</code>/<code>recalculateTotals</code> like Estimates; <code>receive()</code> only accepts <code>partially_received</code>/<code>received</code>), events, <code>AppServiceProvider</code>-registered event subscriber (audit + assignment notification)</li><li><code>LinkableVendor</code> rule — <code>vendor_id</code> is required, tenant-scoped, and validates the Vendors module is entitled</li><li>Catalog registration + <code>module_dependencies</code> row on <code>vendors</code> via <code>DefaultModuleRegistrar</code> migrations (migrate-only); permissions + default role map additive migrations</li><li><code>purchase_orders_number_prefix</code> added to <code>UpdateTenantSettingsRequest</code> validation (was previously stripped, causing <code>updateMany</code> to receive <code>null</code>)</li><li>Pest: <code>tests/Feature/Tenant/PurchaseOrder/PurchaseOrderTest.php</code>, <code>tests/Feature/Central/Module/PurchaseOrdersModuleDependencyTest.php</code></li></ul><p><strong>Frontend</strong></p><ul><li><code>src/pages/purchase-orders/</code> — list page (KPIs: total, mine, draft, sent, partially received, received; status/vendor/assignee filters, DataTable), create/edit form dialog (required vendor <code>SearchableSelect</code>, currency, order date, expected date, notes, line items editor with live subtotal/tax/total preview), detail sheet (overview/lines/notes/timeline tabs; send/mark partially received/mark received/cancel/assign/notes/edit (draft only))</li><li>Added to the existing tenant sidebar <strong>Purchasing</strong> group, after Vendors</li><li><code>purchaseOrderService</code>, <code>QUERY_KEYS.purchaseOrders</code>, <code>PERMISSIONS.purchaseOrders</code></li><li>Notification registry: <code>purchase-order.assigned</code> → <code>/purchase-orders?purchase_order={id}</code></li><li>Playwright: <code>e2e/tests/purchase-orders/purchase-orders.workflow.spec.ts</code> (<code>npm run test:e2e:purchase-orders</code>) — enables both <code>vendors</code> and <code>purchase-orders</code> modules, creates a vendor, creates a purchase order, verifies status transitions (draft → sent → partially received → received), checks the timeline, then deletes it</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/purchase-orders-overview">purchase-orders-overview.md</a> / <a href="/user-guide/purchase-orders">purchase-orders.md</a> (+ <a href="/developer-guide/purchase-orders">developer</a> / <a href="/deployment/purchase-orders">production</a>)</li><li><a href="/api/tenant-v1-purchase-orders">api/tenant-v1-purchase-orders.md</a></li><li><a href="/architecture/module-dependencies">Module Dependencies</a> updated — Purchase Orders → Vendors marked shipped</li><li><a href="/getting-started/product-roadmap">Product Roadmap</a> — Purchase Orders marked shipped in Phase 4; Expenses remains Planned</li></ul><p><strong>Deferred</strong></p><ul><li>Convert a purchase order to an Expense (Phase 4 Milestone 3), Inventory stock posting on receipt, per-line partial receiving, purchase order PDFs / e-mail delivery to vendors, dashboard widgets for Purchase Orders</li></ul><hr><h2 id="vendors-module-2026-08-01" tabindex="-1">Vendors module (2026-08-01) <a class="header-anchor" href="#vendors-module-2026-08-01" aria-label="Permalink to &quot;Vendors module (2026-08-01)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>First Phase 4 (Purchasing) module and Milestone 1 of that phase — a workspace directory of suppliers (backend model <code>Vendor</code>, first-class entity, <strong>no</strong> relationship to Contacts unlike Companies). Flat Laravel, <code>module:vendors</code> + Spatie RBAC, mirrors the Companies notes/timeline/assignee-scope pattern.</li><li>Introduces a new Marketplace category: <code>purchasing</code> (<strong>Purchasing</strong>), <code>category_sort_order=40</code>. <strong>Free Marketplace opt-in</strong> — <code>is_default_included=false</code> / <code>is_billable=false</code>, <code>sort_order=10</code>.</li><li>No <code>industry</code>, <code>source</code>, <code>source_meta</code>, or <code>contacts</code> relationship (unlike Companies). Adds <code>tax_id</code>, <code>payment_terms</code>, <code>currency</code> (max 3 chars), and a <code>status</code> enum (<code>active</code>/<code>inactive</code>, default <code>active</code>).</li></ul><p><strong>Backend</strong></p><ul><li>Tables: <code>vendors</code>, <code>vendor_notes</code>, <code>vendor_activities</code></li><li>Enums: <code>VendorStatusEnum</code> (<code>active</code>, <code>inactive</code>), <code>VendorActivityTypeEnum</code> (<code>Created</code>, <code>Updated</code>, <code>Assigned</code>, <code>NoteAdded</code>, <code>Deleted</code>, <code>Restored</code>)</li><li>Permissions: <code>vendors.view|create|update|delete|restore|force.delete|assign</code></li><li>Model + factories, controller, form requests, API resources, policy, service (search includes <code>tax_id</code>; stats: <code>total_vendors</code>, <code>my_vendors</code>, <code>unassigned</code>, <code>active</code>, <code>inactive</code>, <code>scope</code>), events, <code>AppServiceProvider</code>-registered event subscriber (audit + assignment notification)</li><li>Catalog registration (new <code>purchasing</code> category + <code>vendors</code> module) via <code>DefaultModuleRegistrar</code> migration (migrate-only); permissions + default role map additive migrations</li><li>Pest: <code>tests/Feature/Tenant/Vendor/VendorTest.php</code> (mirrors <code>CompanyTest</code>, includes module gate coverage)</li></ul><p><strong>Frontend</strong></p><ul><li><code>src/pages/vendors/</code> — list page (KPIs: total, my vendors, unassigned, active, inactive; status + assignee filters, DataTable), create/edit form dialog (name, email, phone, website, address, tax ID, payment terms, currency, status, assignee), detail sheet (overview/notes/activity tabs)</li><li>New tenant sidebar <strong>Purchasing</strong> group (after Billing), with Vendors (Truck icon)</li><li><code>vendorService</code>, <code>QUERY_KEYS.vendors</code>, <code>PERMISSIONS.vendors</code></li><li>Notification registry: <code>vendor.assigned</code> → <code>/vendors?vendor={id}</code></li><li>Playwright: <code>e2e/tests/vendors/vendors.workflow.spec.ts</code> (<code>npm run test:e2e:vendors</code>) — enables the <code>vendors</code> module, creates a vendor, verifies KPI cards, notes, and activity timeline, then deletes it</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/vendors-overview">vendors-overview.md</a> / <a href="/user-guide/vendors">vendors.md</a> (+ <a href="/developer-guide/vendors">developer</a> / <a href="/deployment/vendors">production</a>)</li><li><a href="/api/tenant-v1-vendors">api/tenant-v1-vendors.md</a></li><li><a href="/architecture/module-dependencies">Module Dependencies</a> updated — Purchase Orders → Vendors (required, design) and Expenses → Vendors (optional, design) documented ahead of those modules shipping</li><li><a href="/getting-started/product-roadmap">Product Roadmap</a> — Vendors marked shipped in Phase 4, Purchase Orders and Expenses expanded with designed MVP capability bullets</li></ul><p><strong>Deferred</strong></p><ul><li>Purchase Orders (Phase 4 Milestone 2), Expenses (Phase 4 Milestone 3), vendor scorecards/performance tracking, vendor portal, vendor import/export, dashboard widgets, communication template placeholders</li></ul><hr><h2 id="phase-3-billing-production-hardening-2026-08-01" tabindex="-1">Phase 3 Billing production hardening (2026-08-01) <a class="header-anchor" href="#phase-3-billing-production-hardening-2026-08-01" aria-label="Permalink to &quot;Phase 3 Billing production hardening (2026-08-01)&quot;">​</a></h2><p><strong>Security / ledger integrity</strong></p><ul><li>Payment <code>post()</code> now requires each allocated invoice to be active Sent/Partial, rejects allocations above <code>balance_due</code>, and rejects currency mismatches; soft-deleted invoices cannot be paid.</li><li>Invoice void limited to Draft/Sent with zero <code>amount_paid</code> / <code>amount_credited</code> (Partial→Void removed).</li><li>Credit note <code>apply()</code> requires Sent/Partial invoice and credit total ≤ <code>balance_due</code>.</li><li>Unique <code>(tenant_id, number)</code> indexes on customer invoices/payments/credit notes and estimates, with create-time duplicate-number retry.</li></ul><p><strong>UX / CI</strong></p><ul><li>Payments list supports <code>?invoice=</code> deep-link (mirrors Credit Notes); invoice detail links through.</li><li>Docs Quality Gate: raised Vite <code>chunkSizeWarningLimit</code> and excluded Rollup chunk-size advisories from WARNING grep.</li><li>Pest expectations updated for <code>todos</code> as a third default-included module (unblocks Backend CI).</li></ul><h2 id="estimates-module-2026-07-31" tabindex="-1">Estimates module (2026-07-31) <a class="header-anchor" href="#estimates-module-2026-07-31" aria-label="Permalink to &quot;Estimates module (2026-07-31)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>Fourth and final Phase 3 (Billing) module — pre-sale cost estimates a tenant issues to its own customers (backend model <code>Estimate</code>, no <code>Customer</code> prefix — distinct naming from Invoices/Payments/Credit Notes since there&#39;s no equivalent Central concept to collide with). Flat Laravel, <code>module:estimates</code> + Spatie RBAC, mirrors the Credit Notes/Invoices notes/timeline/assignee-scope/lines pattern, plus a Quotations-shaped status machine.</li><li><strong>Hard dependency on Invoices</strong> — same pattern as Payments/Credit Notes; Marketplace blocks installing Estimates until a workspace already has Invoices entitled (converting an estimate always creates a <code>CustomerInvoice</code>). <strong>Free Marketplace opt-in</strong> — catalog category <code>billing</code>, <code>is_default_included=false</code> / <code>is_billable=false</code>, <code>sort_order=40</code> (after Credit Notes&#39; <code>30</code>).</li><li>Estimates introduces a <strong>convert-to-invoice</strong> action (<code>POST /estimates/{id}/convert</code>) — the first Phase 3 action that creates a row in a <em>different</em> module&#39;s table. Adds the <code>customer_invoices.estimate_id</code> foreign key (the nullable column already existed from the Invoices migration; this module adds the constraint once <code>estimates</code> exists).</li><li>Optional soft links to Contacts, Companies, Opportunities, and Quotations — each validated only when that module is entitled, no hard dependency rows for these.</li></ul><p><strong>Backend</strong></p><ul><li>Tables: <code>estimates</code>, <code>estimate_lines</code>, <code>estimate_notes</code>, <code>estimate_activities</code></li><li>Auto-numbered (<code>EST-00001</code>, prefix from <code>estimates_number_prefix</code> tenant setting)</li><li>Status workflow <code>draft → sent → accepted|rejected|expired</code> (<code>EstimateStatusEnum</code>, identical shape to <code>QuotationStatusEnum</code>); disallowed transitions return a 422 validation error</li><li><code>convertToInvoice()</code> copies the estimate&#39;s lines into a new draft <code>CustomerInvoice</code> via <code>CustomerInvoiceService::create()</code>, links it back via <code>estimate_id</code>, marks the estimate <code>accepted</code> if not already, and rejects a second conversion attempt</li><li>Permissions: <code>estimates.view|create|update|delete|restore|force.delete|assign|send|accept|convert</code></li><li>Model + factories, controller, form requests, API resources, policy, service, events (incl. <code>EstimateConverted</code>), <code>AppServiceProvider</code>-registered event subscriber (audit + assignment notification)</li><li>Catalog registration + <code>module_dependencies</code> row via <code>DefaultModuleRegistrar</code> migrations (migrate-only); permissions + default role map additive migrations</li><li>Pest: <code>tests/Feature/Tenant/Estimate/EstimateTest.php</code>, <code>tests/Feature/Central/Module/EstimatesModuleDependencyTest.php</code></li><li>Fixed a pre-existing MySQL &quot;identifier name too long&quot; bug (index names exceeding the 64-character limit) in the <code>customer_invoice_activities</code>, <code>customer_payment_activities</code>, and <code>customer_credit_note_activities</code> migrations, plus the <code>customer_payment_allocations</code> unique constraint and the <code>customer_credit_note_notes</code> / <code>customer_credit_note_lines</code> indexes — discovered while migrating this batch on real MySQL; all now use explicit shortened index names</li></ul><p><strong>Frontend</strong></p><ul><li><code>src/pages/estimates/</code> — list page (KPIs incl. Accepted value, Converted badge, filters, DataTable), create/edit form dialog (contact/company pickers, opportunity picker with quotation picker filtered by the selected opportunity, line items editor), detail sheet (overview/lines/notes/timeline tabs; send/accept/reject/<strong>convert to invoice</strong>/assign/notes)</li><li>Added to the existing tenant sidebar <strong>Billing</strong> group, after Credit Notes</li><li><code>estimateService</code>, <code>QUERY_KEYS.estimates</code>, <code>PERMISSIONS.estimates</code></li><li>Notification registry: <code>estimate.assigned</code> → <code>/estimates?estimate={id}</code></li><li>Playwright: <code>e2e/tests/estimates/estimates.workflow.spec.ts</code> (<code>npm run test:e2e:estimates</code>) — enables both <code>invoices</code> and <code>estimates</code> modules, creates an estimate, sends and accepts it, converts it to an invoice, confirms the conversion dialog, and verifies the resulting invoice + estimate timeline via the API</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/estimates-overview">estimates-overview.md</a> / <a href="/user-guide/estimates">estimates.md</a> (+ <a href="/developer-guide/estimates">developer</a> / <a href="/deployment/estimates">production</a>)</li><li><a href="/api/tenant-v1-estimates">api/tenant-v1-estimates.md</a></li><li><a href="/architecture/module-dependencies">Module Dependencies</a> updated — Estimates → Invoices marked shipped</li><li><a href="/getting-started/product-roadmap">Product Roadmap</a> — Estimates marked shipped in Phase 3, <strong>completing Phase 3 — Billing</strong> (Invoices, Payments, Credit Notes, Estimates all shipped)</li></ul><p><strong>Deferred</strong></p><ul><li>Estimate PDF export / e-mail delivery, reversing a conversion (one-way, one-time), multi-currency conversion, approval workflow beyond the status enum</li></ul><hr><h2 id="credit-notes-module-2026-07-31" tabindex="-1">Credit Notes module (2026-07-31) <a class="header-anchor" href="#credit-notes-module-2026-07-31" aria-label="Permalink to &quot;Credit Notes module (2026-07-31)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>Third Phase 3 (Billing) module — credit notes a tenant issues against its own customer invoices (backend model <code>CustomerCreditNote</code>, distinct from Central&#39;s own platform-billing <code>credit_notes</code> ledger). Flat Laravel, <code>module:credit-notes</code> + Spatie RBAC, mirrors the Payments/Invoices notes/timeline/assignee-scope pattern.</li><li><strong>Hard dependency on Invoices</strong> — same pattern as Payments; Marketplace blocks installing Credit Notes until a workspace already has Invoices entitled. <strong>Free Marketplace opt-in</strong> — catalog category <code>billing</code>, <code>is_default_included=false</code> / <code>is_billable=false</code>, <code>sort_order=30</code> (after Payments&#39; <code>20</code>).</li><li>Credit Notes introduces a first-class <strong>lines</strong> child table (<code>customer_credit_note_lines</code>), like Invoices — <code>subtotal</code>/<code>tax_total</code>/<code>total</code> computed server-side from lines.</li><li><strong>Issuing</strong> a draft credit note locks its content; <strong>applying</strong> an issued credit note adds its <code>total</code> to the linked invoice&#39;s <code>amount_credited</code> and recalculates <code>balance_due</code> via <code>CustomerInvoice::recalculateBalanceFromAmounts()</code> — unlike Payments, this does <strong>not</strong> drive the invoice <code>status</code>. <strong>Voiding</strong> is only reachable from <code>draft</code>/<code>issued</code> (before any invoice balance has been touched).</li></ul><p><strong>Backend</strong></p><ul><li>Tables: <code>customer_credit_notes</code>, <code>customer_credit_note_lines</code>, <code>customer_credit_note_notes</code>, <code>customer_credit_note_activities</code></li><li>Auto-numbered (<code>CN-00001</code>, prefix from <code>credit_notes_number_prefix</code> tenant setting)</li><li>Status workflow <code>draft → issued → applied</code>, with <code>void</code> from <code>draft</code>/<code>issued</code> (<code>CustomerCreditNoteStatusEnum</code>); disallowed transitions return a 422 validation error</li><li>Permissions: <code>credit-notes.view|create|update|delete|restore|force.delete|assign|issue|apply|void</code></li><li>Model + factories, controller, form requests, API resources, policy, service, events, <code>AppServiceProvider</code>-registered event subscriber (audit + assignment notification)</li><li>Catalog registration + <code>module_dependencies</code> row via <code>DefaultModuleRegistrar</code> migrations (migrate-only); permissions + default role map additive migrations</li><li>Pest: <code>tests/Feature/Tenant/CustomerCreditNote/CustomerCreditNoteTest.php</code>, <code>tests/Feature/Central/Module/CreditNotesModuleDependencyTest.php</code></li></ul><p><strong>Frontend</strong></p><ul><li><code>src/pages/credit-notes/</code> — list page (KPIs incl. Applied total, filters, DataTable), create/edit form dialog (invoice picker driving default currency/contact/company, line items editor), detail sheet (overview/lines/notes/timeline; issue/apply/void/assign/notes)</li><li>Added to the existing tenant sidebar <strong>Billing</strong> group, after Payments — kept separate from Central Billing nav</li><li><code>customerCreditNoteService</code>, <code>QUERY_KEYS.customerCreditNotes</code>, <code>PERMISSIONS.customerCreditNotes</code></li><li>Invoice detail sheet: new &quot;Credit notes&quot; link to <code>/credit-notes?invoice={id}</code> when Credit Notes is entitled + <code>credit-notes.view</code> is granted</li><li>Notification registry: <code>customer_credit_note.assigned</code> → <code>/credit-notes?credit-note={id}</code></li><li>Playwright: <code>e2e/tests/credit-notes/credit-notes.workflow.spec.ts</code> (<code>npm run test:e2e:credit-notes</code>) — enables both <code>invoices</code> and <code>credit-notes</code> modules, creates and sends an invoice, creates a credit note against it, issues and applies it, and verifies the invoice&#39;s <code>amount_credited</code>/<code>balance_due</code> via the API</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/credit-notes-overview">credit-notes-overview.md</a> / <a href="/user-guide/credit-notes">credit-notes.md</a> (+ <a href="/developer-guide/credit-notes">developer</a> / <a href="/deployment/credit-notes">production</a>)</li><li><a href="/api/tenant-v1-credit-notes">api/tenant-v1-credit-notes.md</a></li><li><a href="/architecture/module-dependencies">Module Dependencies</a> updated — Credit Notes → Invoices marked shipped</li><li><a href="/getting-started/product-roadmap">Product Roadmap</a> — Credit Notes marked shipped in Phase 3; Estimates remains Planned</li><li>Invoices/Payments docs updated to reflect that <code>amount_credited</code>/<code>balance_due</code> are now driven by Credit Notes rather than &quot;still planned&quot;</li></ul><p><strong>Deferred</strong></p><ul><li>Estimates, refunding an already-applied credit note, credit note PDF export / e-mail delivery, standalone credit notes not tied to an invoice, multi-currency conversion</li></ul><hr><h2 id="payments-module-2026-07-31" tabindex="-1">Payments module (2026-07-31) <a class="header-anchor" href="#payments-module-2026-07-31" aria-label="Permalink to &quot;Payments module (2026-07-31)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>Second Phase 3 (Billing) module — customer payments a tenant receives from its own customers (backend model <code>CustomerPayment</code>, distinct from Central platform-billing Payments ledger). Flat Laravel, <code>module:payments</code> + Spatie RBAC, mirrors the Invoices notes/timeline/assignee-scope pattern.</li><li><strong>Hard dependency on Invoices</strong> — the first Phase 3 module to declare a required <code>module_dependencies</code> row; Marketplace blocks installing Payments until a workspace already has Invoices entitled. <strong>Free Marketplace opt-in</strong> — catalog category <code>billing</code>, <code>is_default_included=false</code> / <code>is_billable=false</code>, <code>sort_order=20</code> (after Invoices&#39; <code>10</code>).</li><li>Payments introduces a first-class <strong>allocations</strong> child table (<code>customer_payment_allocations</code>) linking a payment to one or more invoices; allocations are stored on draft payments but only applied to invoice balances once <strong>posted</strong>.</li><li>Posting/voiding a payment drives the previously read-only Invoice balance fields: <code>amount_paid</code> / <code>balance_due</code> and the <code>sent → partial|paid</code> status transition (via <code>CustomerInvoice::recalculateBalanceFromAmounts()</code>), closing the gap called out in the Invoices changelog entry above.</li></ul><p><strong>Backend</strong></p><ul><li>Tables: <code>customer_payments</code>, <code>customer_payment_allocations</code>, <code>customer_payment_notes</code>, <code>customer_payment_activities</code></li><li>Auto-numbered (<code>PAY-00001</code>, prefix from <code>payments_number_prefix</code> tenant setting)</li><li>Status workflow <code>draft → posted → void</code> (<code>CustomerPaymentStatusEnum</code>); disallowed transitions return a 422 validation error</li><li>Permissions: <code>payments.view|create|update|delete|restore|force.delete|assign|post|void</code></li><li>Model + factories, controller, form requests, API resources, policy, service, events, <code>AppServiceProvider</code>-registered event subscriber (audit + assignment notification)</li><li>Catalog registration + <code>module_dependencies</code> row via <code>DefaultModuleRegistrar</code> migrations (migrate-only); permissions + default role map additive migrations</li><li>Pest: <code>tests/Feature/Tenant/CustomerPayment/CustomerPaymentTest.php</code>, <code>tests/Feature/Central/Module/PaymentsModuleDependencyTest.php</code></li></ul><p><strong>Frontend</strong></p><ul><li><code>src/pages/payments/</code> — list page (KPIs incl. Posted total, filters, DataTable), create/edit form dialog (amount/method/paid-at/reference, contact/company/assignee pickers, allocations editor against invoices), detail sheet (overview/allocations/notes/timeline tabs; post/void/assign/notes)</li><li>Added to the existing tenant sidebar <strong>Billing</strong> group, after Invoices — kept separate from Central Billing nav</li><li><code>customerPaymentService</code>, <code>QUERY_KEYS.customerPayments</code>, <code>PERMISSIONS.customerPayments</code> — named distinctly from the pre-existing Central <code>paymentService</code> / <code>PERMISSIONS.payments</code> (platform subscription billing)</li><li>Invoice detail sheet: new &quot;Related payments&quot; link to <code>/payments</code> when Payments is entitled + <code>payments.view</code> is granted</li><li>Notification registry: <code>customer_payment.assigned</code> → <code>/payments?payment={id}</code></li><li>Playwright: <code>e2e/tests/payments/payments.workflow.spec.ts</code> (<code>npm run test:e2e:payments</code>) — enables both <code>invoices</code> and <code>payments</code> modules, creates an invoice, records a payment with an allocation, posts it, verifies the invoice balance/status updates, voids it, and verifies the reversal</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/payments-overview">payments-overview.md</a> / <a href="/user-guide/payments">payments.md</a> (+ <a href="/developer-guide/payments">developer</a> / <a href="/deployment/payments">production</a>)</li><li><a href="/api/tenant-v1-payments">api/tenant-v1-payments.md</a></li><li><a href="/architecture/module-dependencies">Module Dependencies</a> updated — Payments → Invoices marked shipped (was backend-only)</li><li><a href="/getting-started/product-roadmap">Product Roadmap</a> — Payments marked shipped in Phase 3; Credit Notes/Estimates remain Planned</li><li>Invoices docs updated to reflect that <code>amount_paid</code>/<code>balance_due</code> are now driven by Payments rather than &quot;reserved for a future module&quot;</li></ul><p><strong>Deferred</strong></p><ul><li>Credit Notes (<code>amount_credited</code>), Estimates, payment receipt PDF export / e-mail delivery, partial refunds of a posted payment, online payment-gateway capture, multi-currency conversion</li></ul><hr><h2 id="invoices-module-2026-07-31" tabindex="-1">Invoices module (2026-07-31) <a class="header-anchor" href="#invoices-module-2026-07-31" aria-label="Permalink to &quot;Invoices module (2026-07-31)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>First Phase 3 (Billing) module — customer invoices a tenant sends to its own customers (backend model <code>CustomerInvoice</code>, distinct from Central platform-billing <code>Invoice</code>). Flat Laravel, <code>module:invoices</code> + Spatie RBAC, mirrors the Quotations notes/timeline/assignee-scope pattern.</li><li><strong>No hard dependency</strong> — unlike Quotations/Contracts (which require Opportunities), Invoices has no <code>module_dependencies</code> row and installs standalone. <strong>Free Marketplace opt-in</strong> — catalog category <code>billing</code> (<code>category_sort_order=30</code>), <code>is_default_included=false</code> / <code>is_billable=false</code>, <code>sort_order=10</code>.</li><li><strong>Soft optional links</strong>: <code>contact_id</code> / <code>company_id</code> only surfaced/validated when Contacts/Companies is entitled; <code>quotation_id</code> is a plain tenant-scoped existence check (not gated by a <code>LinkableQuotation</code>-style entitlement rule).</li><li>Balance fields (<code>amount_paid</code>, <code>amount_credited</code>, <code>balance_due</code>) are reserved for the still-planned Payments/Credit Notes modules — read-only via this API today.</li></ul><p><strong>Backend</strong></p><ul><li>Tables: <code>customer_invoices</code>, <code>customer_invoice_lines</code>, <code>customer_invoice_notes</code>, <code>customer_invoice_activities</code></li><li>Line items (<code>description</code>, <code>quantity</code>, <code>unit_price</code>, <code>tax_rate</code>) fully replaced on create/update; <code>subtotal</code> / <code>tax_total</code> / <code>total</code> / <code>balance_due</code> computed server-side</li><li>Auto-numbered (<code>INV-00001</code>, prefix from <code>invoices_number_prefix</code> tenant setting)</li><li>Status workflow <code>draft → sent → partial|paid → void</code> (<code>CustomerInvoiceStatusEnum</code>); disallowed transitions return a 422 validation error</li><li>Permissions: <code>invoices.view|create|update|delete|restore|force.delete|assign|send|void</code></li><li>Model + factories, controller, form requests, API resources, policy, service, events, <code>AppServiceProvider</code>-registered event subscriber (audit + assignment notification)</li><li>Catalog registration via <code>DefaultModuleRegistrar</code> migration (migrate-only); permissions + default role map additive migrations</li><li>Pest: <code>tests/Feature/Tenant/CustomerInvoice/CustomerInvoiceTest.php</code></li></ul><p><strong>Frontend</strong></p><ul><li><code>src/pages/invoices/</code> — list page (KPIs incl. Overdue, filters, DataTable), create/edit form dialog (line items editor, contact/company/assignee pickers), detail sheet (overview/lines/notes/timeline tabs; send/void/assign/notes — no accept)</li><li>New tenant sidebar group <strong>Billing</strong> (after Sales) — kept separate from Central Billing nav</li><li><code>customerInvoiceService</code>, <code>QUERY_KEYS.customerInvoices</code>, <code>PERMISSIONS.customerInvoices</code> — named distinctly from the pre-existing Central <code>invoiceService</code> / <code>PERMISSIONS.invoices</code> (platform subscription billing)</li><li>Notification registry: <code>customer_invoice.assigned</code> → <code>/invoices?invoice={id}</code></li><li>Playwright: <code>e2e/tests/invoices/invoices.workflow.spec.ts</code> (<code>npm run test:e2e:invoices</code>) — enable module, create, search, send, void, timeline</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/invoices-overview">invoices-overview.md</a> / <a href="/user-guide/invoices">invoices.md</a> (+ <a href="/developer-guide/invoices">developer</a> / <a href="/deployment/invoices">production</a>)</li><li><a href="/api/tenant-v1-invoices">api/tenant-v1-invoices.md</a></li><li><a href="/architecture/module-dependencies">Module Dependencies</a> updated (Invoices → Contacts/Companies/Quotations optional; Payments → Invoices required, backend-only for now)</li><li><a href="/getting-started/product-roadmap">Product Roadmap</a> — Invoices marked shipped in Phase 3; Payments/Credit Notes/Estimates remain Planned</li></ul><p><strong>Deferred</strong></p><ul><li>Payments (posting <code>amount_paid</code>, auto <code>partial</code>/<code>paid</code> transitions), Credit Notes (<code>amount_credited</code>), Estimates, invoice PDF export / e-mail delivery, multi-currency conversion</li></ul><hr><h2 id="lead-import-first-note-2026-07-31" tabindex="-1">Lead import first note (2026-07-31) <a class="header-anchor" href="#lead-import-first-note-2026-07-31" aria-label="Permalink to &quot;Lead import first note (2026-07-31)&quot;">​</a></h2><p>Bulk lead import supports an optional <strong>Note</strong> column. When mapped and non-empty, import creates a first note on new leads (and appends a note when updating duplicates). Empty note cells are skipped. Template, wizard field list, Pest, and Playwright import coverage updated.</p><h2 id="lead-import-numeric-phone-cast-2026-07-31" tabindex="-1">Lead import numeric phone cast (2026-07-31) <a class="header-anchor" href="#lead-import-numeric-phone-cast-2026-07-31" aria-label="Permalink to &quot;Lead import numeric phone cast (2026-07-31)&quot;">​</a></h2><p>Bulk lead import no longer fails with “phone must be a string” when Excel/CSV parsers return phone cells as numbers. <code>LeadImportMapper</code> casts string fields before validation.</p><h2 id="overdue-filter-for-tasks-todos-2026-07-31" tabindex="-1">Overdue filter for Tasks &amp; ToDos (2026-07-31) <a class="header-anchor" href="#overdue-filter-for-tasks-todos-2026-07-31" aria-label="Permalink to &quot;Overdue filter for Tasks &amp; ToDos (2026-07-31)&quot;">​</a></h2><p>List and board APIs accept <code>overdue=true</code> for open items with <code>due_at</code> in the past. Tasks and ToDos UIs expose an <strong>Overdue</strong> checkbox; Tasks also toggles the filter from the Overdue KPI card.</p><h2 id="todos-module-2026-07-31" tabindex="-1">ToDos module (2026-07-31) <a class="header-anchor" href="#todos-module-2026-07-31" aria-label="Permalink to &quot;ToDos module (2026-07-31)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>New personal checklist module (<code>todos</code>), separate from Tasks. Default-included, non-billable CRM catalog row (<code>sort_order</code> 21, icon <code>list-todo</code>).</li><li>Creator-scoped visibility via <code>ScopesToCreator</code> — users see only their own to-dos; workspace owner (<code>superadmin</code>) can view all.</li><li>Creator-only update/delete (owner may view others’ items but cannot mutate them).</li></ul><p><strong>Backend</strong></p><ul><li>Table <code>todos</code>; model, policy, service, board + CRUD API under <code>module:todos</code> + <code>todos.*</code>.</li><li>Soft-delete route binding (<code>withTrashed</code>) and whitelist for list <code>sort</code> / <code>direction</code>.</li><li>Local demo: <code>TodosSeeder</code> + dataset counts in <code>config/local-demo.php</code>.</li><li>Permissions: <code>view</code> · <code>create</code> · <code>update</code> · <code>delete</code> (admin/manager/staff).</li><li>Pest: <code>tests/Feature/Tenant/Todo/TodoTest.php</code> (CRUD, creator/admin scope, owner view-only, sort safety, soft-delete show, module gate, isolation).</li></ul><p><strong>Frontend</strong></p><ul><li>Board (default) + list; form dialog + detail sheet; nav gated by <code>module:todos</code> + <code>todos.view</code>.</li><li>Board drag disabled for non-creators (owner view-only cards).</li><li>Playwright: <code>npm run test:e2e:todos</code> (workflow + multi-user visibility).</li></ul><p><strong>Docs / Website</strong></p><ul><li>User / developer / production / API guides; database + roadmap + this note.</li><li>Marketing <code>MODULES</code> entry and included-module copy updated for ToDos (including FAQ cancel copy).</li></ul><h2 id="marketing-catalog-currency-uses-modules-currency-2026-07-31" tabindex="-1">Marketing catalog currency uses modules.currency (2026-07-31) <a class="header-anchor" href="#marketing-catalog-currency-uses-modules-currency-2026-07-31" aria-label="Permalink to &quot;Marketing catalog currency uses modules.currency (2026-07-31)&quot;">​</a></h2><p>Public <code>GET /api/central/v1/public/modules</code> now labels paid prices with each module’s <strong>catalog currency</strong> (<code>modules.currency</code>, typically USD as in Central Modules). It no longer uses <code>system_settings.currency</code> (workspace default), which can be PKR/EUR/etc. and mislabeled catalog USD amounts.</p><h2 id="marketing-site-public-catalog-stats-api-2026-07-31" tabindex="-1">Marketing site public catalog + stats API (2026-07-31) <a class="header-anchor" href="#marketing-site-public-catalog-stats-api-2026-07-31" aria-label="Permalink to &quot;Marketing site public catalog + stats API (2026-07-31)&quot;">​</a></h2><ul><li>Central public endpoints for the EloSync website homepage: <ul><li><code>GET /api/central/v1/public/stats</code> — live Active Workspaces, Modules Installed, Catalog Modules (+ uptime / platform currency)</li><li><code>GET /api/central/v1/public/modules</code> — marketplace cards with <strong>Available / In Progress / Planned</strong> and <strong>Included / Free / Paid</strong> tags; paid prices always use the central application currency</li></ul></li><li>Catalog modules gain <code>availability</code> (<code>available</code> | <code>in_progress</code> | <code>planned</code>) alongside existing commercial <code>status</code> / <code>is_billable</code> flags</li><li>SaaS-Website Trust + Module Marketplace sections consume these APIs (<code>NEXT_PUBLIC_API_URL</code>); CORS supports <code>MARKETING_URL</code></li><li>Pest: <code>tests/Feature/Central/Public/PublicPlatformTest.php</code></li></ul><h2 id="rebrand-saleos-→-elosync-2026-07-31" tabindex="-1">Rebrand SaleOS → EloSync (2026-07-31) <a class="header-anchor" href="#rebrand-saleos-→-elosync-2026-07-31" aria-label="Permalink to &quot;Rebrand SaleOS → EloSync (2026-07-31)&quot;">​</a></h2><p>Product name, docs site, and operator examples are now <strong>EloSync</strong> (<code>docs.elosync.com</code>, <code>*.elosync.com</code>).</p><p><strong>Breaking:</strong> Custom lead webhook HMAC / API-key headers are renamed — <code>X-SaleOS-Signature</code> / <code>X-SaleOS-Timestamp</code> / <code>X-SaleOS-Key</code> → <code>X-EloSync-Signature</code> / <code>X-EloSync-Timestamp</code> / <code>X-EloSync-Key</code>. Update integrators (Zapier, Make, form plugins). Branded-domain DNS defaults are <code>_elosync-verification</code> / <code>elosync-verify-…</code> (override with <code>BRANDED_TXT_PREFIX</code> if needed).</p><h2 id="marketplace-badges-dependents-copy-catalog-versioning-2026-07-31" tabindex="-1">Marketplace badges, dependents copy, catalog versioning (2026-07-31) <a class="header-anchor" href="#marketplace-badges-dependents-copy-catalog-versioning-2026-07-31" aria-label="Permalink to &quot;Marketplace badges, dependents copy, catalog versioning (2026-07-31)&quot;">​</a></h2><ul><li>Tenant Marketplace cards/detail: badges show <strong>Installed</strong> / <strong>Available</strong> / <strong>Billable</strong> / <strong>Pending</strong> (no longer “Included” for free opt-in modules); category tag above module name; long titles no longer overflow the card.</li><li>Detail sheet separates <strong>Dependencies</strong> (modules this one needs) from <strong>Dependents</strong> (installed modules that block remove).</li><li>List API includes <code>already_installed</code>, <code>purchase_pending</code>, and <code>version</code> per row.</li><li><code>DefaultModuleRegistrar</code> accepts create-time <code>version</code> and <code>bumpVersion($slug, $version)</code> for idempotent catalog bumps; docs require bumping <code>modules.version</code> when a module is meaningfully updated.</li></ul><h2 id="marketplace-display-currency-conversion-2026-07-31" tabindex="-1">Marketplace display currency conversion (2026-07-31) <a class="header-anchor" href="#marketplace-display-currency-conversion-2026-07-31" aria-label="Permalink to &quot;Marketplace display currency conversion (2026-07-31)&quot;">​</a></h2><p>Tenant Marketplace list/detail now convert catalog module prices from the catalog currency (typically USD) into the workspace currency for <strong>display only</strong>. Checkout still charges the mapped Stripe/gateway Price in the catalog currency. FX rates come from a cached third-party mid-market feed (<code>CurrencyConversionService</code> / <code>CURRENCY_FX_*</code>). When rates are unavailable, the UI falls back to catalog currency amounts.</p><h2 id="sales-production-readiness-2026-07-31" tabindex="-1">Sales production readiness (2026-07-31) <a class="header-anchor" href="#sales-production-readiness-2026-07-31" aria-label="Permalink to &quot;Sales production readiness (2026-07-31)&quot;">​</a></h2><ul><li><code>LinkableQuotation</code> keeps SoftDeletes (only drops <code>TenantScope</code>) so soft-deleted quotations cannot be linked.</li><li><code>QuotationPolicy::send</code> / <code>accept</code> mirror view/update assignee scoping.</li><li>Contracts: content updates are <strong>draft-only</strong> (<code>Contract::isEditable()</code>); assignment uses dedicated <code>assign()</code> (mirrors Quotations).</li><li>SPA: Quotation and Contract list/detail <strong>Edit</strong> actions are draft-only.</li><li>Pest: staff assignee scope for Quotations/Contracts; soft-deleted quotation link rejected; non-draft contract edit rejected; send/accept assignee isolation.</li><li>Docs: API index, entitlements catalog, database schema, tenant free-install list, and Playwright Sales suites synced.</li></ul><h2 id="sales-audit-remediations-2026-07-31" tabindex="-1">Sales audit remediations (2026-07-31) <a class="header-anchor" href="#sales-audit-remediations-2026-07-31" aria-label="Permalink to &quot;Sales audit remediations (2026-07-31)&quot;">​</a></h2><ul><li>Quotations: content/<code>lines</code> updates are <strong>draft-only</strong> (<code>Quotation::isEditable()</code>); assignment stays available via <code>POST …/assign</code>.</li><li>Quotations: <code>POST …/status</code> requires <code>quotations.send</code> for <code>sent</code> and <code>quotations.accept</code> for <code>accepted</code> (other transitions still use <code>quotations.update</code>).</li><li>Contracts: <code>LinkableQuotation</code> requires the quotation’s opportunity to match the contract’s opportunity.</li><li>SPA: Edit quotation action is draft-only; Playwright RequireAccess coverage extended to Sales routes.</li><li>Docs: API + developer guides updated for the above.</li></ul><h2 id="quotations-contracts-modules-2026-07-31" tabindex="-1">Quotations &amp; Contracts modules (2026-07-31) <a class="header-anchor" href="#quotations-contracts-modules-2026-07-31" aria-label="Permalink to &quot;Quotations &amp; Contracts modules (2026-07-31)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>Two lean Sales modules on top of Opportunities, mirroring its assignee-scope + notes + timeline patterns. Flat Laravel, <code>module:quotations</code> / <code>module:contracts</code> + Spatie RBAC. <strong>Free Marketplace opt-in</strong> — catalog category <code>sales</code>, <code>is_default_included=false</code> / <code>is_billable=false</code>; <code>quotations</code> <code>sort_order=50</code>, <code>contracts</code> <code>sort_order=60</code>.</li><li><strong>Hard dependency</strong>: both <code>quotations</code> and <code>contracts</code> require <strong>Opportunities</strong> — Marketplace install blocks until Opportunities is entitled (<code>module_dependencies</code> migration, mirrors Meetings → Calendar).</li><li><strong>Soft optional dependency</strong>: Contracts may link <code>quotation_id</code> only when Quotations is also entitled — validated by <code>LinkableQuotation</code> (mirrors <code>LinkableCompanyForOpportunity</code>).</li></ul><p><strong>Backend — Quotations</strong></p><ul><li>Tables: <code>quotations</code>, <code>quotation_lines</code>, <code>quotation_notes</code>, <code>quotation_activities</code></li><li>Line items (<code>description</code>, <code>quantity</code>, <code>unit_price</code>, <code>tax_rate</code>) fully replaced on create/update; <code>subtotal</code> / <code>tax_total</code> / <code>total</code> computed server-side</li><li>Status workflow <code>draft → sent → accepted|rejected|expired</code> (<code>QuotationStatusEnum</code>); disallowed transitions — including re-entering the same status — return a 422 validation error</li><li>Permissions: <code>quotations.view|create|update|delete|restore|force.delete|assign|send|accept</code></li><li>Pest: <code>tests/Feature/Tenant/Quotation/QuotationTest.php</code>, <code>tests/Feature/Central/Module/QuotationsModuleDependencyTest.php</code></li></ul><p><strong>Backend — Contracts</strong></p><ul><li>Tables: <code>contracts</code>, <code>contract_notes</code>, <code>contract_activities</code> (no line items — a contract is a single agreement record)</li><li>Status workflow <code>draft → active → expired|terminated</code> (<code>ContractStatusEnum</code>); same same-status/invalid-transition guard as Quotations</li><li>Permissions: <code>contracts.view|create|update|delete|restore|force.delete|assign</code></li><li>Pest: <code>tests/Feature/Tenant/Contract/ContractTest.php</code>, <code>tests/Feature/Central/Module/ContractsModuleDependencyTest.php</code></li></ul><p><strong>Both modules</strong></p><ul><li>Model + factory, controller, form requests, API resources, policy, service, events, <code>AppServiceProvider</code>-registered event subscriber (audit + assignment notification)</li><li>Catalog registration via <code>DefaultModuleRegistrar</code> migration (migrate-only); permissions + default role map additive migrations</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/quotations-overview">quotations-overview.md</a> / <a href="/user-guide/quotations">quotations.md</a> (+ <a href="/developer-guide/quotations">developer</a> / <a href="/deployment/quotations">production</a>)</li><li><a href="/user-guide/contracts-overview">contracts-overview.md</a> / <a href="/user-guide/contracts">contracts.md</a> (+ <a href="/developer-guide/contracts">developer</a> / <a href="/deployment/contracts">production</a>)</li><li><a href="/api/tenant-v1-quotations">api/tenant-v1-quotations.md</a>, <a href="/api/tenant-v1-contracts">api/tenant-v1-contracts.md</a></li><li><a href="/architecture/module-dependencies">Module Dependencies</a> updated (Quotations/Contracts → Opportunities now shipped; Contracts → Quotations optional)</li></ul><p><strong>Deferred</strong></p><ul><li>Quotation PDF export / e-signature, contract renewal reminders, multi-currency conversion, Opportunity → Quotation → Contract conversion wizard</li></ul><hr><h2 id="opportunities-module-2026-07-30" tabindex="-1">Opportunities module (2026-07-30) <a class="header-anchor" href="#opportunities-module-2026-07-30" aria-label="Permalink to &quot;Opportunities module (2026-07-30)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>Sales deals module with <strong>pipeline stages + Kanban board inside Opportunities</strong> (Sales Pipeline is not a separate Marketplace SKU). Mirrors Leads board patterns and Activities soft related links. Flat Laravel, <code>module:opportunities</code> + Spatie RBAC. <strong>Free Marketplace opt-in</strong> — catalog category <code>sales</code>, <code>is_default_included=false</code> / <code>is_billable=false</code> / <code>sort_order=40</code>; tenants enable it manually (only Leads + Tasks auto-install).</li></ul><p><strong>Backend</strong></p><ul><li>Tables: <code>opportunity_stages</code>, <code>opportunities</code>, <code>opportunity_notes</code>, <code>opportunity_activities</code></li><li>Seeded stages: Prospecting → Qualification → Proposal → Negotiation → Won / Lost</li><li>Soft optional FKs: <code>contact_id</code> / <code>company_id</code> / <code>lead_id</code> (entitlement-validated when set)</li><li>Board / stats / stage change / assign / notes / restore / force delete</li><li>Permissions: <code>opportunities.view|create|update|delete|restore|force.delete|assign</code></li><li>Catalog registration via <code>DefaultModuleRegistrar</code> migration (migrate-only)</li><li>Pest: <code>tests/Feature/Tenant/Opportunity/OpportunityTest.php</code></li></ul><p><strong>Frontend</strong></p><ul><li>SPA mirrors Leads (board default + table, form dialog, detail drawer) — ship with Opportunities nav gated by module + permission</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/opportunities-overview">opportunities-overview.md</a> (+ user / developer / production)</li><li><a href="/api/tenant-v1-opportunities">api/tenant-v1-opportunities.md</a></li></ul><p><strong>Deferred</strong></p><ul><li>Separate Sales Pipeline SKU, custom stage admin UI, Lead → Opportunity conversion wizard, realtime board sync, export / import</li></ul><hr><h2 id="quotations-contracts-spa-2026-07-31" tabindex="-1">Quotations &amp; Contracts SPA (2026-07-31) <a class="header-anchor" href="#quotations-contracts-spa-2026-07-31" aria-label="Permalink to &quot;Quotations &amp; Contracts SPA (2026-07-31)&quot;">​</a></h2><p>Tenant Application pages for Quotations and Contracts (list, form with line items for quotes, detail sheets with status actions), Sales nav group, Playwright <code>test:e2e:quotations</code> / <code>test:e2e:contracts</code>, and notification deep-links for assignment.</p><h2 id="marketing-site-forge-ci-2026-07-30" tabindex="-1">Marketing site Forge CI (2026-07-30) <a class="header-anchor" href="#marketing-site-forge-ci-2026-07-30" aria-label="Permalink to &quot;Marketing site Forge CI (2026-07-30)&quot;">​</a></h2><p>EloSync marketing repo (<code>SaaS-Website</code>) publishes a static Next.js export to <code>build-artifacts</code> on each push to <code>main</code> (same pattern as SPA/Docs). Forge deploys that branch with activate-only script — no Node on the server. See <a href="/deployment/laravel-forge">Laravel Forge</a> §4 Marketing.</p><h2 id="marketing-catalog-pricing-sync-2026-07-30" tabindex="-1">Marketing catalog pricing sync (2026-07-30) <a class="header-anchor" href="#marketing-catalog-pricing-sync-2026-07-30" aria-label="Permalink to &quot;Marketing catalog pricing sync (2026-07-30)&quot;">​</a></h2><p>EloSync marketing site and docs now mirror Central catalog commercial flags: <strong>Included free</strong> (Leads, Tasks), <strong>Free to install</strong> (other CRM modules), <strong>Paid</strong> Branded at <strong>$29/mo · $290/yr</strong>. Entitlements catalog table corrected (opt-in CRM modules are not default-included).</p><h2 id="tenant-marketplace-remove-modules-2026-07-30" tabindex="-1">Tenant Marketplace remove modules (2026-07-30) <a class="header-anchor" href="#tenant-marketplace-remove-modules-2026-07-30" aria-label="Permalink to &quot;Tenant Marketplace remove modules (2026-07-30)&quot;">​</a></h2><p>Workspace owners (and anyone with <code>marketplace.purchase</code>) can <strong>remove</strong> opt-in modules from Marketplace — Install / Subscribe to add, Remove / Cancel subscription to drop access. Core default-included modules (Leads, Tasks) stay non-removable; hard dependents must be removed first (e.g. Meetings before Calendar). Re-installing a previously cancelled module reactivates the same subscription row.</p><p><strong>Fix (same day):</strong> Cancel eligibility follows catalog <code>is_default_included</code> (not historical <code>source=included</code>). Data migration marks optional CRM modules opt-in and rewrites their included subscriptions to <code>purchased</code> so Remove appears for workspaces that had them pre-opt-in.</p><ul><li>API: <code>POST /api/tenant/v1/marketplace/modules/{module}/cancel</code>; detail adds <code>can_cancel</code>, <code>blocking_dependents</code>, <code>subscription_source</code></li><li>UI: Marketplace module detail sheet Remove / Cancel subscription + confirmation</li><li>Docs: <a href="/api/tenant-v1-marketplace">tenant-v1-marketplace</a>, <a href="/developer-guide/entitlements">entitlements</a></li></ul><h2 id="default-module-policy-2026-07-30" tabindex="-1">Default module policy (2026-07-30) <a class="header-anchor" href="#default-module-policy-2026-07-30" aria-label="Permalink to &quot;Default module policy (2026-07-30)&quot;">​</a></h2><p>New workspaces auto-install <strong>Leads</strong> and <strong>Tasks</strong> only. Contacts, Companies, Activities, Opportunities, Calendar, Meetings, and Communication Templates stay <strong>free</strong> (<code>is_billable=false</code>) but <strong>opt-in</strong> (<code>is_default_included=false</code>) via Marketplace. Existing workspace subscriptions are not removed.</p><h2 id="activities-module-2026-07-30" tabindex="-1">Activities module (2026-07-30) <a class="header-anchor" href="#activities-module-2026-07-30" aria-label="Permalink to &quot;Activities module (2026-07-30)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>CRM engagements module; mirrors Contacts/Companies (flat Laravel, <code>module:activities</code> + Spatie RBAC). <strong>Free Marketplace opt-in</strong> — catalog <code>is_default_included=false</code> / <code>is_billable=false</code> / <code>sort_order=28</code>; tenants enable it manually (only Leads + Tasks auto-install).</li></ul><p><strong>Backend</strong></p><ul><li>Tables: <code>activities</code>, <code>activity_notes</code>, <code>activity_activities</code></li><li>Types: <code>call</code> | <code>email</code> | <code>note</code> | <code>follow_up</code> | <code>other</code>; complete via <code>POST /activities/{id}/complete</code></li><li>Related FKs: <code>contact_id</code> / <code>company_id</code> / <code>lead_id</code> (at least one required; soft module entitlement)</li><li>Mirrors <code>crm_activity_logged</code> / <code>crm_activity_completed</code> onto related Contact/Company/Lead timelines</li><li>Permissions: <code>activities.view|create|update|delete|restore|force.delete|assign|complete</code> (staff defaults include <code>view</code> + <code>complete</code>, mirroring Tasks)</li><li>Pest: <code>tests/Feature/Tenant/Activity/ActivityTest.php</code> (16 tests)</li></ul><p><strong>Frontend</strong></p><ul><li>Activities list / form dialog / detail drawer (Overview, Notes, Activity tabs); nav after Meetings</li><li>Tenant dashboard: <strong>Recent Activities</strong> widget + <strong>Log Activity</strong> quick action</li><li>Playwright: <code>npm run test:e2e:activities</code> (<code>e2e/tests/activities/</code>)</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/activities-overview">activities-overview.md</a> (+ user / developer / production)</li><li><a href="/api/tenant-v1-activities">api/tenant-v1-activities.md</a></li></ul><p><strong>Deferred</strong></p><ul><li>Calendar projection, Meetings types, unified system-timeline aggregator, Communication Template placeholders</li></ul><hr><h2 id="companies-module-2026-07-30" tabindex="-1">Companies module (2026-07-30) <a class="header-anchor" href="#companies-module-2026-07-30" aria-label="Permalink to &quot;Companies module (2026-07-30)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>CRM organizations module; mirrors Contacts/Leads/Tasks (flat Laravel, <code>module:companies</code> + Spatie RBAC). <strong>Free Marketplace opt-in</strong> — catalog <code>is_default_included=false</code> / <code>is_billable=false</code> / <code>sort_order=12</code>; tenants enable it manually (only Leads + Tasks auto-install).</li></ul><p><strong>Backend</strong></p><ul><li>Tables: <code>companies</code>, <code>company_notes</code>, <code>company_activities</code>; <code>contacts.company_id</code> FK</li><li><code>CompanyService</code>, events/subscriber (audit + assignment mail), tenant API routes</li><li>Permissions: <code>companies.view|create|update|delete|restore|force.delete|assign</code></li><li>Contact writes sync legacy <code>company</code> string from linked Company name when <code>company_id</code> is set; resources expose <code>linked_company</code></li><li>Communication Templates placeholder provider for Companies</li><li>Pest: <code>tests/Feature/Tenant/Company/CompanyTest.php</code></li></ul><p><strong>Frontend</strong></p><ul><li>Companies list / form dialog / detail drawer (Overview, Notes, Activity tabs); nav gated by module + permission, positioned between Leads and Contacts</li><li>Tenant dashboard: <strong>Recent Companies</strong> widget + <strong>Create Company</strong> quick action (gated by <code>module:companies</code> + <code>companies.view</code>/<code>companies.create</code>)</li><li>Contact form company picker when Companies is entitled; list/detail prefer linked company name over legacy string</li><li>Playwright: <code>npm run test:e2e:companies</code> (<code>e2e/tests/companies/</code>)</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/companies-overview">companies-overview.md</a> (+ user / developer / production)</li><li><a href="/api/tenant-v1-companies">api/tenant-v1-companies.md</a></li></ul><p><strong>Deferred</strong></p><ul><li>Lead convert-to-Company, legacy company-string backfill job, Meta invent Companies</li></ul><hr><h2 id="contacts-module-2026-07-30" tabindex="-1">Contacts module (2026-07-30) <a class="header-anchor" href="#contacts-module-2026-07-30" aria-label="Permalink to &quot;Contacts module (2026-07-30)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>Third product module; mirrors Leads/Tasks (flat Laravel, <code>module:contacts</code> + Spatie RBAC). <strong>Free Marketplace opt-in</strong> — catalog <code>is_default_included=false</code> / <code>is_billable=false</code>; tenants enable it manually (only Leads + Tasks auto-install).</li></ul><p><strong>Backend</strong></p><ul><li>Tables: <code>contacts</code>, <code>contact_notes</code>, <code>contact_activities</code>; <code>leads.contact_id</code> FK</li><li><code>ContactService</code>, events/subscriber (audit + assignment mail), tenant API routes</li><li>Permissions: <code>contacts.view|create|update|delete|restore|force.delete|assign</code></li><li><code>LeadService::convert()</code> creates/links a real Contact when <code>contacts</code> is entitled (<code>conversion_meta.stub = false</code>); otherwise conversion stays the earlier status-only placeholder</li><li>Convert hardening: transactional + row lock; requires <code>contacts.create</code>; preserves lead assignee; <code>LeadPolicy::convert</code> matches assignee scope; stub converts can complete once Contacts is installed; assignee eligibility mirrors Leads</li><li>Communication Templates placeholder provider for Contacts</li><li>Pest: <code>tests/Feature/Tenant/Contact/ContactTest.php</code> (+ convert authz/backfill cases in LeadTest)</li></ul><p><strong>Frontend</strong></p><ul><li>Contacts list / form dialog / detail drawer (Overview, Notes, Activity tabs); nav gated by module + permission, positioned between Leads and Tasks</li><li>Tenant dashboard: <strong>Recent Contacts</strong> widget + <strong>Create Contact</strong> quick action (gated by <code>module:contacts</code> + <code>contacts.view</code>/<code>contacts.create</code>); dashboard cache invalidated after contact save / lead convert</li><li>Lead detail drawer shows a <strong>View contact</strong> link after a lead converts to a real contact</li><li>Playwright: <code>npm run test:e2e:contacts</code> (<code>e2e/tests/contacts/</code>)</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/contacts-overview">contacts-overview.md</a> (+ user / developer / production)</li><li><a href="/api/tenant-v1-contacts">api/tenant-v1-contacts.md</a></li></ul><hr><h2 id="meeting-completion-2026-07-29" tabindex="-1">Meeting completion (2026-07-29) <a class="header-anchor" href="#meeting-completion-2026-07-29" aria-label="Permalink to &quot;Meeting completion (2026-07-29)&quot;">​</a></h2><p>Meetings can be <strong>marked completed</strong> (detail action) or <strong>auto-completed</strong> after <code>ends_at</code> via <code>meetings:auto-complete</code> (every 5 minutes). Status is now <code>scheduled</code> | <code>completed</code> | <code>cancelled</code>. Completing cancels pending reminders, keeps the Calendar historical event as <code>scheduled</code>, and does not delete remote Zoom/Google links. List filter <strong>Past</strong> is replaced by <strong>Completed</strong>. API: <code>POST /meetings/{id}/complete</code> (<code>meetings.update</code>). Migration adds <code>completed_at</code> and backfills already-ended scheduled meetings.</p><hr><h2 id="lead-task-restore-force-delete-2026-07-28" tabindex="-1">Lead &amp; task restore / force delete (2026-07-28) <a class="header-anchor" href="#lead-task-restore-force-delete-2026-07-28" aria-label="Permalink to &quot;Lead &amp; task restore / force delete (2026-07-28)&quot;">​</a></h2><p>Leads and Tasks support trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong>. Soft delete is unchanged. Restore is granted to workspace <strong>admin</strong> (and owner); force delete is owner-only by default (<code>leads.force.delete</code> / <code>tasks.force.delete</code>) and can be assigned on Roles. API: <code>POST …/restore</code>, <code>DELETE …/force</code>.</p><hr><h2 id="latest-note-follow-up-previews-on-leads-tasks-lists-2026-07-28" tabindex="-1">Latest note &amp; follow-up previews on Leads/Tasks lists (2026-07-28) <a class="header-anchor" href="#latest-note-follow-up-previews-on-leads-tasks-lists-2026-07-28" aria-label="Permalink to &quot;Latest note &amp; follow-up previews on Leads/Tasks lists (2026-07-28)&quot;">​</a></h2><p>Lead and task <strong>table</strong> and <strong>board</strong> views now show the latest note (and, for leads, the next pending follow-up). Hover the truncated preview to read the full note or follow-up details. List/board API payloads include <code>latest_note</code> and (leads) <code>next_follow_up</code>.</p><hr><h2 id="meetings-create-form-crash-after-visiting-settings-2026-07-28" tabindex="-1">Meetings create form crash after visiting Settings (2026-07-28) <a class="header-anchor" href="#meetings-create-form-crash-after-visiting-settings-2026-07-28" aria-label="Permalink to &quot;Meetings create form crash after visiting Settings (2026-07-28)&quot;">​</a></h2><p>Fixed an intermittent SPA “Something went wrong” error when opening New Meeting after Settings (or any page that filled the shared tenant-settings React Query cache). The meeting form unwrapped that cache to a bare array and called <code>.find</code>, while Settings stored the API envelope — so <code>.find</code> ran on an object. Meetings now uses a shared <code>useTenantSettingsQuery</code> helper with the same envelope shape (and a defensive normalizer).</p><hr><h2 id="meeting-list-vs-edit-timezone-mismatch-2026-07-28" tabindex="-1">Meeting list vs edit timezone mismatch (2026-07-28) <a class="header-anchor" href="#meeting-list-vs-edit-timezone-mismatch-2026-07-28" aria-label="Permalink to &quot;Meeting list vs edit timezone mismatch (2026-07-28)&quot;">​</a></h2><p>Meetings (and Calendar list columns) now format start/end times with an explicit timezone: workspace Settings when loaded, otherwise the meeting/event <code>timezone</code> saved on the record. This fixes the case where the edit form showed the correct Asia/Karachi wall clock (e.g. 4:00 PM) while the list still showed the UTC clock (e.g. 11:00 AM) after a Central settings fallback. Tenant settings bootstrap also refuses to adopt Central’s timezone for an authenticated workspace shell.</p><hr><h2 id="workspace-timezone-meeting-calendar-times-2026-07-28" tabindex="-1">Workspace timezone meeting/calendar times (2026-07-28) <a class="header-anchor" href="#workspace-timezone-meeting-calendar-times-2026-07-28" aria-label="Permalink to &quot;Workspace timezone meeting/calendar times (2026-07-28)&quot;">​</a></h2><p>Scheduled datetimes (meetings, calendar, task due dates, lead follow-ups) no longer shift when the workspace timezone is not UTC. Eloquent stores those fields as UTC instants (<code>UtcDateTime</code> cast); the SPA continues to display and edit them in the workspace timezone from Settings. Meeting create/edit uses the workspace timezone (read-only on the form) instead of a separate picker that did not drive conversion. Meetings/Calendar list UIs now re-render when the workspace timezone loads or changes so times do not stick on UTC after Settings bootstrap.</p><hr><h2 id="web-push-profile-false-not-supported-2026-07-27" tabindex="-1">Web Push Profile false &quot;not supported&quot; (2026-07-27) <a class="header-anchor" href="#web-push-profile-false-not-supported-2026-07-27" aria-label="Permalink to &quot;Web Push Profile false &quot;not supported&quot; (2026-07-27)&quot;">​</a></h2><p>Profile Desktop notifications no longer sticks on “This browser does not support Web Push” when notification permission is already granted but no service worker is registered. Status lookup uses <code>getRegistration()</code> instead of hanging on <code>serviceWorker.ready</code>.</p><hr><h2 id="desktop-notification-prompt-—-dismiss-once-forever-2026-07-27" tabindex="-1">Desktop notification prompt — dismiss once forever (2026-07-27) <a class="header-anchor" href="#desktop-notification-prompt-—-dismiss-once-forever-2026-07-27" aria-label="Permalink to &quot;Desktop notification prompt — dismiss once forever (2026-07-27)&quot;">​</a></h2><p>The post-login “Enable desktop notifications?” dialog no longer reappears on every login after “Not now”. Dismissal is stored in <code>localStorage</code> for that browser; users can still enable later from Profile or the Notification Center.</p><hr><h2 id="meetings-host-filter-crash-after-visiting-leads-tasks-2026-07-27" tabindex="-1">Meetings host filter crash after visiting Leads/Tasks (2026-07-27) <a class="header-anchor" href="#meetings-host-filter-crash-after-visiting-leads-tasks-2026-07-27" aria-label="Permalink to &quot;Meetings host filter crash after visiting Leads/Tasks (2026-07-27)&quot;">​</a></h2><p>Fixed an intermittent SPA “Something went wrong” error on Meetings. The Meetings pages unwrapped the shared users React Query cache to a bare array while Leads/Tasks stored the API envelope, so navigating Leads → Meetings called <code>.map</code> on an object. Meetings now uses a shared <code>useWorkspaceUsersQuery</code> helper with the same envelope shape (and a defensive normalizer).</p><hr><h2 id="password-show-hide-on-all-secret-fields-2026-07-26" tabindex="-1">Password show/hide on all secret fields (2026-07-26) <a class="header-anchor" href="#password-show-hide-on-all-secret-fields-2026-07-26" aria-label="Permalink to &quot;Password show/hide on all secret fields (2026-07-26)&quot;">​</a></h2><p>All password and secret inputs in the SPA now use the shared <code>PasswordInput</code> control with an eye toggle (show/hide), including profile, users, tenants, mail settings, payment gateway credentials, and meeting integrations. Auth screens already had this pattern.</p><hr><h2 id="meta-app-setup-operator-guide-2026-07-25" tabindex="-1">Meta App Setup operator guide (2026-07-25) <a class="header-anchor" href="#meta-app-setup-operator-guide-2026-07-25" aria-label="Permalink to &quot;Meta App Setup operator guide (2026-07-25)&quot;">​</a></h2><p>Docs-only: added <a href="/developer-guide/meta-app-setup">Meta App Setup</a> — create Meta Developer App (Marketing API use case), App Domains, Lead Ads permissions, OAuth vs webhook URLs, Central <code>META_LEAD_ADS_*</code> / integrations API, tenant Connect Meta, production gates, and troubleshooting. Linked from Meta Lead Ads, Leads deployment, installation, user overview, Tenant Leads API, and Developer Guide index.</p><hr><h2 id="platform-domain-auto-generated-on-signup-central-create-2026-07-25" tabindex="-1">Platform domain auto-generated on signup / Central create (2026-07-25) <a class="header-anchor" href="#platform-domain-auto-generated-on-signup-central-create-2026-07-25" aria-label="Permalink to &quot;Platform domain auto-generated on signup / Central create (2026-07-25)&quot;">​</a></h2><p>Central tenant create/update and public workspace registration no longer accept a domain field. The platform hostname is always <code>{slug}.{PLATFORM_DOMAIN_SUFFIXES}</code> (company name spaces/special characters → hyphens via slug). Custom domains stay Branded self-service (Settings → Domain after purchase). SPA register + Central tenant form hide the domain input; Pest/e2e updated.</p><hr><h2 id="backend-env-example-production-template-2026-07-25" tabindex="-1">Backend <code>.env.example</code> production template (2026-07-25) <a class="header-anchor" href="#backend-env-example-production-template-2026-07-25" aria-label="Permalink to &quot;Backend `.env.example` production template (2026-07-25)&quot;">​</a></h2><p>Backend <code>.env.example</code> is production-shaped: <code>https://api.example.com</code>, <code>https://app.example.com</code>, <code>reverb.example.com</code> (443/https), Redis cache/queue required with Reverb, S3 disk, secure session cookies, minimal comments. Secrets stay empty placeholders — never commit real keys. Local install docs override to Herd/<code>localhost</code>.</p><hr><h2 id="laravel-forge-production-deployment-guide-2026-07-25" tabindex="-1">Laravel Forge production deployment guide (2026-07-25) <a class="header-anchor" href="#laravel-forge-production-deployment-guide-2026-07-25" aria-label="Permalink to &quot;Laravel Forge production deployment guide (2026-07-25)&quot;">​</a></h2><p>Docs-only: production-friendly <a href="/deployment/laravel-forge">Laravel Forge Deployment</a> covering three Forge sites (API / SPA / Docs), production <code>.env</code>, deploy scripts, scheduler, queue + Reverb daemons, email, deploy order, and troubleshooting. Installation page, Deployment index, Production Runbook, and Frontend build-artifacts docs now point operators at Forge first for go-live.</p><hr><h2 id="installation-guide-—-local-configuration-plan-2026-07-25" tabindex="-1">Installation guide — local configuration plan (2026-07-25) <a class="header-anchor" href="#installation-guide-—-local-configuration-plan-2026-07-25" aria-label="Permalink to &quot;Installation guide — local configuration plan (2026-07-25)&quot;">​</a></h2><p>Docs-only: new <a href="/getting-started/installation">Installation &amp; Local Configuration</a> page covering backend (Herd, <code>.env</code>, migrate/seed), frontend Vite/<code>VITE_*</code>, VitePress docs, Reverb + Echo alignment, email (log/SMTP/Settings), queues/scheduler/Web Push, optional Stripe/storage, terminal layout, and a verify checklist — with pointers to production runbooks.</p><hr><h2 id="lead-ingest-—-custom-webhook-meta-lead-ads-2026-07-24" tabindex="-1">Lead ingest — Custom Webhook + Meta Lead Ads (2026-07-24) <a class="header-anchor" href="#lead-ingest-—-custom-webhook-meta-lead-ads-2026-07-24" aria-label="Permalink to &quot;Lead ingest — Custom Webhook + Meta Lead Ads (2026-07-24)&quot;">​</a></h2><p>Inbound lead capture through the Lead Source Driver pipeline:</p><ul><li>Shared <code>NormalizedLeadData</code> → <code>LeadDuplicateService</code> → <code>LeadService</code> (no driver DB writes)</li><li><strong>Custom webhooks</strong> per tenant: URL + API key / HMAC (<code>X-EloSync-Timestamp</code> + signature), editable <code>default_source</code></li><li><strong>Meta Lead Ads</strong>: OAuth connect, <strong>Page picker UI</strong>, Page subscribe, shared <code>/webhooks/leads/meta</code>, queue <code>lead-ingest</code></li><li>Leads UI → <strong>Integrations</strong> panel; permission <code>leads.manage_integrations</code></li><li>Production hardening: module entitlement on ingress, body size limits, per-endpoint throttle, Graph timeouts, auth-only <code>needs_reauth</code>, force-delete page reclaim</li><li>Docs: Lead Source Driver Architecture (implemented), Custom Lead Webhook, Meta Lead Ads (shipped)</li><li>Pre-merge hardening: <code>guzzlehttp/guzzle</code> → 7.15.1; SPA <code>postcss</code> + <code>react-router</code> → 8.3.0 (high audit clear); Pest expectations updated for <code>meetings</code> / <code>branded</code> and platform subdomain domains; Larastan typing cleared (lead ingest + meetings/CRM)</li></ul><hr><h2 id="branded-domain-settings-ux-2026-07-24" tabindex="-1">Branded Domain settings UX (2026-07-24) <a class="header-anchor" href="#branded-domain-settings-ux-2026-07-24" aria-label="Permalink to &quot;Branded Domain settings UX (2026-07-24)&quot;">​</a></h2><p>Settings → <strong>Domain</strong> uses a guided three-step flow (enter address → copy-friendly DNS cards → check connection) instead of raw DNS admin rows, aimed at non-technical workspace admins.</p><hr><h2 id="branded-module-—-custom-domains-notification-chrome-2026-07-24" tabindex="-1">Branded module — custom domains + notification chrome (2026-07-24) <a class="header-anchor" href="#branded-module-—-custom-domains-notification-chrome-2026-07-24" aria-label="Permalink to &quot;Branded module — custom domains + notification chrome (2026-07-24)&quot;">​</a></h2><p>Billable marketplace module <code>branded</code> (not default-included) for custom domain mapping and white-label email / web push.</p><ul><li>Tenant self-service <strong>Settings → Domain</strong>: propose hostname (ccTLDs like <code>myai.com.pk</code> / <code>app.domain.co.uk</code> supported), DNS/IP instructions, verify ownership</li><li>Host resolution ignores unverified or non-entitled custom domains (IP pointing alone cannot hijack a workspace)</li><li>Central / registration auto-generate platform subdomains from slug (no client domain field)</li><li>When branded is active: tenant logo / app name in mail chrome and web push icon/title prefix</li><li>Cancel/deactivate branded clears custom-domain verification</li><li>Production hardening: force-delete on remove/expire (unique reclaim), verify fails closed without <code>BRANDED_SERVER_IPV4</code>/<code>CNAME</code>, CORS allowlist for verified custom Origins, hourly stale-claim purge</li><li>Pest + Playwright <code>test:e2e:branded</code>; docs: user / developer / deployment / API</li></ul><hr><h2 id="daily-crm-summary-emails-2026-07-23" tabindex="-1">Daily CRM summary emails (2026-07-23) <a class="header-anchor" href="#daily-crm-summary-emails-2026-07-23" aria-label="Permalink to &quot;Daily CRM summary emails (2026-07-23)&quot;">​</a></h2><p>At <strong>Daily Reminder Time</strong> (<code>task_reminder_time</code>, default <code>09:00</code> local), each workspace sends a mail-only CRM snapshot in addition to the existing task due digest.</p><ul><li>Personal summary: open leads by stage (excludes Won/Lost), open tasks by status (excludes completed/cancelled), scheduled meetings (excludes cancelled; host/attendee distinct)</li><li>Users flagged <strong>Receive all-users daily summary</strong> (<code>receive_all_users_daily_summary</code>) get a user-wise team email (active users only) instead of a personal summary</li><li>Durable delivery ledger <code>daily_summary_deliveries</code> (<code>personal</code> / <code>team</code>) with stale-queued reclaim (45m) and max 5 attempts</li><li>Aggregations run once per tenant per tick (SQL meeting distinct counts)</li><li>Settings label <strong>Daily Reminder Time</strong>; user create/edit checkbox; Playwright flag toggle</li><li>Tests: Pest <code>DailyCrmSummaryNotificationTest</code>, <code>TenantUserDailySummaryFlagTest</code></li><li>Production report: <a href="/deployment/daily-crm-summary">Daily CRM summary</a></li></ul><hr><h2 id="tenant-session-timeout-setting-2026-07-23" tabindex="-1">Tenant session timeout setting (2026-07-23) <a class="header-anchor" href="#tenant-session-timeout-setting-2026-07-23" aria-label="Permalink to &quot;Tenant session timeout setting (2026-07-23)&quot;">​</a></h2><p>Each workspace can set its own session idle/token lifetime, including <strong>never timeout</strong>.</p><ul><li>Tenant Settings → <strong>Security</strong>: <code>session_lifetime_minutes</code> (<code>0</code> = keep users signed in until they sign out)</li><li>Falls back to Central <code>session_lifetime_minutes</code> when unset</li><li>Sanctum tenant tokens use the workspace value (<code>expires_at</code> null when <code>0</code>); SPA idle logout is skipped when <code>0</code></li><li>Password policy remains Central-only</li><li>Tests: Pest tenant settings + remember-me TTL; Vitest <code>session-timeout</code></li><li>Docs: tenant settings user/developer guides</li></ul><hr><h2 id="lead-assignee-exclusion-2026-07-22" tabindex="-1">Lead assignee exclusion (2026-07-22) <a class="header-anchor" href="#lead-assignee-exclusion-2026-07-22" aria-label="Permalink to &quot;Lead assignee exclusion (2026-07-22)&quot;">​</a></h2><p>Workspace owners and users flagged <strong>Exclude from lead assignment</strong> no longer receive leads via import auto-distribute, bulk equal distribute, or manual assignee pickers.</p><ul><li>Backend: <code>users.exclude_from_lead_auto_assign</code>, <code>User::eligibleLeadAssignees</code>, <code>EligibleLeadAssignee</code> validation on assign/create/update/bulk/import</li><li>Frontend: checkbox on tenant user create/edit; assignee pickers filter ineligible users (keeps current assignee so they can be cleared)</li><li>Docs: User Guide Leads + Tenant RBAC, developer Leads notes, tenant leads API</li></ul><h2 id="expired-session-redirects-to-login-2026-07-22" tabindex="-1">Expired session redirects to login (2026-07-22) <a class="header-anchor" href="#expired-session-redirects-to-login-2026-07-22" aria-label="Permalink to &quot;Expired session redirects to login (2026-07-22)&quot;">​</a></h2><p>Expired or revoked tenant sessions no longer leave the SPA on protected pages toasting <strong>Workspace context is required.</strong></p><ul><li>Backend: <code>InitializeTenancy</code> returns <strong>401 Unauthenticated</strong> when a Bearer token is present but cannot resolve a workspace (pruned/revoked/unknown tokens); anonymous requests without context still return <code>400 workspace_required</code></li><li>Frontend: axios treats <code>401</code> and any non-<code>skipAuth</code> <code>400 workspace_required</code> (with or without a Bearer — covers the idle token-clear race) as session expiry — clears the token and hard-redirects to login without toasting; concurrent errors while redirecting are also suppressed</li><li>Idle timeout hard-redirects immediately, then best-effort logout</li><li>Tests: Pest <code>TokenExpirationTest</code>; Vitest <code>src/api/axios.test.ts</code></li><li>Docs: <a href="/developer-guide/authentication">authentication developer</a>, <a href="/user-guide/authentication">authentication user guide</a></li></ul><hr><h2 id="meetings-module-2026-07-22" tabindex="-1">Meetings module (2026-07-22) <a class="header-anchor" href="#meetings-module-2026-07-22" aria-label="Permalink to &quot;Meetings module (2026-07-22)&quot;">​</a></h2><p>Workspace Meetings marketplace module (CRM, default-included) with Calendar projection, <strong>per-tenant</strong> Zoom/Google Meet OAuth credentials + account connect, and one multi-channel reminder.</p><ul><li>Deploy: create migration is production-safe against a leftover pre-redesign <code>meetings</code> table — replaces Meetings-related tables only (preserves other production data), purges <code>calendar_events</code> with <code>source_type=meeting</code>, then creates the current schema</li><li>Backend: meetings/attendees/reminders/provider connections; permissions (<code>view</code>/<code>create</code>/<code>update</code>/<code>delete</code>/<code>view_all</code>/<code>assign_host</code>/<code>manage_integrations</code>); tenant API; migrate-only catalog registration + required Meetings → Calendar dependency</li><li>Providers: each workspace stores its own Zoom/Google OAuth client ID/secret (encrypted); connects a workspace account; manual join URL when provider is <code>none</code>; OAuth token refresh; bounded retry job with explicit tenant init; OAuth one-time nonce</li><li>Cancel/delete: remote Zoom/Google delete is best-effort so missing scopes cannot block local cancel; Zoom authorize requests write/read/delete scopes</li><li>Reminders: atomic <code>pending</code>→<code>sending</code> claim; external guest mail dedupe; <code>crm:send-due-notifications</code> delivers in-app + web push + email</li><li>Frontend: Meetings list/form/detail/integrations; provider options gated until connected; cancel confirm; retry sync; Calendar projections open in Meetings (read-only on Calendar)</li><li>Docs: user/developer/deployment/API; webhooks documented as stub until native provider verify</li><li>Pest: <code>tests/Feature/Tenant/Meeting/*</code></li></ul><hr><h2 id="tenant-branding-bootstrap-consistency-2026-07-21" tabindex="-1">Tenant branding bootstrap consistency (2026-07-21) <a class="header-anchor" href="#tenant-branding-bootstrap-consistency-2026-07-21" aria-label="Permalink to &quot;Tenant branding bootstrap consistency (2026-07-21)&quot;">​</a></h2><p>SPA branding no longer flickers through placeholder product names or stick on Central after soft login.</p><ul><li>Static shell / tab-title fallback standardized on <strong>EloSync</strong> (<code>index.html</code>, settings-store defaults, <code>VITE_APP_NAME</code>)</li><li>Sidebar and auth layout show empty brand text until public settings are loaded (no <code>DC SaaS</code> placeholder)</li><li>Settings re-bootstrap after auth settles so tenant <code>public/settings</code> can resolve via Bearer token and optional <code>X-Tenant-Domain</code></li><li>Central fallback on tenant routes only applies on first load — does not overwrite branding after login or settings save</li><li>Unit coverage: <code>src/store/settings-store.test.ts</code></li><li>Docs: <a href="/developer-guide/tenant-settings">tenant-settings developer</a>, <a href="/user-guide/tenant-settings-overview">tenant-settings overview</a></li></ul><hr><h2 id="daily-task-digest-emails-2026-07-21" tabindex="-1">Daily task digest emails (2026-07-21) <a class="header-anchor" href="#daily-task-digest-emails-2026-07-21" aria-label="Permalink to &quot;Daily task digest emails (2026-07-21)&quot;">​</a></h2><p>Due/overdue task alerts no longer email once per task.</p><ul><li>In-app: one <code>task.due_today</code> / <code>task.overdue</code> database notification per task (unchanged click-through to <code>/tasks?task={id}</code>)</li><li>Email: one consolidated daily digest per assignee with task links and a View my tasks CTA</li><li>Workspace setting <strong>Daily task reminder time</strong> (<code>task_reminder_time</code>, default <code>09:00</code>) in tenant timezone</li><li>Durable delivery ledger <code>task_digest_deliveries</code> (queued/sent/failed + retry) so cache flush cannot duplicate and queue failures can retry</li><li>Scheduler: <code>crm:send-due-notifications</code> every 5 minutes with <code>onOneServer</code> (lead follow-up due emails unchanged)</li></ul><hr><h2 id="calendar-module-v1-2026-07-21" tabindex="-1">Calendar module v1 (2026-07-21) <a class="header-anchor" href="#calendar-module-v1-2026-07-21" aria-label="Permalink to &quot;Calendar module v1 (2026-07-21)&quot;">​</a></h2><p>Personal Calendar marketplace module (CRM, default-included).</p><ul><li>Backend: <code>calendar_events</code>, permissions (<code>view</code>/<code>create</code>/<code>update</code>/<code>delete</code>/<code>view_all</code>), tenant API, migrate-only catalog registration</li><li>Frontend: <strong>Week</strong> (default) + <strong>Day</strong> time grids with drag-and-drop reschedule, Month + Agenda, create/edit/cancel/delete, upcoming dashboard widget</li><li>Workspace timezone-aware display/edit; overlapping events laid out side-by-side on Week/Day</li><li>Visibility: staff sees own events; Owner/Admin/Manager with <code>view_all</code> see all — <strong>no calendar assignment</strong></li><li>Platform audit via <code>CalendarEventSubscriber</code> (create/update/cancel/delete), mirroring Leads/Tasks</li><li>Docs: user/developer/deployment/API; Pest incl. deploy-migration + audit coverage; Playwright <code>test:e2e:calendar</code></li><li>Meetings / Zoom / Google Meet later projected onto Calendar (shipped 2026-07-22)</li></ul><hr><h2 id="whatsapp-cloud-integration-roadmap-2026-07-20" tabindex="-1">WhatsApp Cloud Integration roadmap (2026-07-20) <a class="header-anchor" href="#whatsapp-cloud-integration-roadmap-2026-07-20" aria-label="Permalink to &quot;WhatsApp Cloud Integration roadmap (2026-07-20)&quot;">​</a></h2><p>Documentation-only: official architectural blueprint for a future WhatsApp Cloud API communication platform.</p><ul><li>Added <a href="/developer-guide/whatsapp-cloud-integration">WhatsApp Cloud Integration</a> under <strong>Future Integrations</strong> (current <code>wa.me</code> state vs Cloud API vision, messaging driver architecture, OAuth, multi-tenant WABA/phone ownership, conversations, templates, security, automation, Meta Lead Ads complementarity)</li><li>Cross-linked with <a href="/developer-guide/lead-source-driver-architecture">Lead Source Driver Architecture</a> and <a href="/developer-guide/meta-lead-ads-integration">Meta Lead Ads Integration</a></li><li>Sidebar / Developer Guide index / Product Roadmap updated</li><li>No backend or frontend application code changes</li></ul><hr><h2 id="lead-source-driver-architecture-2026-07-20" tabindex="-1">Lead Source Driver Architecture (2026-07-20) <a class="header-anchor" href="#lead-source-driver-architecture-2026-07-20" aria-label="Permalink to &quot;Lead Source Driver Architecture (2026-07-20)&quot;">​</a></h2><p>Documentation-only: architectural decision for all future lead ingestion in EloSync.</p><ul><li>Added <a href="/developer-guide/lead-source-driver-architecture">Lead Source Driver Architecture</a> (<code>LeadSourceDriverInterface</code> responsibilities, shared pipeline, <code>NormalizedLeadData</code>, driver vs Lead ownership, driver catalog, Open/Closed extensibility)</li><li>Updated <a href="/developer-guide/meta-lead-ads-integration">Meta Lead Ads Integration</a>: <code>MetaLeadAdsDriver</code> is the first production implementation of the architecture</li><li>Sidebar / Developer Guide index: Future Integrations cross-links both pages</li><li>Product Roadmap: Phase 1 Planned entry for Lead Source Driver Architecture</li><li>No backend or frontend application code changes</li></ul><hr><h2 id="meta-lead-ads-integration-roadmap-2026-07-20" tabindex="-1">Meta Lead Ads Integration roadmap (2026-07-20) <a class="header-anchor" href="#meta-lead-ads-integration-roadmap-2026-07-20" aria-label="Permalink to &quot;Meta Lead Ads Integration roadmap (2026-07-20)&quot;">​</a></h2><p>Documentation-only: official implementation blueprint for a future Meta Lead Ads → Leads integration.</p><ul><li>Added <a href="/developer-guide/meta-lead-ads-integration">Meta Lead Ads Integration</a> under <strong>Future Integrations</strong> (architecture, OAuth, multi-tenant Page ID resolution, field mapping, <code>LeadDuplicateService</code> + <code>LeadService</code> gates, security, Meta permissions, error handling, future enhancements)</li><li>Sidebar: Developer Guide → Future Integrations → Meta Lead Ads</li><li>Product Roadmap: Phase 1 Planned entry linking to the blueprint</li><li>No backend or frontend application code changes</li></ul><hr><h2 id="fix-persist-open-click-webhook-event-settings-2026-07-19" tabindex="-1">Fix: persist Open/Click webhook event settings (2026-07-19) <a class="header-anchor" href="#fix-persist-open-click-webhook-event-settings-2026-07-19" aria-label="Permalink to &quot;Fix: persist Open/Click webhook event settings (2026-07-19)&quot;">​</a></h2><ul><li>Fixed settings save treating <code>mail_webhook_events</code> list arrays as <code>{value:…}</code> wrappers (Open/Click were stored as null and UI checkboxes cleared after save)</li><li>Default webhook events now include <code>opened</code> and <code>clicked</code></li><li>Open webhooks update email log status once events are persisted</li></ul><h2 id="email-open-click-tracking-on-email-logs-2026-07-19" tabindex="-1">Email open/click tracking on email logs (2026-07-19) <a class="header-anchor" href="#email-open-click-tracking-on-email-logs-2026-07-19" aria-label="Permalink to &quot;Email open/click tracking on email logs (2026-07-19)&quot;">​</a></h2><ul><li>Open and Click webhooks now set email log status to <code>opened</code> / <code>clicked</code> (counts also stored in <code>meta.opens</code> / <code>meta.clicks</code>)</li><li>Email Logs UI shows Opened/Clicked statuses plus open/click counts in the detail panel</li><li>Mail settings no longer wipe Open/Click checkboxes after save/reload</li><li>Postmark setup instructions note that Open tracking and Link tracking must be enabled in Postmark (settings save does not sync the provider UI)</li></ul><h2 id="email-webhooks-body-logging-and-resend-2026-07-19" tabindex="-1">Email webhooks, body logging, and resend (2026-07-19) <a class="header-anchor" href="#email-webhooks-body-logging-and-resend-2026-07-19" aria-label="Permalink to &quot;Email webhooks, body logging, and resend (2026-07-19)&quot;">​</a></h2><ul><li>Provider delivery webhooks for Postmark / Mailgun: <code>POST /webhooks/email/{provider}</code> (Central) and <code>…/{provider}/{tenant}</code> (Tenant custom mail)</li><li>Configurable event multiselect (<code>mail_webhook_events</code>) + signing secret in Central/Tenant Mail settings; <code>meta.mail_webhook</code> on settings GET</li><li>Full message body capture (<code>body_html</code> / <code>body_text</code>) on email logs by default (<code>EMAIL_LOGS_STORE_BODY=true</code>) for audit/proof</li><li>One-click resend from email log detail (<code>email-logs.resend</code>, <code>POST …/email-logs/{uuid}/resend</code>)</li><li>Docs: <a href="/developer-guide/email-webhooks">Email webhooks</a>, updated <a href="/developer-guide/multi-provider-email">Multi-Provider Email</a></li></ul><h2 id="v1-1-0-—-platform-stabilization-prepared-2026-07-19" tabindex="-1">v1.1.0 — Platform Stabilization (prepared 2026-07-19) <a class="header-anchor" href="#v1-1-0-—-platform-stabilization-prepared-2026-07-19" aria-label="Permalink to &quot;v1.1.0 — Platform Stabilization (prepared 2026-07-19)&quot;">​</a></h2><p>First official coordinated platform tag. Official record: <a href="/changelog/v1.1.0">v1.1.0</a>.</p><p>Git tag: <strong><code>v1.1.0</code></strong> (clean SemVer — <strong>create only after CI is green on all three repos</strong>). No <code>-platform</code> suffix.</p><p>Highlights:</p><ul><li>Multi-provider email (SMTP / Postmark / Mailgun) + logs + queue isolation</li><li>Production hardening (migrate-only modules/RBAC, auth≠RBAC, go-live runbooks)</li><li>Notifications + Communication Templates on the frozen foundation</li><li>Larastan level 5 at zero errors; standardized PR Quality Gates (Backend / Frontend / Docs)</li><li><a href="/developer-guide/documentation-governance">Documentation Governance</a> — same-PR rule for code + tests + docs</li><li><a href="/deployment/release-process">Release Process</a> with branch-protection checklist for admins</li></ul><p>Package versions: Frontend &amp; Docs <code>1.1.0</code>; Backend tag-only. Legacy docs alias: <a href="/changelog/v1.1.0-platform">v1.1.0-platform</a>.</p><hr><h2 id="multi-provider-email-delivery-—-production-hardening-2026-07-19" tabindex="-1">Multi-Provider Email Delivery — production hardening (2026-07-19) <a class="header-anchor" href="#multi-provider-email-delivery-—-production-hardening-2026-07-19" aria-label="Permalink to &quot;Multi-Provider Email Delivery — production hardening (2026-07-19)&quot;">​</a></h2><p>Production-readiness fixes on top of the multi-provider email implementation:</p><ul><li>Runtime isolation: <code>EmailManager</code> clears prior SMTP/Postmark/Mailgun secrets on every apply; queue middleware clears secrets after each mail job</li><li>Central HTTP middleware <code>central.mail</code> re-applies Central mail on every Central request</li><li>Tenant system-mode test mail inherits Central; test-mail restores prior runtime config in <code>finally</code></li><li>Provider-conditional save validation; additive <code>email-logs.*</code> permission migration; unsupported webhook capabilities no longer advertised</li><li>Upgrade/runbook notes for migrate, <code>email:migrate-tenant-mail-modes</code>, composer packages, <code>queue:restart</code></li></ul><h2 id="multi-provider-email-delivery-implementation-2026-07-19" tabindex="-1">Multi-Provider Email Delivery implementation (2026-07-19) <a class="header-anchor" href="#multi-provider-email-delivery-implementation-2026-07-19" aria-label="Permalink to &quot;Multi-Provider Email Delivery implementation (2026-07-19)&quot;">​</a></h2><p>Platform infrastructure: provider-agnostic email delivery for Central and Tenant.</p><ul><li><code>EmailManager</code> + driver registry (SMTP, Postmark, Mailgun, log/array/sendmail) with Laravel mailer overlay + <code>Mail::forgetMailers()</code></li><li>Central/Tenant settings: <code>mail_provider</code>, encrypted API secrets, <code>mail_mode</code> (system|custom), reply-to, timeout</li><li>Queue middleware <code>ApplyEmailRuntimeConfig</code> re-applies tenant/central mail config on the <code>emails</code> worker</li><li>Structured test-mail responses (draft settings supported); email logs API + UI + weekly prune</li><li>Artisan <code>email:migrate-tenant-mail-modes</code> backfills tenant modes from legacy <code>mail_host</code></li><li>Future stubs: webhook capability interface, resend/analytics services, failover config keys</li><li>Developer guide: <a href="/developer-guide/multi-provider-email">Multi-Provider Email</a></li></ul><hr><h2 id="multi-provider-email-delivery-roadmap-2026-07-19" tabindex="-1">Multi-Provider Email Delivery roadmap (2026-07-19) <a class="header-anchor" href="#multi-provider-email-delivery-roadmap-2026-07-19" aria-label="Permalink to &quot;Multi-Provider Email Delivery roadmap (2026-07-19)&quot;">​</a></h2><p>Documentation-only: product roadmap for provider-agnostic email delivery (Central + Tenant).</p><ul><li>Updated <a href="/getting-started/product-roadmap">Product Roadmap</a>: <strong>Multi-Provider Email Delivery</strong> section (<code>EmailManager</code> / driver abstraction, Central + tenant providers, logs, queue/retry, optional provider capabilities, analytics, test email, enterprise routing)</li><li>Distinguishes <strong>Planned</strong>, <strong>Future</strong>, and <strong>Enterprise</strong> capabilities; SMTP remains one interchangeable driver</li><li>No application code, schema, API, or settings implementation changes</li></ul><hr><h2 id="clean-url-static-fallbacks-2026-07-18" tabindex="-1">Clean URL static fallbacks (2026-07-18) <a class="header-anchor" href="#clean-url-static-fallbacks-2026-07-18" aria-label="Permalink to &quot;Clean URL static fallbacks (2026-07-18)&quot;">​</a></h2><p>Deep links work on default Forge/Nginx without per-server <code>$uri.html</code> rewrites.</p><ul><li>Post-build script <code>scripts/ensure-clean-url-indexes.mjs</code> copies each VitePress page to a directory <code>index.html</code> so <code>/path/to/page</code> resolves via standard <code>try_files $uri $uri/</code></li><li>Wired into <code>npm run docs:build</code> (CI publish included)</li></ul><hr><h2 id="modular-architecture-convention-2026-07-18" tabindex="-1">Modular architecture convention (2026-07-18) <a class="header-anchor" href="#modular-architecture-convention-2026-07-18" aria-label="Permalink to &quot;Modular architecture convention (2026-07-18)&quot;">​</a></h2><p>Documentation-only pass establishing the long-term modular architecture standard for all future modules.</p><ul><li>Added <a href="/architecture/">Architecture</a> section: <a href="/architecture/module-architecture">Module Architecture</a>, <a href="/architecture/module-dependencies">Module Dependencies</a>, <a href="/architecture/module-licensing">Module Licensing</a></li><li>Updated <a href="/getting-started/product-roadmap">Product Roadmap</a>: Calendar, Meetings (scheduling, Zoom, Google Meet, email reminders), AI Integration (Planning)</li><li>Documented development convention: self-contained modules, declared dependencies, independent licensing compatibility</li><li>Updated site footer copyright to © 2026 EloSync. All rights reserved.</li><li>No application code, billing, marketplace, schema, or API changes</li></ul><hr><h2 id="documentation-sync-—-migrate-only-modules-auth-rbac-separation-2026-07-18" tabindex="-1">Documentation sync — migrate-only modules &amp; auth/RBAC separation (2026-07-18) <a class="header-anchor" href="#documentation-sync-—-migrate-only-modules-auth-rbac-separation-2026-07-18" aria-label="Permalink to &quot;Documentation sync — migrate-only modules &amp; auth/RBAC separation (2026-07-18)&quot;">​</a></h2><p>Docs pass aligning architecture, deployment, RBAC, provisioning, entitlements, database, API, and Communication Templates guides with the final production architecture.</p><ul><li>Production deploy is migration-driven (<code>migrate --force</code> + <code>optimize</code>); no catalog/permission reseeding</li><li>Authentication has no authorization side effects; workspace RBAC is provisioned explicitly</li><li>Communication Templates documented as a reusable platform module (placeholders, render/preview, WhatsApp)</li><li>Future modules follow the data-migration registration pattern</li></ul><hr><h2 id="authentication-authorization-separation-2026-07-18" tabindex="-1">Authentication / authorization separation (2026-07-18) <a class="header-anchor" href="#authentication-authorization-separation-2026-07-18" aria-label="Permalink to &quot;Authentication / authorization separation (2026-07-18)&quot;">​</a></h2><p>Keep login and authenticated requests free of RBAC side effects.</p><ul><li><code>TenantAuthorizationProvisioningService</code> provisions workspace roles during workspace create</li><li><code>TenantAuthBootstrapService</code> only creates owners and issues tokens</li><li>Dashboard, role listing, and user listing no longer repair permissions</li><li>Legacy shared-role isolation remains an explicit <code>tenants:isolate-roles</code> maintenance command</li><li>Existing workspaces still receive new permissions through additive data migrations</li></ul><hr><h2 id="communication-templates-production-deploy-hardening-2026-07-17" tabindex="-1">Communication Templates production deploy hardening (2026-07-17) <a class="header-anchor" href="#communication-templates-production-deploy-hardening-2026-07-17" aria-label="Permalink to &quot;Communication Templates production deploy hardening (2026-07-17)&quot;">​</a></h2><p>Eliminate production <code>db:seed</code> for Communication Templates.</p><ul><li>Data migrations register the catalog module and grant permissions additively during <code>php artisan migrate</code></li><li><code>DefaultModuleRegistrar</code> installs the module only for workspaces missing a subscription row (never reactivates cancelled/suspended)</li><li><code>TenantPermissionSynchronizer</code> creates missing permission vocabulary and grants only new permissions without resetting customized roles</li><li>Authentication and dashboard requests no longer mutate roles or permissions</li><li><code>TenantAuthorizationProvisioningService</code> creates default RBAC during workspace provisioning; deploy migrations add future permissions</li><li>CatalogSeeder remains insert-only for fresh/local environments</li></ul><hr><h2 id="communication-templates-module-mvp-2026-07-17" tabindex="-1">Communication Templates module (MVP) (2026-07-17) <a class="header-anchor" href="#communication-templates-module-mvp-2026-07-17" aria-label="Permalink to &quot;Communication Templates module (MVP) (2026-07-17)&quot;">​</a></h2><p>Catalog module for reusable plain-text templates with a placeholder registry and WhatsApp Web (<code>wa.me</code>) from Leads.</p><ul><li>Backend: <code>communication_templates</code> table, CRUD + preview/render APIs, Lead/shared placeholder providers, UUID route binding, permissions (<code>view|create|update|delete|use</code>), platform audit</li><li>Frontend: Templates admin page with chip inserter, Lead detail WhatsApp picker, module-gated nav</li><li>Docs: developer / user / API / deployment guides; E2E <code>test:e2e:communication-templates</code></li><li>Default-included with Leads and Tasks for new workspaces</li></ul><hr><h2 id="in-app-notifications-production-hardening-2026-07-16" tabindex="-1">In-app notifications production hardening (2026-07-16) <a class="header-anchor" href="#in-app-notifications-production-hardening-2026-07-16" aria-label="Permalink to &quot;In-app notifications production hardening (2026-07-16)&quot;">​</a></h2><p>Release hardening for the frozen notification stack (no architecture changes).</p><ul><li>Backend: after-commit queueing, broadcast-after-persist guard, reassignment dedupe keys, Reverb origin pinning</li><li>Frontend: Forge <code>window.env</code> Reverb config, Echo reconnect + poll-only-when-disconnected, dead-code cleanup</li><li>Docs: <a href="/deployment/notifications">Notification System deployment runbook</a>, contract/API/runbook links, production checklist + troubleshooting</li></ul><hr><h2 id="in-app-notifications-production-stack-2026-07-16" tabindex="-1">In-app notifications production stack (2026-07-16) <a class="header-anchor" href="#in-app-notifications-production-stack-2026-07-16" aria-label="Permalink to &quot;In-app notifications production stack (2026-07-16)&quot;">​</a></h2><p>Phased delivery of the frozen notification architecture (payload v1 → digests → Reverb/Echo → registry → browser → prune).</p><ul><li>Backend: schema_version envelope, route descriptors, NotificationBatch + lead digests, Reverb private channels, <code>notifications:prune</code>, unread indexes</li><li>Frontend: Laravel Echo, modular <code>src/notifications</code> registry, optimistic bell UX, Web Notification API manager</li><li>Docs: <a href="/developer-guide/notification-architecture-contract">notification-architecture-contract.md</a>, API + roadmap updated</li><li>Lead assigned: database + broadcast only (mail deferred); bulk/import → one digest per assignee</li></ul><hr><h2 id="notification-architecture-contract-frozen-2026-07-16" tabindex="-1">Notification architecture contract frozen (2026-07-16) <a class="header-anchor" href="#notification-architecture-contract-frozen-2026-07-16" aria-label="Permalink to &quot;Notification architecture contract frozen (2026-07-16)&quot;">​</a></h2><p>In-app notification contracts are frozen before phased implementation (payload v1, route descriptors, NotificationBatch, Reverb/Echo, modular registry).</p><ul><li>Docs: <a href="/developer-guide/notification-architecture-contract">notification-architecture-contract.md</a></li><li>Linked from module development standard and tenant notifications API</li><li>No application code in this change; implementation follows Phases 1–8</li></ul><hr><h2 id="branding-disk-split-local-logos-favicons-2026-07-16" tabindex="-1">Branding disk split (local logos/favicons) (2026-07-16) <a class="header-anchor" href="#branding-disk-split-local-logos-favicons-2026-07-16" aria-label="Permalink to &quot;Branding disk split (local logos/favicons) (2026-07-16)&quot;">​</a></h2><p>Logo and favicon can use a dedicated disk while other uploads stay on S3.</p><ul><li>Env: <code>FILESYSTEM_BRANDING_DISK</code> (defaults to uploads / <code>FILESYSTEM_DISK</code>)</li><li>Production split: <code>FILESYSTEM_DISK=s3</code> + <code>FILESYSTEM_BRANDING_DISK=public</code> + <code>php artisan storage:link</code></li><li><code>FileUploadService</code> branding helpers; central/tenant branding + workspace logos use the branding disk</li><li>Docs: <code>developer-guide/object-storage.md</code>; settings production checklists updated</li></ul><hr><h2 id="lead-import-reusable-import-framework-2026-07-16" tabindex="-1">Lead Import (reusable Import framework) (2026-07-16) <a class="header-anchor" href="#lead-import-reusable-import-framework-2026-07-16" aria-label="Permalink to &quot;Lead Import (reusable Import framework) (2026-07-16)&quot;">​</a></h2><p>Bulk CSV/XLSX lead import with a reusable framework for future modules.</p><ul><li>Permission: <code>leads.import</code> (admin/manager; mirrors export)</li><li>Package: Maatwebsite Laravel Excel; queue: <code>ProcessLeadImportJob</code> on <code>imports</code></li><li>API: template, upload, mapping, options, preview, run, history, original/failed/error downloads</li><li>SPA: 5-step wizard + import history beside Export; polls queued progress</li><li>Duplicate modes: skip / update (needs <code>leads.update</code>) / keep; unique fields email and/or phone</li><li>Single migration <code>lead_imports</code>; row failures as downloadable CSVs (no per-row tables)</li><li>Writes via <code>LeadService::create()</code> / <code>update()</code>; audit <code>lead_import_completed</code> / <code>lead_import_failed</code></li><li>Tests: <code>LeadImportTest</code>; Playwright <code>leads.import.spec.ts</code></li><li>Docs: user/developer/API/deployment guides updated (import no longer deferred)</li></ul><hr><h2 id="tenant-manual-member-email-verification-2026-07-16" tabindex="-1">Tenant manual member email verification (2026-07-16) <a class="header-anchor" href="#tenant-manual-member-email-verification-2026-07-16" aria-label="Permalink to &quot;Tenant manual member email verification (2026-07-16)&quot;">​</a></h2><p>Workspace owners and admins can help members who never receive the verification email.</p><ul><li>Permission: <code>users.verify</code> (owner + admin role map)</li><li>API: <code>POST /api/tenant/v1/users/{user}/verify-email</code>, <code>POST /api/tenant/v1/users/{user}/resend-verification</code></li><li>SPA Users row menu: <strong>Resend verification</strong> / <strong>Mark as verified</strong></li><li>Audit: <code>tenant_user_email_verified</code>, <code>tenant_user_verification_resent</code></li><li>Tests: <code>TenantUserVerifyEmailTest</code>; Playwright tenant RBAC covers mark-as-verified</li></ul><hr><h2 id="dedicated-emails-queue-2026-07-15" tabindex="-1">Dedicated emails queue (2026-07-15) <a class="header-anchor" href="#dedicated-emails-queue-2026-07-15" aria-label="Permalink to &quot;Dedicated emails queue (2026-07-15)&quot;">​</a></h2><p>All <code>ShouldQueue</code> notifications dispatch to the named <code>emails</code> queue via <code>QueuesOnEmails</code>.</p><ul><li>Worker: <code>php artisan queue:work --queue=emails --sleep=1 --tries=3 --max-time=3600</code></li><li>Optional standby: <code>--queue=default</code> for future non-mail jobs</li><li>Docs: production runbook, module-development-developer, backend README Queue Setup</li></ul><hr><h2 id="spa-runtime-config-multi-client-forge-2026-07-15" tabindex="-1">SPA runtime config (multi-client / Forge) (2026-07-15) <a class="header-anchor" href="#spa-runtime-config-multi-client-forge-2026-07-15" aria-label="Permalink to &quot;SPA runtime config (multi-client / Forge) (2026-07-15)&quot;">​</a></h2><p>Frontend API origin is runtime via Forge-generated <code>/config.js</code> (<code>window.env</code>), not baked into CI.</p><ul><li>Deploy script sources site <code>.env</code> and writes <code>VITE_API_URL</code> / <code>VITE_APP_NAME</code> / <code>VITE_API_MODE</code></li><li>Same <code>build-artifacts</code> artifact for every client; each Forge site owns its <code>.env</code></li><li>No committed <code>config.js</code> / <code>config.example.js</code> in the SPA repo</li><li>Docs: <code>architecture/frontend-build-artifacts.md</code>, production runbook</li></ul><hr><h2 id="frontend-production-ci-cd-build-artifacts-2026-07-15" tabindex="-1">Frontend production CI/CD (build-artifacts) (2026-07-15) <a class="header-anchor" href="#frontend-production-ci-cd-build-artifacts-2026-07-15" aria-label="Permalink to &quot;Frontend production CI/CD (build-artifacts) (2026-07-15)&quot;">​</a></h2><p>Automated SPA production builds on merge to <code>main</code> without committing <code>dist/</code> to source.</p><ul><li>GitHub Actions workflow <code>frontend-build.yml</code>: lint, typecheck, Vite production build, validation, secret scan</li><li>Uploads GitHub Actions artifact <code>frontend-build</code> (30-day retention)</li><li>Publishes deployment-ready assets to the <code>build-artifacts</code> branch with <code>build-info.json</code> provenance</li><li>Docs: <code>architecture/frontend-build-artifacts.md</code>; production runbook SPA section updated</li></ul><hr><h2 id="object-storage-migration-wasabi-s3-2026-07-15" tabindex="-1">Object storage migration (Wasabi / S3) (2026-07-15) <a class="header-anchor" href="#object-storage-migration-wasabi-s3-2026-07-15" aria-label="Permalink to &quot;Object storage migration (Wasabi / S3) (2026-07-15)&quot;">​</a></h2><p>All user uploads go through Laravel Storage via <code>FileUploadService</code>. Production uses <code>FILESYSTEM_DISK=s3</code> (Wasabi or any S3-compatible provider); local uses <code>FILESYSTEM_DISK=public</code>.</p><ul><li><code>league/flysystem-aws-s3-v3</code> + full <code>AWS_*</code> env (<code>ENDPOINT</code> / <code>URL</code> for Wasabi)</li><li>Central/tenant branding and admin tenant logos use <code>FileUploadService</code> (unique filenames, relative keys, disk-agnostic URLs)</li><li>Tenancy filesystem bootstrapper no longer remaps the shared <code>public</code>/uploads disk (prefix isolation via <code>tenants/{uuid}/…</code>)</li><li>Artisan <code>storage:migrate-to-s3</code> copies existing local objects idempotently</li><li>Docs: <code>architecture/object-storage.md</code>; settings production guides updated</li></ul><hr><h2 id="go-live-hardening-2026-07-15" tabindex="-1">Go-live hardening (2026-07-15) <a class="header-anchor" href="#go-live-hardening-2026-07-15" aria-label="Permalink to &quot;Go-live hardening (2026-07-15)&quot;">​</a></h2><p>Production readiness audit for Central + Tenant with Leads &amp; Tasks. Billing and security fixes only — no architecture redesign.</p><p><strong>Critical / High</strong></p><ul><li>Module cancel now calls Stripe/Creem <code>cancelSubscription</code> before local entitlement revoke (prevents silent continued charging)</li><li>Failed webhook logs are reclaimed on provider retry (no permanent swallow after a transient 500)</li><li>Recurring <code>invoice.payment_succeeded</code> creates a renewal invoice/payment when the provider transaction id is new</li><li>Cashier <code>/stripe/webhook</code> handles <code>invoice.payment_failed</code></li><li>Email verification asserts the user belongs to the current tenant</li><li>Boot refuses <code>APP_DEBUG=true</code> in production; HTTPS scheme forced in production; <code>SecureHeaders</code> + <code>TrustProxies</code></li><li>Lead CSV export escapes formula injection (<code>=+-@</code>)</li><li>Checkout merges admin <code>gateway_metadata</code> into Stripe/Creem session metadata</li><li>SPA: Leads/Tasks assignee fetches gated on <code>users.list</code> (no spurious 403 toast for staff); assignee fields PermissionGated in create/edit dialogs</li></ul><p><strong>Ops / docs</strong></p><ul><li>CRM due-notification command applies tenant SMTP runtime config</li><li>Production runbook: cache isolation wording, Creem webhook secret, frontend SPA deploy notes</li><li>Tests: cancel-at-gateway, failed-webhook retry, renewal ledger; marketplace Stripe mocks allow <code>completedCheckoutEvent</code></li></ul><hr><h2 id="creem-payment-gateway-2026-07-14" tabindex="-1">Creem payment gateway (2026-07-14) <a class="header-anchor" href="#creem-payment-gateway-2026-07-14" aria-label="Permalink to &quot;Creem payment gateway (2026-07-14)&quot;">​</a></h2><p>Add Creem as a second provider behind the existing <code>PaymentGatewayInterface</code> / <code>GatewayManager</code> stack. Stripe behavior is unchanged.</p><ul><li><code>CreemGateway</code> + HTTP <code>CreemClient</code>, webhook HMAC verification, provider-neutral <code>tenant_gateway_customers</code></li><li>Config: <code>config/creem.php</code> (<code>CREEM_*</code> env fallbacks); seed + admin enable/disable/default/config</li><li>Webhooks: <code>POST /webhooks/gateways/creem</code> (<code>creem-signature</code>) → Billing Engine module activation</li><li>Product mapping uses Creem <code>prod_…</code> ids; Central UI credential fields + Creem-specific mapping copy</li><li>Return-URL / “Complete subscription” sync via <code>confirm-checkout</code> so paid checkouts activate without a second session when webhooks are delayed</li><li>Docs: <code>billing/creem.md</code>; tests: <code>CreemGatewayTest</code>, <code>CreemWebhookTest</code>, <code>CreemCheckoutConfirmTest</code></li></ul><hr><h2 id="provider-agnostic-billing-2026-07-14" tabindex="-1">Provider-agnostic billing (2026-07-14) <a class="header-anchor" href="#provider-agnostic-billing-2026-07-14" aria-label="Permalink to &quot;Provider-agnostic billing (2026-07-14)&quot;">​</a></h2><p>Decouple Modules from Stripe. Stripe is one payment driver; catalog pricing stays on Modules.</p><ul><li>Added <code>payment_gateway_module_prices</code> (gateway × module × billing cycle → product/price references)</li><li>Migrated existing <code>modules.stripe_*</code> IDs into the mapping table, then dropped those columns</li><li>Added <code>modules.currency</code> and <code>workspace_module_subscriptions.payment_gateway_id</code></li><li><code>BillingEngine</code> / <code>StripeGateway</code> resolve checkout prices from mappings; consolidated billing skips recurring-gateway subscriptions</li><li>Central API + UI: Module form is catalog-only; <strong>Payment Gateways → Product Mapping</strong> manages provider refs</li><li>Docs: <code>billing/*</code>, <code>architecture/database.md</code>, <code>api/central-v1.md</code>, <code>admin-ui.md</code></li></ul><hr><h2 id="rc1-—-production-readiness-2026-07-14" tabindex="-1">RC1 — Production Readiness (2026-07-14) <a class="header-anchor" href="#rc1-—-production-readiness-2026-07-14" aria-label="Permalink to &quot;RC1 — Production Readiness (2026-07-14)&quot;">​</a></h2><p>Release Candidate hardening for paying-customer launch. No new business modules. Official notes: <a href="/deployment/rc1-production-readiness">releases/rc1-production-readiness.md</a>. Recommended tag: <code>v1.2.0-rc.1</code>.</p><p><strong>Critical / High</strong></p><ul><li>Revoke Sanctum tokens on user suspend; reject suspended sessions via <code>not.suspended</code></li><li>Webhook unique idempotency + safe payload summaries; Cashier + gateway ingress share claim store</li><li>Registration defaults off; tenant password-reset URLs include <code>workspace</code></li><li>Impersonation limited to workspace owner role</li><li>SPA query-cache cleared on session switches; email-verify URL allowlist; verified gate treats missing timestamp as unverified</li><li>Board APIs cap per-column payload size; drawer query-param history for leads/tasks</li></ul><p><strong>Ops / a11y</strong></p><ul><li>Health check probes Redis when used; skip-to-content; billing ErrorState; remember-me default off</li></ul><hr><h2 id="production-hardening-pass-2026-07-13" tabindex="-1">Production Hardening Pass (2026-07-13) <a class="header-anchor" href="#production-hardening-pass-2026-07-13" aria-label="Permalink to &quot;Production Hardening Pass (2026-07-13)&quot;">​</a></h2><p>Security, ops, and SPA hardening for launch readiness. Platform freeze unchanged (no Features/Plans/Limits reintroduced).</p><p><strong>Critical / High security</strong></p><ul><li>Block assignment of protected <code>superadmin</code> (workspace owner) roles via tenant user APIs</li><li>Central role permission sync filtered to <code>central-api</code> guard only</li><li>Gateway webhooks verify signatures before persisting payloads; store safe summaries only</li><li>Branding uploads reject SVG (stored XSS)</li><li>Narrowed <code>User</code> / <code>CentralUser</code> <code>$fillable</code> privileged fields</li><li>CORS origins pinned via <code>FRONTEND_URL</code> / <code>CORS_ALLOWED_ORIGINS</code> (no <code>*</code>)</li><li>Payment API redacts raw <code>gateway_response</code> / <code>webhook_payload</code></li><li>Webhook + API rate limiting; schedule <code>withoutOverlapping</code></li><li>SPA: safe post-login redirects, route <code>RequireAccess</code> gates, ErrorBoundary, query cache clear on logout</li></ul><p><strong>Ops</strong></p><ul><li>Notifications implement <code>ShouldQueue</code></li><li>Health <code>/up</code> verifies database connectivity</li><li>Production runbook: <a href="/deployment/platform-production-runbook">architecture/platform-production-runbook.md</a></li><li><code>.env.example</code> production guidance</li></ul><hr><h2 id="sprint-2-—-crm-ux-2026-07-13" tabindex="-1">Sprint 2 — CRM UX (2026-07-13) <a class="header-anchor" href="#sprint-2-—-crm-ux-2026-07-13" aria-label="Permalink to &quot;Sprint 2 — CRM UX (2026-07-13)&quot;">​</a></h2><p>Leads/Tasks UX + notifications + tenant dashboard widgets. Platform freeze unchanged.</p><p><strong>Leads</strong></p><ul><li><code>lead_value</code> (renamed from <code>estimated_value</code>); independent status <code>active|waiting|on_hold|closed|archived</code>; priority; assignment history</li><li>Kanban (default) + table; DnD opens drawer, save commits stage; KPIs / board / stats APIs</li><li>Follow-up update/reschedule; export CSV/XLSX (filtered); convert stub (<code>converted_at</code>, activity, status closed — Contacts deferred)</li><li>Permissions: <code>view|create|update|delete|assign|export|convert</code> (no import); assignee scoping without <code>leads.assign</code></li></ul><p><strong>Tasks</strong></p><ul><li><code>waiting</code> status; UI labels <code>open</code> as To Do; board (default) + list; KPIs / board / stats APIs</li><li>Comments + History tabs; <code>tasks.change_due_date</code> required to change <code>due_at</code> after create</li><li>Assignee scoping via <code>tasks.assign</code></li></ul><p><strong>Notifications &amp; dashboard</strong></p><ul><li>Historical initial release: database + mail channels; APIs list / unread-count / mark read / mark all; realtime was added in the later notification architecture rollout above</li><li>Hourly <code>crm:send-due-notifications</code> for due/overdue follow-ups and tasks</li><li><code>GET /dashboard</code> widget registry gated by module + permission + assignee scope; no calendar widget until Calendar module</li></ul><p><strong>Docs</strong></p><ul><li>Updated Leads/Tasks guides, database, module-development patterns, tenant UI</li><li>API: <a href="/api/tenant-v1-leads">tenant-v1-leads.md</a>, <a href="/api/tenant-v1-tasks">tenant-v1-tasks.md</a>, <a href="/api/tenant-v1-notifications">tenant-v1-notifications.md</a>, <a href="/api/tenant-v1-dashboard">tenant-v1-dashboard.md</a></li></ul><hr><h2 id="v1-1-0-platform-—-production-ready-2026-07-13" tabindex="-1">v1.1.0-platform — Production Ready (2026-07-13) <a class="header-anchor" href="#v1-1-0-platform-—-production-ready-2026-07-13" aria-label="Permalink to &quot;v1.1.0-platform — Production Ready (2026-07-13)&quot;">​</a></h2><p>Platform foundation declared <strong>Production Ready</strong> and <strong>frozen</strong>. No new business modules in this release — hardening only.</p><p>Logical freeze notes (never tagged in git). Official first tag: <a href="/changelog/v1.1.0"><code>v1.1.0</code></a>.<br> Alias: <a href="/changelog/v1.1.0-platform">v1.1.0-platform</a></p><p><strong>Verification</strong></p><ul><li>Pest: <strong>230/230</strong> pass</li><li>Playwright: <strong>69/69</strong> pass (<code>--workers=1</code>, all projects: setup, auth, tenant, chromium)</li><li>Manual Cursor browser happy path: Central + Tenant</li></ul><p><strong>Authentication &amp; SPA</strong></p><ul><li>Auth matrix expanded: Pest + Playwright coverage for lockout messages (includes minutes remaining), remember-me, email verification, registration validation, tenant login, and wrong-workspace rejection</li><li><code>VerifyEmailGate</code> <strong>Sign out</strong> navigates to the context login page after logout</li></ul><p><strong>Billing &amp; gateways</strong></p><ul><li><code>BillingEngine::resolveTenant</code> falls back to <code>payment_id</code> in event metadata when customer/subscription maps are absent</li><li>Gateway webhook failure/cancel Pest coverage</li></ul><p><strong>Validation &amp; settings</strong></p><ul><li>Central user and module validation Pest; Lead validation; module deactivate gate after uninstall</li><li>System settings runtime asserts: Sanctum expiration, locale, Cashier currency, date/time formats</li></ul><p><strong>E2E stability</strong></p><ul><li>Focused auth/tenant/central specs; page-object delete/clone assertions; local Playwright <code>workers: 1</code></li></ul><hr><h2 id="product-roadmap-documented-2026-07-12" tabindex="-1">Product roadmap documented (2026-07-12) <a class="header-anchor" href="#product-roadmap-documented-2026-07-12" aria-label="Permalink to &quot;Product roadmap documented (2026-07-12)&quot;">​</a></h2><ul><li>Added <a href="/getting-started/product-roadmap">product-roadmap.md</a>: CRM → Sales → Billing → Purchasing → Inventory → Finance → HR → future expansion</li><li>Linked from README and platform-freeze docs</li><li>Phase 1 CRM: Leads + Tasks complete; Contacts / Companies / Calendar / Activities next</li></ul><hr><h2 id="tasks-module-2026-07-12" tabindex="-1">Tasks module (2026-07-12) <a class="header-anchor" href="#tasks-module-2026-07-12" aria-label="Permalink to &quot;Tasks module (2026-07-12)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>Second product module; mirrors Leads (flat Laravel, <code>module:tasks</code> + Spatie RBAC)</li><li>Functional differences only: status/priority/complete vs stages/follow-ups</li></ul><p><strong>Backend</strong></p><ul><li>Tables: <code>tasks</code>, <code>task_notes</code>, <code>task_activities</code></li><li><code>TaskService</code>, events/subscriber (audit + assignment mail), tenant API routes</li><li>Permissions: <code>tasks.view|create|update|delete|assign|complete</code></li><li>Pest: <code>tests/Feature/Tenant/Task/TaskTest.php</code></li></ul><p><strong>Frontend</strong></p><ul><li>Tasks list / form dialog / detail drawer; nav gated by module + permission</li><li>Playwright: <code>npm run test:e2e:tasks</code> (<code>--project=tenant</code>)</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/tasks-overview">modules/tasks.md</a> (+ user / developer / production)</li><li><a href="/api/tenant-v1-tasks">api/tenant-v1-tasks.md</a></li></ul><hr><h2 id="leads-reference-module-2026-07-12" tabindex="-1">Leads reference module (2026-07-12) <a class="header-anchor" href="#leads-reference-module-2026-07-12" aria-label="Permalink to &quot;Leads reference module (2026-07-12)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>First product module on the frozen foundation; blueprint for Tasks and later modules</li><li>Flat Laravel layout (no Modules package); <code>module:leads</code> + Spatie RBAC</li><li>Pipeline-ready domain: stages, status workflow, assignment, notes, follow-ups, timeline</li></ul><p><strong>Backend</strong></p><ul><li>Tables: <code>lead_stages</code>, <code>leads</code>, <code>lead_notes</code>, <code>lead_follow_ups</code>, <code>lead_activities</code></li><li><code>LeadService</code>, events/subscriber (audit + mail notifications), tenant API routes</li><li>Permissions: <code>leads.view|create|update|delete|assign</code></li><li>Auth payload includes <code>modules[]</code> for SPA entitlement gating</li><li>Pest: <code>tests/Feature/Tenant/Lead/LeadTest.php</code></li></ul><p><strong>Frontend</strong></p><ul><li>Leads list / form dialog / detail drawer; nav gated by module + permission</li><li>Playwright: <code>npm run test:e2e:leads</code> (<code>--project=tenant</code>)</li></ul><p><strong>Docs</strong></p><ul><li><a href="/user-guide/leads-overview">modules/leads.md</a> (+ user / developer / production)</li><li><a href="/api/tenant-v1-leads">api/tenant-v1-leads.md</a></li></ul><hr><h2 id="platform-freeze-module-development-standard-2026-07-12" tabindex="-1">Platform Freeze &amp; Module Development Standard (2026-07-12) <a class="header-anchor" href="#platform-freeze-module-development-standard-2026-07-12" aria-label="Permalink to &quot;Platform Freeze &amp; Module Development Standard (2026-07-12)&quot;">​</a></h2><p><strong>Architecture</strong></p><ul><li>Platform foundation locked — no redesign of Auth, Tenancy, RBAC, Billing, Marketplace, Settings, or Gateway architecture except critical security / data-integrity / production bugs</li><li>Official <a href="/developer-guide/module-development">Module Development Standard</a>: flat Laravel layout, catalog + <code>module:</code> + Spatie permissions, audit + activity logging, Pest + Playwright, docs DoD</li><li>Cursor rules added in Backend and Frontend (<code>.cursor/rules/platform-freeze.mdc</code>, <code>module-development.mdc</code>)</li><li><strong>Leads</strong> designated as the reference business module; future modules must mirror it</li></ul><p><strong>Docs</strong></p><ul><li><a href="/getting-started/platform-freeze">architecture/platform-freeze.md</a></li><li><a href="/developer-guide/module-development">modules/module-development.md</a> (+ developer / production)</li></ul><hr><h2 id="production-hardening-2026-07-12" tabindex="-1">Production Hardening (2026-07-12) <a class="header-anchor" href="#production-hardening-2026-07-12" aria-label="Permalink to &quot;Production Hardening (2026-07-12)&quot;">​</a></h2><p><strong>Authentication</strong></p><ul><li>Shared tenant <code>/login</code> with Workspace field (slug/domain); <code>/central/login</code> isolated for platform admins</li><li>Server-owned workspace resolution: host → bearer token → <code>workspace</code> input; fail-closed without context</li><li>Email verification enforced for Central and Tenant (<code>verified</code> middleware + SPA verify pages)</li><li>Sanctum token TTL wired to <code>session_lifetime_minutes</code>; Remember Me extends TTL; login lockout after failed attempts</li><li>Removed client tenant persistence (<code>tenantStorage</code> / <code>VITE_DEFAULT_TENANT_DOMAIN</code>)</li></ul><p><strong>Provisioning &amp; tenancy</strong></p><ul><li>Central workspace create always requires an Owner; settings defaults and default role permissions seeded</li><li>Suspended/archived workspaces denied at the API edge</li></ul><p><strong>Security, payments, impersonation, audit</strong></p><ul><li>Tenant setting cache keys namespaced; isolation Pest coverage</li><li>Stripe webhook signature verification + idempotency; payment matching by metadata; PaymentAttempt logging</li><li>Impersonation issues real tenant tokens with timeout, banner, and revoke-on-end</li><li>Broader PlatformAuditService coverage (auth, workspace, users, roles, settings, modules)</li></ul><p><strong>Client / docs</strong></p><ul><li>Currency, date/time, locale, and timezone formatters consume bootstrap settings; SPA idle logout</li><li>Authentication / tenancy docs updated for hybrid resolution and custom-domain readiness</li></ul><hr><h2 id="manual-qa-—-production-readiness-fixes-2026-07-12" tabindex="-1">Manual QA — Production Readiness Fixes (2026-07-12) <a class="header-anchor" href="#manual-qa-—-production-readiness-fixes-2026-07-12" aria-label="Permalink to &quot;Manual QA — Production Readiness Fixes (2026-07-12)&quot;">​</a></h2><p><strong>Backend</strong></p><ul><li><code>DomainRule</code> now accepts platform hostnames including <code>tenant.localhost</code> and <code>tenant.myapp.com</code> (previously required three labels and rejected local domains)</li><li>Central <code>RoleService</code> lists only <code>central-api</code> roles (orphaned <code>tenant-api</code> rows no longer leak into Central Users/Roles UI)</li><li>Central role create always sets <code>guard_name=central-api</code> and scopes uniqueness to that guard</li><li><code>InitializeTenancy</code> re-resolves and switches tenant per request when the domain/header changes</li><li>New <code>tenant.user</code> middleware rejects Sanctum tokens used against a different workspace (<code>EnsureTenantUserBelongsToCurrentTenant</code>)</li><li>Pest: <code>DomainRuleTest</code>, <code>RoleListIsolationTest</code>, <code>TenantTokenIsolationTest</code></li></ul><p><strong>Frontend</strong></p><ul><li>Tenant form shows domain validation errors and uses <code>tenant.localhost</code> placeholder</li><li>Timezone options always include <code>UTC</code> so the default value displays correctly</li></ul><hr><h2 id="tenant-users-roles-permissions-rbac" tabindex="-1">Tenant Users, Roles &amp; Permissions (RBAC) <a class="header-anchor" href="#tenant-users-roles-permissions-rbac" aria-label="Permalink to &quot;Tenant Users, Roles &amp; Permissions (RBAC)&quot;">​</a></h2><p><strong>Backend</strong></p><ul><li>Per-workspace roles via <code>roles.tenant_id</code> (no Spatie teams); permissions remain shared <code>tenant-api</code> vocabulary</li><li>Expanded <code>config/tenant-permissions.php</code> (users, roles, settings, leads, tasks)</li><li>Tenant User + Role APIs: CRUD, suspend, password change, clone, permissions matrix</li><li>Owner (<code>superadmin</code>) bootstrap with full permissions; protected default roles</li><li>Legacy backfill: <code>php artisan tenants:isolate-roles</code> (+ lazy ensure on Users/Roles APIs)</li><li>Pest: user/role CRUD, permission assignment, authorization, workspace isolation, legacy backfill</li></ul><p><strong>Frontend</strong></p><ul><li>Tenant <code>/users</code>, <code>/roles</code>, <code>/roles/matrix</code> reusing Central pages with workspace-aware copy and routes</li><li>Administration nav: Users / Roles (permission-gated)</li><li>Playwright: <code>npm run test:e2e:tenant-rbac</code></li></ul><p><strong>Docs</strong></p><ul><li><code>authorization/tenant-rbac*.md</code> — architecture, user guide, production security</li></ul><hr><h2 id="tenant-branding-configuration" tabindex="-1">Tenant Branding &amp; Configuration <a class="header-anchor" href="#tenant-branding-configuration" aria-label="Permalink to &quot;Tenant Branding &amp; Configuration&quot;">​</a></h2><p><strong>Backend</strong></p><ul><li><code>TenantSettingService</code> resolves workspace settings with hierarchy: tenant override → tenant profile → Central → system default</li><li>Tenant Settings API: list/update, branding upload, test mail, public bootstrap</li><li>SMTP passwords encrypted; runtime mail uses tenant SMTP when <code>mail_host</code> is set, otherwise Central</li><li>Branding assets stored under <code>tenants/{uuid}/branding/…</code></li><li>Permissions: <code>settings.list</code>, <code>settings.update</code></li><li>Pest coverage for resolver + API</li></ul><p><strong>Frontend</strong></p><ul><li>Tenant Settings page (<code>/settings</code>) — General, Branding, Mail with searchable selects, color picker, uploads</li><li>Settings store bootstraps resolved tenant branding when a workspace domain is known</li><li>Playwright: <code>npm run test:e2e:tenant-settings</code></li></ul><p><strong>Docs</strong></p><ul><li><code>settings/tenant-settings*.md</code> — hierarchy, SMTP, storage, security</li></ul><hr><h2 id="tenant-application-ui-foundation" tabindex="-1">Tenant Application UI Foundation <a class="header-anchor" href="#tenant-application-ui-foundation" aria-label="Permalink to &quot;Tenant Application UI Foundation&quot;">​</a></h2><p><strong>Frontend</strong></p><ul><li>Tenant protected routes now use the shared <code>AppLayout</code> shell (Sidebar, Topbar, Breadcrumbs, Command Palette, User Menu)</li><li>Context-aware navigation: <code>centralNavigationGroups</code> vs <code>tenantNavigationGroups</code></li><li>Tenant sidebar: Dashboard, Leads, Tasks, Settings, Profile</li><li>Tenant dashboard redesigned as layout-matched placeholders (welcome, workspace info, modules, activity, quick actions)</li><li>Leads / Tasks / Tenant Settings reserved via <code>PlaceholderPage</code></li><li>Shared Profile page works on both <code>/profile</code> and <code>/central/profile</code></li></ul><p><strong>Docs</strong></p><ul><li>Shared layout developer + tenant user guides</li><li>Architecture note for shared design system / layout reuse</li></ul><hr><h2 id="tenant-authentication-foundation" tabindex="-1">Tenant Authentication Foundation <a class="header-anchor" href="#tenant-authentication-foundation" aria-label="Permalink to &quot;Tenant Authentication Foundation&quot;">​</a></h2><p><strong>Backend</strong></p><ul><li>Self-service registration creates workspace owner, default roles/permissions, and returns a tenant Sanctum token</li><li>Password reset emails point at SPA routes via <code>FRONTEND_URL</code></li><li>Tenant dashboard placeholder returns workspace + installed modules</li><li>Email verification architecture prepared (<code>MustVerifyEmail</code> + signed verify/resend routes)</li><li>Impersonation helper reserved for future tenant token handoff</li></ul><p><strong>Frontend</strong></p><ul><li>Tenant auth at <code>/login</code>, <code>/register</code>, <code>/forgot-password</code>, <code>/reset-password/{token}</code></li><li>Central auth moved under <code>/central/*</code> with isolated token storage</li><li>Tenant dashboard placeholder for auth/impersonation verification</li></ul><p><strong>Docs / tests</strong></p><ul><li>Authentication developer, user, and production guides</li><li>Pest coverage for tenant auth; Playwright auth suites updated for <code>/central</code> + tenant flows</li></ul><hr><h2 id="features-layer-removed-—-module-licensing-spatie-authorization" tabindex="-1">Features layer removed — module licensing + Spatie authorization <a class="header-anchor" href="#features-layer-removed-—-module-licensing-spatie-authorization" aria-label="Permalink to &quot;Features layer removed — module licensing + Spatie authorization&quot;">​</a></h2><p>Licensing and authorization are fully decoupled.</p><p><strong>Architecture</strong></p><ul><li>Removed Features catalog (model, API, UI, entitlements <code>features[]</code>, <code>features.*</code> permissions, <code>features</code> table)</li><li>Modules remain pure licensing products via <code>workspace_module_subscriptions</code></li><li>User access stays on Spatie Roles &amp; Permissions</li><li>Tenant gating: <code>module:{slug}</code> (licensing) then <code>can:{permission}</code> (authorization)</li><li>Entitlements payload is now <code>{ core, modules }</code> only</li><li>Default modules unchanged: Leads + Tasks (free, included, non-removable)</li></ul><p><strong>Backend</strong></p><ul><li><code>EnsureModule</code> middleware replaces <code>EnsureModuleFeature</code></li><li>Catalog seeder no longer creates Feature rows</li><li>Migration drops <code>features</code> table</li></ul><p><strong>Frontend</strong></p><ul><li>Features admin page, nav, API client, and Playwright suite removed</li><li>Marketplace / tenant details no longer show feature badges</li></ul><hr><h2 id="payment-gateway-management" tabindex="-1">Payment Gateway Management <a class="header-anchor" href="#payment-gateway-management" aria-label="Permalink to &quot;Payment Gateway Management&quot;">​</a></h2><p>Gateway-agnostic payment provider management for Central Billing.</p><p><strong>Architecture</strong></p><ul><li>Billing Engine talks only to <code>PaymentGatewayInterface</code> via <code>GatewayManager</code></li><li>Stripe/Cashier isolated inside <code>StripeGateway</code>; arch tests enforce isolation</li><li>Admin APIs for enable/disable/default/config/mode/test/webhooks/logs/capabilities</li><li>Encrypted gateway credentials; secrets never returned to the frontend</li><li>Generic webhook ingress <code>POST /webhooks/gateways/{code}</code> + Cashier Stripe route</li></ul><p><strong>Schema</strong></p><ul><li>Expanded <code>payment_gateways</code> (mode, encrypted config, webhook/test metadata)</li><li>Added <code>payment_attempts</code>, <code>gateway_logs</code>, <code>webhook_logs</code></li><li><code>payment_methods</code> remains the workspace preferred-method store</li></ul><p><strong>Frontend</strong></p><ul><li>Top-level <strong>Billing</strong> nav: Dashboard, Invoices, Payments, Transactions, Refunds, Payment Methods, Payment Gateways, Coupons, Taxes, Billing Logs</li><li>Full Payment Gateways management UI (configure Stripe fields, sandbox/live, test connection, logs)</li></ul><p><strong>Docs</strong></p><ul><li><code>billing/payment-gateways.md</code> (+ developer/user/production/webhooks guides)</li><li>Updated <code>billing-engine.md</code> and <code>stripe-cashier.md</code></li></ul><hr><h2 id="central-application-settings-refactor" tabindex="-1">Central Application Settings refactor <a class="header-anchor" href="#central-application-settings-refactor" aria-label="Permalink to &quot;Central Application Settings refactor&quot;">​</a></h2><p>Rebuilt system settings so every key is validated and consumed at runtime.</p><p><strong>Backend</strong></p><ul><li>Expanded mail/security/branding/localization settings; removed unused placeholders (<code>primary_color</code>, feature-flag duplicates, display-only queue/disk keys)</li><li>Runtime config overlay (app name, timezone, locale, session lifetime, mail From/SMTP, Cashier currency)</li><li>Encrypted <code>mail_password</code>, branding file uploads, test-mail endpoint</li><li>Public bootstrap + self-service workspace registration gated by <code>registration_enabled</code></li><li>Tenant-only maintenance middleware (<code>tenant.available</code>); Central stays fully operational</li><li>Centralized <code>PasswordRule</code> / <code>Password::defaults()</code> from security settings</li><li>Support email + company name injected into tenant-facing auth emails</li></ul><p><strong>Frontend</strong></p><ul><li>Settings UI rebuilt with SearchableSelect for timezone/locale/currency/formats</li><li>App title, sidebar, button color CSS vars, favicon/logo from public settings</li><li>App-wide date/time helpers; registration-closed and branded maintenance pages</li></ul><p><strong>Tests / docs</strong></p><ul><li>Expanded Pest settings suite; Playwright settings coverage for registration-closed + maintenance copy</li><li>Added Settings user / developer / production guides under <code>settings/</code></li><li>Updated API, admin UI, database, and testing docs</li></ul><hr><h2 id="tenant-form-cleanup" tabindex="-1">Tenant form cleanup <a class="header-anchor" href="#tenant-form-cleanup" aria-label="Permalink to &quot;Tenant form cleanup&quot;">​</a></h2><p>Removed <code>owner_id</code> and <code>address</code> from the <code>tenants</code> schema and admin UI. Timezone, currency, country, and locale are searchable selects. Logo is an image upload (<code>logo</code> file field → <code>logo_path</code> / <code>logo_url</code>).</p><hr><h2 id="central-qa-stabilization-playwright" tabindex="-1">Central QA stabilization (Playwright) <a class="header-anchor" href="#central-qa-stabilization-playwright" aria-label="Permalink to &quot;Central QA stabilization (Playwright)&quot;">​</a></h2><p>Stabilized the Central Application with a full Playwright pass before further Tenant Application work.</p><p><strong>Fixed</strong></p><ul><li>Logout now revokes only the current Sanctum token (was deleting all tokens and breaking parallel E2E sessions)</li><li>Dashboard growth/revenue series API keys aligned to frontend contract (<code>count</code>, <code>amount</code>) — removed chart <code>NaN</code> display</li><li>Settings E2E opens the Billing tab before toggling trial flags</li><li>Auth greeting assertion matches time-based welcome copy</li><li>Roles cleanup searches before deleting the original role after clone</li></ul><p><strong>Added (Playwright)</strong></p><ul><li>Module suites: marketplace, billing, impersonation, permissions, profile</li><li>Per-module npm scripts (<code>test:e2e:marketplace</code>, <code>test:e2e:billing</code>, …)</li><li>Smoke coverage for Marketplace route</li></ul><p><strong>Docs</strong></p><ul><li>Updated <code>testing/playwright.md</code> and Frontend <code>docs/testing/PLAYWRIGHT.md</code></li></ul><hr><h2 id="modular-foundation-complete-phases-1–6" tabindex="-1">Modular foundation complete (Phases 1–6) <a class="header-anchor" href="#modular-foundation-complete-phases-1–6" aria-label="Permalink to &quot;Modular foundation complete (Phases 1–6)&quot;">​</a></h2><p>Delivered marketplace APIs, Billing Engine, impersonation, and the financial ledger on top of the module-licensing foundation.</p><p><strong>Added</strong></p><ul><li>Marketplace: <code>GET /marketplace/modules</code>, <code>GET /marketplace/modules/{module}</code> (published catalog, dependency hints, <code>?tenant_id=</code> install state)</li><li>Module subscriptions: <code>GET /module-subscriptions</code>, show, <code>POST …/cancel</code>, <code>POST …/deactivate</code>; <code>POST /tenants/{tenant}/modules</code> (install)</li><li>Billing Engine (<code>BillingEngine</code>, <code>GatewayManager</code>, <code>ManualGateway</code>, <code>StripeGateway</code>, <code>ProrationCalculator</code>)</li><li>Consolidated billing: <code>php artisan billing:run-consolidated</code> (scheduled daily); one invoice per workspace billing cycle for all billable active modules</li><li>Financial ledger tables + read APIs: <code>invoices</code>, <code>invoice_items</code>, <code>payments</code>, <code>payment_transactions</code>, <code>payment_gateways</code>, <code>payment_methods</code>, <code>billing_addresses</code>, <code>taxes</code>, <code>coupons</code>, <code>refunds</code>, <code>credit_notes</code></li><li>Impersonation: <code>impersonation_sessions</code> table; <code>POST /tenants/{tenant}/impersonate</code>, <code>POST /impersonation/{id}/end</code></li><li>Permissions: <code>module-subscriptions.*</code>, <code>invoices.*</code>, <code>payments.*</code>, <code>impersonation.*</code></li></ul><p><strong>Admin UI</strong></p><ul><li>Marketplace browse screen</li><li>Tenant details tabs: Overview | Modules | Billing; impersonate action with reason prompt</li><li>Module catalog form retains marketplace pricing fields</li></ul><p><strong>Unchanged from prior entry</strong></p><ul><li>Plans removed; Leads + Tasks remain default-included, non-billable</li><li><code>workspace_module_subscriptions</code> is licensing SoT; Cashier/Stripe is a gateway driver only</li></ul><hr><h2 id="module-licensing-foundation-plans-removed" tabindex="-1">Module licensing foundation (Plans removed) <a class="header-anchor" href="#module-licensing-foundation-plans-removed" aria-label="Permalink to &quot;Module licensing foundation (Plans removed)&quot;">​</a></h2><p>Replaced plan-based licensing with workspace module subscriptions.</p><p><strong>Removed</strong></p><ul><li>Plans, plan modules/features/limits, limit definitions, usage counters</li><li>Plan-based <code>tenant_subscriptions</code> / <code>subscription_events</code></li><li>Central API/UI for plans, limits, and tenant-subscriptions</li><li><code>default_plan_id</code> system setting</li></ul><p><strong>Added</strong></p><ul><li>Module catalog fields: <code>uuid</code>, pricing, <code>trial_days</code>, <code>version</code>, <code>status</code>, <code>is_default_included</code>, <code>is_billable</code>, Stripe price IDs</li><li><code>module_categories</code>, <code>module_dependencies</code></li><li><code>workspace_module_subscriptions</code> + history</li><li>Workspace billing profile: <code>billing_anchor_day</code>, <code>billing_cycle</code>, <code>proration_mode</code>, <code>next_billing_at</code></li><li><code>EntitlementService</code> + <code>GET /tenants/{tenant}/entitlements</code></li><li><code>config/core-platform.php</code> for always-on platform capabilities</li><li>Catalog seed: <strong>Leads</strong> and <strong>Tasks</strong> only (included, non-billable)</li><li>New workspaces auto-install Leads + Tasks (<code>source=included</code>, not cancellable by owners)</li></ul><hr><h2 id="prior-central-saas-platform-completion" tabindex="-1">Prior: Central SaaS Platform completion <a class="header-anchor" href="#prior-central-saas-platform-completion" aria-label="Permalink to &quot;Prior: Central SaaS Platform completion&quot;">​</a></h2><p>See git history for the earlier plan-based Central Platform delivery notes (tenants, users, roles, Cashier scaffolding, dashboard). That licensing model has been superseded.</p>',717))])}const v=n(l,[["render",c]]);export{f as __pageData,v as default};
